/**
 * Guard overlay: stamp each guarded transition edge with its evaluated truth
 * (`guard_value`) so the renderer can draw a ✓/✗/? badge + styling. Keyed by
 * edge id — the same id `applyStateOverlay` uses for `is_fired` — so guard
 * badges and the fired-transition animation align. Returns a new model; does
 * not mutate.
 */
import type { ViewModel, GuardEval } from "./types";

export function applyGuardOverlay(model: ViewModel, guards: GuardEval[]): ViewModel {
  const byEdge = new Map(guards.map(g => [g.edgeId, g.value]));
  return {
    ...model,
    edges: model.edges.map(e =>
      byEdge.has(e.id) ? { ...e, guard_value: byEdge.get(e.id) } : e
    ),
  };
}
