import React, { useEffect, useState } from "react";

/**
 * Progress cover that stays invisible for one second. Fast builds/layouts
 * therefore never flash a spinner, while slow work has an explanation waiting
 * in a frame the browser can paint before ELK occupies the UI thread.
 */
export function LoadingOverlay({ message, delayMs = 1000 }: { message: string; delayMs?: number }) {
  const [visible, setVisible] = useState(delayMs === 0);

  useEffect(() => {
    if (delayMs === 0) {
      setVisible(true);
      return;
    }
    setVisible(false);
    const id = setTimeout(() => setVisible(true), delayMs);
    return () => clearTimeout(id);
  }, [delayMs, message]);

  if (!visible) return null;
  return (
    <div className="smlml-loading-overlay" role="status" aria-live="polite">
      <div className="smlml-loading-spinner" aria-hidden="true" />
      <div>{message}</div>
    </div>
  );
}
