/**
 * Cursor → diagram-target resolution for the browser editor.
 *
 * The logic itself lives in the shared app at
 * `editors/smlml-vscode/src/views/app/resolve-target.ts`, which
 * `editors/smlml-vscode/src/views/panel.ts` also uses. It used to be duplicated
 * here as a hand-kept port, which is how the two came to disagree: only one of
 * them needed teaching that a node's `range` is its declaration NAME span, so
 * a cursor on an attribute is covered by no node range at all and matches only
 * that attribute's compartment entry.
 *
 * This module is now the browser-side re-export, so there is one implementation
 * and one test suite behind it.
 */

export {
  normalizeRange,
  resolveNodeAtPosition,
  resolveTargetAtPosition,
} from "../../../smlml-vscode/src/views/app/resolve-target";
export type {
  DiagramTarget,
  TargetEntry,
  TargetNode,
  TargetNode as NodeRange,
} from "../../../smlml-vscode/src/views/app/resolve-target";
