/**
 * AST JSON export/import for the web editor toolbar.
 *
 * Mirrors the VS Code commands (`editors/smlml-vscode/src/ast-commands-util.ts`):
 * all model work happens in the wasm LSP via `smlml/exportAst` / `smlml/importAst`,
 * and this module only moves bytes and reports outcomes. The two front-ends share
 * no module (deliberate — separate build graphs), so this is a deliberate
 * duplicate of that file's response shapes and error-rendering behavior, kept in
 * sync by hand rather than by import.
 */
import { download } from "../workspace/zip";

/**
 * Every `kind` the server's `smlml/exportAst` and `smlml/importAst` handlers
 * can emit (`crates/smlml-lsp/src/handlers/editor_ast.rs`).
 *
 * Export-side: `unresolved` (preflight gate), `missing-dependency`,
 * `ambiguous-root-package`, `language-mismatch`, `no-roots`, `parse`,
 * `not-found`. Import-side: `deserialize`, `unparse`, and `no-roots` again
 * (shared: it means the same thing to the user on both sides). The union is
 * kept exhaustive so a new server-side `kind` fails TypeScript compilation
 * here rather than being silently rendered as generic text.
 *
 * The last two are CLIENT-SYNTHESIZED — the server never sends them.
 * `unsupported` covers a server that answered `null` or a non-object (the LSP
 * dispatch's catch-all arm for an unknown request, i.e. an older server);
 * `transport` covers `sendRequest` itself rejecting.
 */
export type AstErrorKind =
  | "unresolved"
  | "missing-dependency"
  | "ambiguous-root-package"
  | "language-mismatch"
  | "no-roots"
  | "parse"
  | "not-found"
  | "deserialize"
  | "unparse"
  | "unsupported"
  | "transport";

export interface AstErrorResponse {
  ok: false;
  kind: AstErrorKind;
  message: string;
  details: string[];
}

export interface ExportAstResponse {
  ok: true;
  json: string;
  suggestedName: string;
  contributingFiles: string[];
}

export interface ImportAstResponse {
  ok: true;
  files: { name: string; text: string }[];
  skipped: string[];
  incomplete: string[];
}

export type AstResponse = ExportAstResponse | ImportAstResponse | AstErrorResponse;

/** Error text: the message, with any details indented beneath it. */
export function formatAstError(res: AstErrorResponse): string {
  if (res.details.length === 0) return res.message;
  return [res.message, ...res.details.map((d) => `  ${d}`)].join("\n");
}

/**
 * Turn a raw `sendRequest` result into either the expected success payload or
 * an `AstErrorResponse` — never anything else.
 *
 * The server's own failures already arrive as `{ok: false, ...}`. What this
 * adds is the case the server does not model: a server that has never heard of
 * `smlml/exportAst` answers `null` (the LSP dispatch's `_ =>` arm), and
 * `if (!res.ok)` on `null` throws a `TypeError` inside the callback's floating
 * async IIFE, which reaches nobody — not even the log panel.
 *
 * Mirrors `editors/smlml-vscode/src/ast-commands-util.ts`; the two front-ends
 * share no module by design and are kept in sync by hand.
 */
export function coerceAstResponse<T extends { ok: true }>(
  method: string,
  raw: unknown
): T | AstErrorResponse {
  if (typeof raw !== "object" || raw === null || !("ok" in raw)) {
    return {
      ok: false,
      kind: "unsupported",
      message:
        "This language server does not support AST import/export — update the smlml language server.",
      details: [`${method} returned ${raw === null ? "null" : typeof raw}`],
    };
  }
  return raw as T | AstErrorResponse;
}

/** An `AstErrorResponse` for a rejected `sendRequest` (crash, dropped worker). */
export function transportAstResponse(method: string, err: unknown): AstErrorResponse {
  const detail = err instanceof Error ? err.message : String(err);
  return {
    ok: false,
    kind: "transport",
    message: `The language server did not answer ${method}.`,
    details: [detail],
  };
}

/** Send the exported JSON to the browser's downloads. */
export function deliverExport(res: ExportAstResponse): void {
  download(new Blob([res.json], { type: "application/json" }), res.suggestedName);
}
