/**
 * Floating edge — connects to the *border* of each endpoint node on the line
 * toward the other endpoint, instead of to a fixed Top/Bottom handle.
 *
 * Why: with fixed handles every edge entering a node converges on one point
 * (top-centre) and leaves another (bottom-centre), so multi-edge nodes look
 * pinched and the connector is forced to stand a long way off the box before it
 * can bend. Floating attachment lets the several relations on a node spread
 * naturally around its perimeter, attaches annotation links right next to their
 * element, and removes the standoff (the line meets the box exactly where it
 * points).
 *
 * The border-intersection maths is the canonical React Flow "floating edges"
 * algorithm (treats the node as a rectangle and finds where the centre-to-centre
 * line crosses it).
 */

import React from "react";
import { BaseEdge, useInternalNode, type EdgeProps, type EdgeTypes } from "@xyflow/react";
import { RoutedEdge } from "./RoutedEdge";
import { computeFloatingPath } from "./edgeGeometry";
import { EdgeLabel } from "./EdgeLabel";
import { markerShaftInset } from "./EdgeMarkers";

// ── Component ─────────────────────────────────────────────────────────────────

export function FloatingEdge(props: EdgeProps) {
  const { id, source, target, markerStart, markerEnd, style, label, data } = props;
  const sourceNode = useInternalNode(source);
  const targetNode = useInternalNode(target);
  if (!sourceNode || !targetNode) return null;

  const routing = (data?.routing as string | undefined) ?? "smoothstep";
  const [carrierPath] = computeFloatingPath(sourceNode, targetNode, routing);
  const [path, labelX, labelY] = computeFloatingPath(
    sourceNode,
    targetNode,
    routing,
    markerShaftInset(markerStart, true),
    markerShaftInset(markerEnd, false),
  );

  return (
    <>
      <BaseEdge id={id} path={path} style={style} />
      {(markerStart || markerEnd) && (
        <path
          d={carrierPath}
          fill="none"
          stroke="transparent"
          markerStart={markerStart}
          markerEnd={markerEnd}
          pointerEvents="none"
        />
      )}
      <EdgeLabel edgeId={id} label={label} x={labelX} y={labelY} />
    </>
  );
}

/**
 * Shared `edgeTypes` map for every wired view — all four (`TreeFlowView`,
 * `InterconnectionFlowView`, `ActionFlowView`, `StateFlowView`) register the
 * same edge types, so one export replaces four byte-identical `const
 * EDGE_TYPES` copies. `routed` draws ELK's own computed route (used when
 * `layoutViewModel` found one); `floating` is the border-intersection
 * fallback for edges ELK did not route.
 */
export const EDGE_TYPES: EdgeTypes = {
  floating: FloatingEdge,
  routed: RoutedEdge,
};
