import React from "react";
import { Handle, Position, type NodeProps } from "@xyflow/react";
import { formOf } from "./form";

export function ActionDecisionNode({ data }: NodeProps) {
  // Server-classified family, authoritative and shared with the CLI painters;
  // "default" is the wire's own fallback for a node with no family tint.
  const family = (data.family as string | undefined) ?? "default";
  // The wrapper is the bounding box `CTRL_W`/`CTRL_H` reserve; the square
  // inside it is rotated 45°, so the box has to hold that square's diagonal
  // (16 × √2 ≈ 22.6) and the 4px inset centres it.
  return (
    <div
      className={`fam-${family}`}
      data-form={formOf(data)}
      style={{ position: "relative", width: 24, height: 24 }}
    >
      <Handle type="target" position={Position.Top} />
      <div
        className="smlml-action-decision"
        style={{ position: "absolute", top: 4, left: 4 }}
      />
      <Handle type="source" position={Position.Bottom} />
    </div>
  );
}
