/**
 * Shared edge-label rendering — identical between `FloatingEdge` and
 * `RoutedEdge` (both drop the label into React Flow's `EdgeLabelRenderer`
 * portal, centred on a given point). Extracted so the two edge components
 * don't carry byte-identical copies of this block.
 */

import React from "react";
import { EdgeLabelRenderer } from "@xyflow/react";

export function EdgeLabel({ edgeId, label, x, y }: { edgeId?: string; label: React.ReactNode; x: number; y: number }) {
  if (!label) return null;
  // A caption the pilot folded arrives as one string with real newlines
  // (`layout.ts`'s `unfoldPilotLineBreaks`). Emit one element per line rather
  // than leaning on `white-space`, so the PAINTED line count equals the count
  // `layout.ts` measured and handed ELK — by construction, not by two
  // estimators agreeing. That is the same rule `text-metrics.ts` states for
  // wrapped node text.
  const body =
    typeof label === "string" && label.includes("\n")
      ? label.split("\n").map((line, i) => (
          <div key={i} style={{ whiteSpace: "pre" }}>
            {line}
          </div>
        ))
      : label;
  return (
    <EdgeLabelRenderer>
      <div
        className="smlml-edge-label"
        // The label is portalled out of the edge's own SVG group, so nothing
        // else ties the two together. The conformance probe needs the join to
        // score a label's TEXT against the edge the oracle declares it on
        // (`assets/conformance/visualization/scripts/layout/probe.mjs`).
        data-edge-id={edgeId}
        style={{
          position: "absolute",
          transform: `translate(-50%, -50%) translate(${x}px, ${y}px)`,
          pointerEvents: "all",
        }}
      >
        {body}
      </div>
    </EdgeLabelRenderer>
  );
}
