/**
 * Generic right-click context menu.  Renders a positioned list at (x, y),
 * closes on outside click / Esc / scroll, and invokes the chosen action.
 * No domain knowledge — callers supply labelled actions.
 */

export interface MenuItem {
  label: string;
  action: () => void;
  disabled?: boolean;
}

let openMenu: HTMLElement | null = null;

function close(): void {
  openMenu?.remove();
  openMenu = null;
  document.removeEventListener("mousedown", onDocDown, true);
  document.removeEventListener("keydown", onKey, true);
  window.removeEventListener("scroll", close, true);
}

function onDocDown(e: MouseEvent): void {
  if (openMenu && !openMenu.contains(e.target as Node)) close();
}

function onKey(e: KeyboardEvent): void {
  if (e.key === "Escape") close();
}

export function showContextMenu(x: number, y: number, items: MenuItem[]): void {
  close();
  const menu = document.createElement("div");
  menu.className = "ctx-menu";
  for (const item of items) {
    const row = document.createElement("button");
    row.className = "ctx-item";
    row.textContent = item.label;
    row.disabled = item.disabled ?? false;
    row.addEventListener("click", () => {
      close();
      item.action();
    });
    menu.appendChild(row);
  }
  menu.style.left = `${x}px`;
  menu.style.top = `${y}px`;
  document.body.appendChild(menu);
  openMenu = menu;

  // Nudge back on-screen if it overflows.
  const r = menu.getBoundingClientRect();
  if (r.right > window.innerWidth) menu.style.left = `${Math.max(0, window.innerWidth - r.width)}px`;
  if (r.bottom > window.innerHeight) menu.style.top = `${Math.max(0, window.innerHeight - r.height)}px`;

  document.addEventListener("mousedown", onDocDown, true);
  document.addEventListener("keydown", onKey, true);
  window.addEventListener("scroll", close, true);
}
