import { createContext, useContext } from "react";
import type { SourceRange } from "./types";

export type NavigateFn = (uri: string, range: SourceRange) => void;

export const NavigateContext = createContext<{ navigate: NavigateFn; uri: string } | null>(null);

export function useNavigate(): NavigateFn | undefined {
  const ctx = useContext(NavigateContext);
  return ctx
    ? (uri: string, range: SourceRange) => ctx.navigate(uri || ctx.uri, range)
    : undefined;
}
