/**
 * Free-text search over a view model.
 *
 * "Everything shown" is the contract: a reader searching a diagram is looking
 * for a name they can see, and every visible string is fair game — a node's
 * label and stereotype, each compartment row, and an edge's label, stereotype
 * and transition clauses. Anything painted but not searched reads as a bug to
 * whoever is typing.
 *
 * The result is deliberately structural rather than a flat id list: the caller
 * highlights matched rows individually and frames matched nodes, and needs to
 * tell those apart. An edge match contributes its endpoints to the framing set
 * so that "find the flow carrying Telemetry" puts both ends on screen.
 */

import type { ViewModel, ViewNode, ViewEdge } from "./types";

export interface SearchMatches {
  /** Nodes to highlight and to frame. */
  nodes: Set<string>;
  /** Edges to highlight. */
  edges: Set<string>;
  /** Per node, the indices of the compartment rows that matched. */
  rows: Map<string, Set<number>>;
  /** Total matched things, for the "n results" readout. */
  count: number;
}

export const NO_MATCHES: SearchMatches = {
  nodes: new Set(),
  edges: new Set(),
  rows: new Map(),
  count: 0,
};

/** Case-insensitive substring test, tolerant of absent fields. */
function hit(haystack: string | undefined | null, needle: string): boolean {
  return !!haystack && haystack.toLowerCase().includes(needle);
}

/** Every searchable string a node paints, excluding its compartment rows. */
function nodeText(n: ViewNode): Array<string | undefined> {
  return [n.label, n.stereotype, n.id];
}

/** Every searchable string an edge paints. */
function edgeText(e: ViewEdge): Array<string | undefined> {
  return [e.label, e.stereotype, e.trigger, e.guard, e.effect, e.multiplicity];
}

/**
 * Everything in `model` matching `query`.
 *
 * A blank or whitespace-only query matches nothing rather than everything:
 * highlighting the entire diagram and framing all of it is indistinguishable
 * from having no search at all, and clearing the box should restore the view.
 */
export function searchViewModel(model: ViewModel, query: string): SearchMatches {
  const needle = query.trim().toLowerCase();
  if (!needle) return NO_MATCHES;

  const nodes = new Set<string>();
  const edges = new Set<string>();
  const rows = new Map<string, Set<number>>();

  for (const n of model.nodes) {
    let matched = nodeText(n).some(t => hit(t, needle));
    n.compartments?.forEach((c, i) => {
      if (!hit(c.label, needle)) return;
      matched = true;
      const set = rows.get(n.id) ?? new Set<number>();
      set.add(i);
      rows.set(n.id, set);
    });
    if (matched) nodes.add(n.id);
  }

  for (const e of model.edges) {
    if (!edgeText(e).some(t => hit(t, needle))) continue;
    edges.add(e.id);
    // Frame what the edge connects, so a matched relation is readable rather
    // than a highlighted line running off both sides of the viewport.
    nodes.add(e.source);
    nodes.add(e.target);
  }

  let count = edges.size;
  for (const id of nodes) count += rows.get(id)?.size ?? 1;
  return { nodes, edges, rows, count };
}
