/**
 * Layout failure banner — shown over a diagram panel when `layoutViewModel`
 * reports `layoutFailed` (ELK rejected the graph and a fallback grid is
 * shown instead). Renders nothing when there is no error.
 *
 * Positioned `absolute` over the top of the panel, with `pointerEvents: none`
 * on the wrapping container so it never swallows canvas interaction — it is
 * purely informational, nothing in it is clickable.
 */
import React from "react";

export function LayoutFailureBanner({ error }: { error: Error | null | undefined }) {
  if (!error) return null;

  return (
    <div
      style={{
        position: "absolute",
        top: 0,
        left: 0,
        right: 0,
        zIndex: 10,
        display: "flex",
        justifyContent: "center",
        pointerEvents: "none",
      }}
    >
      <div
        style={{
          marginTop: 6,
          padding: "4px 10px",
          maxWidth: "90%",
          borderRadius: 3,
          fontSize: 11,
          // `--vscode-inputValidation-warning*` is not defined in
          // editors/smlml-web/src/styles/theme.css (unlike `--vscode-focusBorder`
          // / `--vscode-descriptionForeground` / `--vscode-panel-border`, which
          // every other component here uses). It works anyway — VS Code injects
          // the full palette at runtime, and the hardcoded fallbacks below cover
          // the standalone smlml-web demo — but it's kept deliberately: this is
          // the one banner in the app signalling a real warning/error condition,
          // and the neighbouring set has no warning-colored member to borrow.
          background: "var(--vscode-inputValidation-warningBackground, #352a05)",
          border: "1px solid var(--vscode-inputValidation-warningBorder, #cca700)",
          color: "var(--vscode-inputValidation-warningForeground, #d4d4d4)",
        }}
      >
        Layout engine rejected this diagram — showing a fallback grid. {error.message}
      </div>
    </div>
  );
}
