/**
 * Problems panel — renders LSP diagnostics grouped by file.  Clicking a row
 * navigates the editor to the diagnostic's start position.
 */

import type { Diagnostic } from "../types.ts";

export interface ProblemFile {
  uri: string;
  path: string;
  diagnostics: Diagnostic[];
}

export interface ProblemsCallbacks {
  onNavigate(uri: string, line: number, character: number): void;
}

export class ProblemsPanel {
  private lastKey = "";

  constructor(
    private readonly container: HTMLElement,
    private readonly cbs: ProblemsCallbacks
  ) {}

  /** Render all files that currently have diagnostics. */
  render(files: ProblemFile[]): void {
    const key = files
      .filter((f) => f.diagnostics.length > 0)
      .map((f) => f.uri + ":" + f.diagnostics.map((d) => `${d.severity}@${d.range.start.line}:${d.range.start.character}:${d.message}`).join("|"))
      .join(";");
    if (key === this.lastKey) return;
    this.lastKey = key;
    this.container.innerHTML = "";
    const withDiags = files.filter((f) => f.diagnostics.length > 0);
    if (withDiags.length === 0) {
      const empty = document.createElement("div");
      empty.className = "dock-empty";
      empty.textContent = "No problems detected.";
      this.container.appendChild(empty);
      return;
    }

    for (const file of withDiags) {
      const head = document.createElement("div");
      head.className = "prob-file";
      head.textContent = file.path + " ";
      const n = document.createElement("span");
      n.className = "prob-n";
      n.textContent = `(${file.diagnostics.length})`;
      head.appendChild(n);
      this.container.appendChild(head);

      for (const d of file.diagnostics) {
        const row = document.createElement("div");
        row.className = "problem" + (d.severity === 1 ? " err" : "");
        const ico = document.createElement("span");
        ico.className = "ico";
        const msg = document.createElement("span");
        msg.className = "msg";
        msg.textContent = d.message;
        const loc = document.createElement("span");
        loc.className = "loc";
        loc.textContent = `${file.path} ${d.range.start.line + 1}:${d.range.start.character + 1}`;
        const copyBtn = document.createElement("button");
        copyBtn.className = "prob-copy";
        copyBtn.title = "Copy to clipboard";
        copyBtn.innerHTML =
          `<svg viewBox="0 0 16 16" fill="currentColor"><path d="M4 2h7l3 3v9H4V2zm1 1v10h8V6h-3V3H5zm6 .7V5h1.3L11 2.7z"/><path d="M2 4v10h8v1H1V4h1z"/></svg>`;
        copyBtn.addEventListener("click", (e) => {
          e.stopPropagation();
          const text = `${file.path}:${d.range.start.line + 1}:${d.range.start.character + 1} — ${d.message}`;
          navigator.clipboard.writeText(text).catch(() => {});
        });
        row.append(ico, msg, loc, copyBtn);
        row.addEventListener("click", () =>
          this.cbs.onNavigate(file.uri, d.range.start.line, d.range.start.character)
        );
        this.container.appendChild(row);
      }
    }
  }
}
