/**
 * Pure cursor → diagram-target resolution, shared by both editors.
 *
 * Given a 0-based (line, UTF-16 character) cursor position, find the tightest
 * thing in the view model whose range contains it. That is not always a node:
 * a node's `range` is its declaration NAME span (`lower::enrich` fills it from
 * `DeclRecord::name_span`), so a cursor on `mass` inside `part def Payload`
 * lands on no node at all — the only range covering it belongs to the
 * `mass: MassValue` compartment entry. Resolving nodes alone therefore made
 * every attribute in the file unreachable from the editor.
 *
 * A compartment hit wins over its own node whenever both contain the cursor,
 * since the entry is strictly the tighter span.
 */

import type { SourceRange } from "./types";

export interface TargetEntry {
  range?: SourceRange;
}

export interface TargetNode {
  id: string;
  range?: SourceRange;
  compartments?: TargetEntry[];
}

/** What the cursor is pointing at: a node, optionally one of its rows. */
export interface DiagramTarget {
  nodeId: string;
  /** Index into that node's `compartments`, when a row is the tighter hit. */
  compartment?: number;
}

/**
 * Normalize a view-model range to the camelCase `SourceRange` shape.
 *
 * `smlml_view::SourceRange` serializes camelCase (`startLine` / `startCol` /
 * `endLine` / `endCol`) — the contract in `types.ts`. This stays tolerant of
 * the snake_case form as a compatibility boundary so a backend serialization
 * drift can't silently break node-click navigation or cursor→node highlighting
 * again.
 */
export function normalizeRange(raw: unknown): SourceRange | undefined {
  if (!raw || typeof raw !== "object") return undefined;
  const r = raw as Record<string, number | undefined>;
  const startLine = r.startLine ?? r.start_line;
  const startCol = r.startCol ?? r.start_col;
  const endLine = r.endLine ?? r.end_line;
  const endCol = r.endCol ?? r.end_col;
  if (startLine == null || startCol == null || endLine == null || endCol == null) return undefined;
  return { startLine, startCol, endLine, endCol };
}

function contains(r: SourceRange, line: number, character: number): boolean {
  return (
    (r.startLine < line || (r.startLine === line && r.startCol <= character)) &&
    (r.endLine > line || (r.endLine === line && r.endCol >= character))
  );
}

/** Smaller is tighter. Line span dominates, column span breaks the tie. */
function area(r: SourceRange): number {
  return (r.endLine - r.startLine) * 10000 + (r.endCol - r.startCol);
}

/** The tightest node-or-compartment-entry whose range contains the cursor. */
export function resolveTargetAtPosition(
  nodes: TargetNode[],
  line: number,
  character: number
): DiagramTarget | undefined {
  let best: { target: DiagramTarget; area: number } | undefined;
  const consider = (target: DiagramTarget, r: SourceRange | undefined) => {
    if (!r || !contains(r, line, character)) return;
    const a = area(r);
    // `<` not `<=`: with equal spans the node, considered first, wins — a
    // compartment entry only takes precedence by being strictly tighter.
    if (best === undefined || a < best.area) best = { target, area: a };
  };
  for (const node of nodes) {
    consider({ nodeId: node.id }, node.range);
    node.compartments?.forEach((entry, i) => {
      consider({ nodeId: node.id, compartment: i }, entry.range);
    });
  }
  return best?.target;
}

/**
 * The tightest containing node id, ignoring compartment entries.
 *
 * Kept for callers that can only act on a whole node.
 */
export function resolveNodeAtPosition(
  nodes: TargetNode[],
  line: number,
  character: number
): string | undefined {
  return resolveTargetAtPosition(
    nodes.map(n => ({ id: n.id, range: n.range })),
    line,
    character
  )?.nodeId;
}
