/**
 * ViewHost — framework-free orchestration of the diagram pane.
 *
 * This is a behavior-port of editors/smlml-vscode/src/views/panel.ts
 * (`_refresh` / `_resolveNodeAtPosition` / `_onWebviewMessage` /
 * `_handleSimStep`), driven through the LSP gateway + a CodeMirror editor bridge
 * instead of VS Code APIs.  The duplication with panel.ts is intentional and
 * temporary: when the shared `smlml-view-core` package is extracted (existing
 * plan W1/W2), both consumers collapse onto one ViewHostCore and this file goes
 * away.  Keep the message protocol identical to panel.ts so the reused React app
 * needs no changes.
 */

import type {
  ExtToWebviewMsg,
  GuardEval,
  SourceRange,
  ViewKind,
  WebviewToExtMsg,
} from "../../../smlml-vscode/src/views/app/types";
import { ExpansionState } from "../../../smlml-vscode/src/views/app/expansion";
import { conceptFor } from "../../../smlml-vscode/src/views/app/legend-concepts";
import { normalizeRange, resolveTargetAtPosition, type NodeRange } from "./resolve-node.ts";
import { defaultResolvedKind } from "../../../smlml-vscode/src/views/app/resolve-kind";
import type { LogTag } from "../types.ts";

interface BuildViewResult {
  kind: ViewKind;
  viewJson: string;
  /** Whether the file declares a state machine — gates the Simulation kind. */
  hasStates?: boolean;
  /**
   * Set when the server could not build the view; `viewJson` is then `""`,
   * which parses to nothing and would paint as an empty model.
   */
  error?: string;
}

interface SimStepResult {
  currentState: string;
  traceText: string;
  firedEdgeId?: string | null;
  guards?: GuardEval[];
  machineJson?: string | null;
  /** Set when the server could not run the step; no other field is meaningful. */
  error?: string | null;
}

export interface LspGateway {
  sendRequest<T = unknown>(method: string, params?: unknown): Promise<T>;
}

/**
 * Documentation for a standalone snippet — the editor's own hover lookup,
 * reached without an open document.
 *
 * Supplied by the worker transport. Optional because a host that cannot run
 * the lookup simply never answers a `conceptDocs` message, and the legend rows
 * show no popover rather than waiting on a promise that will not settle.
 */
export interface SnippetDocs {
  snippetHover(src: string, lang: string, offset: number): Promise<string | null>;
}

export interface EditorBridge {
  /** Switch to `uri` if needed and select+scroll the given range. */
  navigate(uri: string, range: SourceRange): void;
}

export interface ViewHostDeps {
  lsp: LspGateway;
  editor: EditorBridge;
  /** Post a message to the reused React app. */
  post(msg: ExtToWebviewMsg): void;
  /** Simulation step result, for the Run panel. */
  onSimResult?(currentState: string, traceText: string): void;
  log(tag: LogTag, msg: string): void;
  /** Language-documentation lookup for legend rows; see {@link SnippetDocs}. */
  docs?: SnippetDocs;
  /** Monotonic clock, injectable so tests are not timing-dependent. */
  now?(): number;
}

export class ViewHost {
  private kind: ViewKind = "auto";
  private currentUri = "";
  private machineJson: string | null = null;
  private cachedNodes: NodeRange[] = [];
  /**
   * Ticket for the newest `refresh` — a build that finishes after a later one
   * started is stale and must not post. Without this, a slow `buildView` for the
   * previous file/kind lands last and overwrites the current view (it is what
   * left the Simulation panel showing an empty diagram and the wrong file's
   * `hasStates`).
   */
  private refreshSeq = 0;
  private readonly cursorPositions = new Map<string, { line: number; character: number }>();
  private heritageRefreshTimer: ReturnType<typeof setTimeout> | undefined;

  /**
   * Metamodel-view expansion set. A refresh rebuilds the app's state from the
   * response, so the request that produced it has to outlive it.
   * `ExpansionState` is the same object panel.ts holds — the accumulation rule
   * is shared rather than ported. Cleared on a file, kind or text change: an
   * expansion names element UUIDs, which belong to one file's graph and to one
   * parse of it.
   */
  private readonly expansion = new ExpansionState();

  /**
   * Document version the current expansion set was built against, or
   * `undefined` when no caller has reported one. Element UUIDs come out of a
   * per-parse counter, so they name different elements after any edit — see
   * `ExpansionState`.
   */
  private currentVersion: number | undefined;

  constructor(private readonly deps: ViewHostDeps) {}

  setActiveUri(uri: string): void {
    if (uri !== this.currentUri) {
      // The clear has to happen here and not only in `refresh`: the "active"
      // event sets the uri first and refreshes afterwards, so by the time
      // `refresh` compares them they are already equal.
      this.expansion.clear();
      this.currentVersion = undefined;
    }
    this.currentUri = uri;
  }

  /**
   * Empty the diagram, invalidating any build already in flight.
   *
   * `setActiveUri("")` alone is not enough: it assigns `currentUri` but leaves
   * `refreshSeq` untouched, so a `buildView` started before the workspace was
   * emptied still holds the current ticket and posts its `loadView` *after* the
   * empty one — repainting the file that was just deleted. Bumping the ticket
   * here is what makes the clear stick, and it is why the caller must use this
   * rather than posting an empty `loadView` itself.
   */
  clear(): void {
    if (this.heritageRefreshTimer) clearTimeout(this.heritageRefreshTimer);
    this.heritageRefreshTimer = undefined;
    this.refreshSeq += 1;
    this.currentUri = "";
    this.cachedNodes = [];
    this.machineJson = null;
    this.deps.post({
      type: "loadView",
      kind: this.kind,
      resolvedKind: defaultResolvedKind(this.kind),
      uri: "",
      viewJson: JSON.stringify({ nodes: [], edges: [] }),
    });
  }

  /**
   * Re-build the current view for `uri` (defaults to the active file).
   *
   * `version` is the document version the caller is showing. Passing it lets
   * the host drop an expansion set that the re-parse has invalidated; omitting
   * it leaves the set alone, which is what a re-request of the same text
   * (`ready`, an expand click) wants.
   */
  async refresh(
    uri = this.currentUri,
    position?: { line: number; character: number },
    version?: number,
  ): Promise<void> {
    if (!uri) return;
    if (uri !== this.currentUri) {
      this.expansion.clear();
      this.currentVersion = undefined;
    }
    if (version !== undefined) {
      if (this.currentVersion !== undefined && version !== this.currentVersion) {
        this.expansion.clear();
      }
      this.currentVersion = version;
    }
    this.currentUri = uri;
    if (position) this.cursorPositions.set(uri, position);

    // Everything posted below describes *this* request, not whatever the fields
    // hold once the await returns.
    const seq = ++this.refreshSeq;
    const kind = this.kind;

    const params: Record<string, unknown> = { uri, kind };
    if (kind === "auto" || kind === "heritage") {
      const selected = position ?? this.cursorPositions.get(uri);
      if (selected) params.position = selected;
    }
    if (kind === "metamodel") {
      const expand = this.expansion.expandParam();
      const budget = this.expansion.budget();
      if (expand) params.expand = expand;
      if (budget !== undefined) params.budget = budget;
    }

    // "simulation" is a panel mode, not a view kind: the server resolves it to
    // the state view, which is the diagram the Simulation panel steps.
    let resolvedKind: ViewKind = defaultResolvedKind(kind);
    let viewJson = "{}";
    let hasStates: boolean | undefined;
    let error: string | undefined;
    const now = this.deps.now ?? (() => performance.now());
    const t0 = now();
    try {
      const result = await this.deps.lsp.sendRequest<BuildViewResult>("smlml/buildView", params);
      if (result) {
        // A failure returns `viewJson: ""`, which is not nullish and so slips
        // past a `??` default straight into the app's `JSON.parse`, where the
        // throw is swallowed and the user sees an empty graph. The `error`
        // field exists so this is told rather than painted as "no elements".
        error = result.error || undefined;
        viewJson = error ? "{}" : (result.viewJson || "{}");
        resolvedKind = (result.kind as ViewKind) ?? resolvedKind;
        hasStates = result.hasStates;
      }
      const elapsed = now() - t0;
      this.deps.log("VIEW", `buildView(${kind}) in ${elapsed.toFixed(0)} ms`);
    } catch (err) {
      error = String(err);
      this.deps.log("VIEW", `buildView(${kind}) error: ${String(err)}`);
    }

    // A newer refresh started while this one was in flight — it owns the view.
    if (seq !== this.refreshSeq) return;

    if (error) {
      // A build that failed on a stale expansion id would fail identically on
      // every later refresh; dropping the set is what lets the view recover.
      this.expansion.clear();
      this.deps.log("VIEW", `buildView(${kind}) failed: ${error}`);
    }

    this.cachedNodes = this.extractNodes(viewJson);
    this.deps.post({
      type: "loadView",
      kind,
      resolvedKind,
      uri,
      viewJson,
      hasStates,
      error,
      expansion: this.expansion.snapshot(),
    });
  }

  /** Editor cursor moved → pulse the matching diagram node or attribute row. */
  onCursor(uri: string, line: number, character: number): void {
    this.cursorPositions.set(uri, { line, character });
    if (uri !== this.currentUri) return;
    if (this.kind === "heritage") {
      if (this.heritageRefreshTimer) clearTimeout(this.heritageRefreshTimer);
      this.heritageRefreshTimer = setTimeout(() => {
        this.heritageRefreshTimer = undefined;
        void this.refresh(uri);
      }, 180);
    }
    if (this.cachedNodes.length === 0) return;
    const target = resolveTargetAtPosition(this.cachedNodes, line, character);
    if (target) {
      this.deps.post({
        type: "highlightNode",
        nodeId: target.nodeId,
        compartment: target.compartment,
      });
    }
  }

  /** Handle a message coming back from the reused React app. */
  async handleAppMessage(msg: WebviewToExtMsg): Promise<void> {
    switch (msg.type) {
      case "ready":
        await this.refresh();
        break;
      case "navigate": {
        const range = normalizeRange(msg.range);
        if (range) this.deps.editor.navigate(msg.uri || this.currentUri, range);
        break;
      }
      case "simulateStep":
        await this.handleSimStep(msg.trigger ?? null, msg.guardOverrides ?? {});
        break;
      case "viewKindChanged":
        this.kind = msg.kind;
        this.expansion.clear();
        await this.refresh();
        break;
      case "expandNodes":
        // An amendment to the set, not a replacement — see `ExpansionState`.
        this.expansion.apply(msg);
        await this.refresh();
        break;
      case "conceptDocs":
        await this.handleConceptDocs(msg.concept);
        break;
    }
  }

  /**
   * Answer the legend's ask for a concept's documentation.
   *
   * Resolves the caption to the snippet `legend-concepts.ts` maps it to and
   * runs the editor's hover lookup over that snippet, so the legend and the
   * text panel show the same text from the same place. An unmapped caption, a
   * host with no lookup, and a position the language has nothing to say about
   * all answer `null` — the app records that and the row stops asking.
   */
  private async handleConceptDocs(concept: string): Promise<void> {
    const query = conceptFor(concept);
    let markdown: string | null = null;
    if (query && this.deps.docs) {
      try {
        markdown = await this.deps.docs.snippetHover(query.src, query.lang, query.offset);
      } catch (err) {
        this.deps.log("VIEW", `conceptDocs(${concept}) failed: ${String(err)}`);
      }
    }
    this.deps.post({ type: "conceptDocsResult", concept, markdown });
  }

  private async handleSimStep(
    trigger: string | null,
    guardOverrides: Record<string, boolean>,
  ): Promise<void> {
    try {
      // "__reset__" is a real server trigger that returns to the initial state
      // while keeping the session machine; the server round-trips machineJson.
      const result = await this.deps.lsp.sendRequest<SimStepResult | null>(
        "smlml/simulateStep",
        {
          uri: this.currentUri,
          machineJson: this.machineJson,
          trigger,
          guardOverrides,
        },
      );

      // A step the server could not run: `error` on a well-formed result, or —
      // from an older server — a bare `null`. Either way, report it and keep the
      // session we already have rather than reading fields off nothing.
      const failure = !result
        ? "the language server could not run the simulation step"
        : result.error;
      if (failure) {
        this.deps.log("VIEW", `simulateStep failed: ${failure}`);
        this.deps.post({ type: "stepError", message: failure });
        return;
      }

      const step = result as SimStepResult;
      this.machineJson = step.machineJson ?? this.machineJson;
      this.deps.post({
        type: "stepResult",
        currentState: step.currentState,
        traceText: step.traceText,
        firedEdgeId: step.firedEdgeId ?? null,
        guards: step.guards ?? [],
      });
      this.deps.onSimResult?.(step.currentState, step.traceText);
    } catch (err) {
      this.deps.log("VIEW", `simulateStep error: ${String(err)}`);
      this.deps.post({ type: "stepError", message: String(err) });
    }
  }

  private extractNodes(viewJson: string): NodeRange[] {
    try {
      const parsed = JSON.parse(viewJson) as {
        nodes?: Array<{ id: string; range?: unknown; compartments?: Array<{ range?: unknown }> }>;
      };
      // Compartment ranges come along: a node's own range is only its
      // declaration name, so an attribute is reachable from the editor only
      // through its row's range.
      return (parsed.nodes ?? []).map((n) => ({
        id: n.id,
        range: normalizeRange(n.range),
        compartments: (n.compartments ?? []).map((c) => ({ range: normalizeRange(c.range) })),
      }));
    } catch {
      return [];
    }
  }
}
