/**
 * Pure derivation of the file-browser tree plus name/move validation guards.
 * No DOM, no store coupling — unit-testable headlessly.  The UI calls
 * `buildTree` on every render and the guards from inline-edit / drag handlers.
 */

export interface TreeFile {
  kind: "file";
  path: string;
  name: string;
  uri: string;
}

export interface TreeFolder {
  kind: "folder";
  path: string;
  name: string;
  children: TreeNode[];
}

export type TreeNode = TreeFile | TreeFolder;

/** Build a nested tree from files and explicit folder paths (folders first). */
export function buildTree(files: { path: string; uri: string }[], folders: string[]): TreeNode[] {
  const root: TreeFolder = { kind: "folder", path: "", name: "", children: [] };
  const byPath = new Map<string, TreeFolder>([["", root]]);

  function ensureFolder(path: string): TreeFolder {
    const existing = byPath.get(path);
    if (existing) return existing;
    const slash = path.lastIndexOf("/");
    const parentPath = slash >= 0 ? path.slice(0, slash) : "";
    const name = slash >= 0 ? path.slice(slash + 1) : path;
    const parent = ensureFolder(parentPath);
    const node: TreeFolder = { kind: "folder", path, name, children: [] };
    parent.children.push(node);
    byPath.set(path, node);
    return node;
  }

  for (const dir of folders) if (dir) ensureFolder(dir);
  for (const f of files) {
    const slash = f.path.lastIndexOf("/");
    const dir = slash >= 0 ? f.path.slice(0, slash) : "";
    const name = slash >= 0 ? f.path.slice(slash + 1) : f.path;
    ensureFolder(dir).children.push({ kind: "file", path: f.path, name, uri: f.uri });
  }

  sortChildren(root);
  return root.children;
}

function sortChildren(folder: TreeFolder): void {
  folder.children.sort((a, b) => {
    if (a.kind !== b.kind) return a.kind === "folder" ? -1 : 1;
    return a.name.localeCompare(b.name);
  });
  for (const c of folder.children) if (c.kind === "folder") sortChildren(c);
}

/** A name is valid if non-empty, slash-free, and not already a sibling. */
export function isValidName(name: string, siblings: string[]): boolean {
  if (!name || name.includes("/")) return false;
  return !siblings.includes(name);
}

/** A file name additionally must end in `.sysml` / `.kerml`. */
export function isValidFileName(name: string, siblings: string[]): boolean {
  return isValidName(name, siblings) && /\.(sysml|kerml)$/i.test(name);
}

/** True when `srcPath` can move into `destFolder` (no self, descendant, or no-op). */
export function canMove(srcPath: string, destFolder: string): boolean {
  if (destFolder === srcPath) return false;
  if (destFolder.startsWith(srcPath + "/")) return false;
  const srcParent = srcPath.includes("/") ? srcPath.slice(0, srcPath.lastIndexOf("/")) : "";
  return srcParent !== destFolder;
}
