/**
 * Log panel — timestamped WASM lifecycle + operation breadcrumbs.
 * Implements `LogSink` so it can be handed to the worker transport and others.
 */

import type { LogLevel, LogSink, LogTag } from "../types.ts";

function stamp(): string {
  const d = new Date();
  const p = (n: number, w = 2) => String(n).padStart(w, "0");
  return `${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}.${p(d.getMilliseconds(), 3)}`;
}

export class LogPanel implements LogSink {
  constructor(
    private readonly listEl: HTMLElement,
    private readonly countEl: HTMLElement
  ) {}

  log(tag: LogTag, msg: string, level: LogLevel = "info"): void {
    const line = document.createElement("div");
    line.className = `log-line ${level}`;
    const t = document.createElement("span");
    t.className = "ts";
    t.textContent = stamp();
    const g = document.createElement("span");
    g.className = "tag";
    g.textContent = tag;
    const m = document.createElement("span");
    m.className = "msg";
    m.textContent = msg;
    line.append(t, g, m);
    this.listEl.appendChild(line);
    this.listEl.scrollTop = this.listEl.scrollHeight;
    this.countEl.textContent = `${this.listEl.childElementCount} entries`;
  }

  clear(): void {
    this.listEl.innerHTML = "";
    this.countEl.textContent = "0 entries";
  }
}
