/**
 * Metamodel-view node: one resolved element, or one truncation placeholder.
 *
 * The metamodel view is a debugging and training diagram — it shows which
 * metaclass instances a piece of text produced and what each one stores — so
 * this box is field-qualified where `DefaultNode` is not. `mass` alone says
 * nothing here; `declaredName mass` says which slot it came out of, and the
 * same slot on a flow end would carry only a source slice.
 *
 * The wire is creole-free: `stereotype` arrives as the bare metaclass and the
 * guillemets are added here, as are the monospace face on the source slice,
 * the dashed outline, and every placeholder's text.
 */

import React from "react";
import { Handle, Position, type NodeProps } from "@xyflow/react";
import { boundedBudget } from "../types";
import type { CompartmentEntry, Truncation } from "../types";

/**
 * Compartment kind carrying the verbatim source text that produced an element
 * (`smlml_viewgen::metamodel::SOURCE_SLICE`). It gets the monospace face; every
 * other row is a metamodel field name and its value.
 */
export const SOURCE_SLICE = "source";

/**
 * Longest source slice painted on a box before it is elided.
 *
 * Exported because `layout.ts` reserves the box this paints into: measuring the
 * full slice is what pinned every metamodel node to `--smlml-max-w` while the
 * painter showed 34 characters of it.
 */
export const SLICE_CHARS = 34;

/** The slice as painted — elided at {@link SLICE_CHARS} — or `undefined`. */
export function sliceText(compartments: CompartmentEntry[]): string | undefined {
  const row = compartments.find(c => c.kind === SOURCE_SLICE);
  if (!row) return undefined;
  return row.label.length > SLICE_CHARS ? row.label.slice(0, SLICE_CHARS) + "…" : row.label;
}

/**
 * The name painted on its own line, or `undefined` when a field row already
 * carries it.
 *
 * A named element carries its name twice — once in `label` and once in the row
 * naming the field it came out of — and the row is the more informative of the
 * two. An `«external»` ghost has only `label`: it stands for a target outside
 * this resource, so there is no element here to have a name field. Matched
 * against the NAME rows only: a node whose `value` happens to equal its name
 * would otherwise lose the name line.
 *
 * Exported for the same reason as {@link SLICE_CHARS} — the reserved height has
 * to agree with whether this line paints.
 */
export function bareNameOf(
  label: string | undefined,
  rows: CompartmentEntry[]
): string | undefined {
  return label && !rows.some(c => NAME_FIELDS.includes(c.kind) && c.label === label)
    ? label
    : undefined;
}

/** The field rows painted as lines — every compartment but the source slice. */
export function fieldRows(compartments: CompartmentEntry[]): CompartmentEntry[] {
  return compartments.filter(c => c.kind !== SOURCE_SLICE);
}

/** The expand control's text, or `undefined` when the node offers none. */
export function expandText(expandable: boolean, expanded: boolean): string | undefined {
  if (!expandable) return undefined;
  return expanded ? "+ expand rest" : "+ expand";
}

/** The collapse control's text, or `undefined` when the node offers none. */
export function collapseText(collapsible: boolean): string | undefined {
  return collapsible ? "− collapse" : undefined;
}

/** Fields whose value the hover panel shows after the flags, in this order. */
const HOVER_SCALARS = ["visibility", "direction", "value"];

/**
 * The name-bearing fields (`smlml_viewgen::metamodel::NAME_FIELDS`). A row of
 * one of these kinds is where a named element's `label` also appears.
 */
const NAME_FIELDS = ["declaredName", "declaredShortName"];

/**
 * Hover text: identity plus the non-relational metadata.
 *
 * Deliberately *not* the byte range. The range drives click-to-source, which is
 * what the click already does; printing it here would be an implementation
 * detail competing with the fields that answer a question.
 *
 * The `is*` rows are split into set and unset because on a metamodel element
 * an unset flag is a fact, not an absence — `isAbstract false` on a definition
 * is why it is not italic. The split reads whatever `is*` rows the wire sends;
 * today's builder keeps them off the box as per-feature boilerplate, so the
 * two lines appear only where they carry something.
 */
export function hoverText(
  stereotype: string | undefined,
  elementId: string | undefined,
  hasSource: boolean,
  compartments: CompartmentEntry[]
): string {
  const lines: string[] = [];
  if (stereotype) lines.push(`«${stereotype}»`);
  if (elementId) lines.push(`uuid: ${elementId}`);
  if (!hasSource) lines.push("no distinct grammar rule node produced this element");

  // Keyed on the boolean value rather than on an `is` name prefix, which
  // would also capture a future field spelled e.g. `isolation`. The scalar
  // fields are excluded by name because their value is not a flag even when it
  // reads as one: `attribute flag = true;` gives a `LiteralBoolean` a `value`
  // row of `"true"`, which belongs on the `value:` line.
  const isFlag = (c: CompartmentEntry) =>
    !HOVER_SCALARS.includes(c.kind) && (c.label === "true" || c.label === "false");
  const set = compartments.filter(c => isFlag(c) && c.label === "true").map(c => c.kind);
  const unset = compartments.filter(c => isFlag(c) && c.label === "false").map(c => c.kind);
  if (set.length) lines.push(`flags: ${set.join(", ")}`);
  if (unset.length) lines.push(`not: ${unset.join(", ")}`);

  const scalars = compartments.filter(c => HOVER_SCALARS.includes(c.kind));
  const names = compartments.filter(
    c => !isFlag(c) && !HOVER_SCALARS.includes(c.kind) && c.kind !== SOURCE_SLICE
  );
  for (const c of [...scalars, ...names]) lines.push(`${c.kind}: ${c.label}`);

  return lines.join("\n");
}

/**
 * The text a truncation placeholder shows, composed from the numbers it carries.
 *
 * The global control states what it will actually deliver, not what the server
 * counted. `total` is unclamped, but the request is bounded to
 * `boundedBudget(total)` so the layout cannot freeze the editor indefinitely —
 * a button reading "Expand all 50000 nodes · ≈40.0s" that delivers 12500 would
 * be stating a total and a cost it has no intention of honouring. Where the
 * cap applies the label says so and prices the request it will really send.
 */
export function truncationLabel(t: Truncation): string {
  if (t.affordance === "branch") {
    return `+${t.hidden}`;
  }
  const asking = boundedBudget(t.total);
  const seconds = (
    (t.estimated_layout_ms * (asking / Math.max(t.total, 1))) / 1000
  ).toFixed(1);
  return asking < t.total
    ? `(+) Expand ${asking} of ${t.total} nodes · ≈${seconds}s layout · capped`
    : `(+) Expand all ${t.total} nodes · ≈${seconds}s layout`;
}

/**
 * The secondary line under a `+N` control, absent on the global one.
 *
 * Exported for `layout.ts`: a placeholder that paints two lines has to be
 * measured as two lines.
 */
export function truncationDetail(t: Truncation): string | undefined {
  if (t.affordance === "branch") return "hidden below this node";
  return `showing ${t.budget} of ${t.total}`;
}

function TruncationBox({ truncation }: { truncation: Truncation }) {
  const detail = truncationDetail(truncation);
  return (
    <div
      className="smlml-node smlml-metamodel-truncation"
      data-affordance={truncation.affordance}
    >
      <Handle type="target" position={Position.Top} />
      <div className="smlml-metamodel-truncation-label">{truncationLabel(truncation)}</div>
      {detail && <div className="smlml-metamodel-truncation-detail">{detail}</div>}
      <Handle type="source" position={Position.Bottom} />
    </div>
  );
}

export function MetamodelNode({ data, selected }: NodeProps) {
  const truncation = data.truncation as Truncation | undefined;
  if (truncation) return <TruncationBox truncation={truncation} />;

  const stereotype = data.stereotype as string | undefined;
  const elementId = data.elementId as string | undefined;
  // The wire omits `has_source` when true, and `layout.ts` forwards it as it
  // arrived, so an absent value is the majority case rather than unknown.
  const hasSource = (data.hasSource as boolean | undefined) ?? true;
  const expandable = data.expandable as boolean | undefined;
  const expanded = data.expanded as boolean | undefined;
  // Whether closing this node would change the graph — see `decorateNodes`.
  // The whole drawn subtree of an opened node arrives `expanded`, and a close
  // can only remove an id the client's own set holds.
  const collapsible = (data.collapsible as boolean | undefined) ?? expanded;
  const compartments = (data.compartments as CompartmentEntry[] | undefined) ?? [];

  const label = data.label as string | undefined;
  const rows = fieldRows(compartments);
  const bareName = bareNameOf(label, rows);
  const slice = sliceText(compartments);

  return (
    <div
      className={`smlml-node smlml-metamodel-node${selected ? " selected" : ""}`}
      data-has-source={String(hasSource)}
      title={hoverText(stereotype, elementId, hasSource, compartments)}
      style={
        // A dashed outline says the engine built this element and nobody typed
        // it — the one bit an absent span carries. Inline because it is a
        // per-node conditional, not part of the type scale `layout.ts` measures.
        hasSource ? undefined : { borderStyle: "dashed", borderWidth: 1.5 }
      }
    >
      <Handle type="target" position={Position.Top} />
      {stereotype && <div className="smlml-node-metaclass">«{stereotype}»</div>}
      {bareName && (
        <div className="smlml-node-label">{bareName}</div>
      )}
      {rows.map((c, i) => (
        <div key={i} className={`smlml-metamodel-row smlml-metamodel-${c.kind}`}>
          <span className="smlml-metamodel-field">{c.kind}</span>{" "}
          <span className="smlml-metamodel-value">{c.label}</span>
        </div>
      ))}
      {!hasSource && <div className="smlml-metamodel-nosource">no source node</div>}
      {slice && <div className="smlml-metamodel-slice">{slice}</div>}
      {/* Two independent controls, because the two facts are independent: a
          node can have folded relationships beneath it AND materialized ones,
          which is a partial expansion. They are separate elements so a click
          on the box itself is still a navigation. */}
      {expandable && (
        <div className="smlml-metamodel-control smlml-metamodel-expand">
          {expandText(true, expanded ?? false)}
        </div>
      )}
      {collapsible && (
        <div className="smlml-metamodel-control smlml-metamodel-collapse">
          {collapseText(true)}
        </div>
      )}
      <Handle type="source" position={Position.Bottom} />
    </div>
  );
}
