/**
 * Custom React Flow node components, and the one registry that maps
 * `layout.ts`'s node type strings onto them.
 *
 * The registry lives here, next to the components, because there is exactly one
 * correct answer to "which component draws a node of type T" and it does not
 * vary by view. A missing entry is silent — React Flow falls back to the
 * `default` component — so a boundary port could paint a full
 * stereotype-and-name box inside the 14px square `layout.ts` reserves for a
 * port glyph, overflowing the layout. A single shared registry, rather than
 * a per-view copy, is what keeps every view's entry set consistent.
 *
 * Register every family here and import `NODE_TYPES`; do not re-declare it.
 */

import type { NodeTypes } from "@xyflow/react";
import { DefaultNode } from "./DefaultNode";
import { StateNode } from "./StateNode";
import { ActionInitialNode } from "./ActionInitialNode";
import { ActionFinalNode } from "./ActionFinalNode";
import { ActionDecisionNode } from "./ActionDecisionNode";
import { ActionForkJoinNode } from "./ActionForkJoinNode";
import { PortNode } from "./PortNode";
import { PackageNode } from "./PackageNode";
import { AnnotationNode } from "./AnnotationNode";
import { MetamodelNode } from "./MetamodelNode";
import { LifelineNode } from "./LifelineNode";
import { SequenceBoxNode } from "./SequenceBoxNode";

export {
  DefaultNode, StateNode, ActionInitialNode, ActionFinalNode,
  ActionDecisionNode, ActionForkJoinNode, PortNode, PackageNode, AnnotationNode,
  MetamodelNode, LifelineNode, SequenceBoxNode,
};

/**
 * Every node type a layout producer can emit — `layout.ts`'s `rfNodeType` for
 * the ELK views, `sequenceLayout.ts` for the sequence view. Keep them in step:
 * a type emitted but not registered here renders as the wrong component at the
 * wrong size, with only a console warning to say so.
 */
export const NODE_TYPES: NodeTypes = {
  default:         DefaultNode,
  state:           StateNode,
  actionInitial:   ActionInitialNode,
  actionFinal:     ActionFinalNode,
  actionDecision:  ActionDecisionNode,
  actionForkJoin:  ActionForkJoinNode,
  port:            PortNode,
  package:         PackageNode,
  annotation:      AnnotationNode,
  metamodel:       MetamodelNode,
  // Sequence view only, and emitted by `sequenceLayout` rather than by
  // `rfNodeType`: `rfNodeType` classifies a wire node's kind, and the box
  // frame is not a wire node at all. Registered in the same one registry all
  // the same — there is still exactly one answer to "which component draws a
  // node of type T".
  lifeline:        LifelineNode,
  sequenceBox:     SequenceBoxNode,
};
