/**
 * Tree view — OMG VTree + VCompartment + VRequirement conformant.
 *
 * Consumes v2 ViewModel and lays out with ELK:
 *   - All named elements as compartmented nodes
 *   - «stereotype» above name
 *   - Attribute/doc compartments below name
 *   - Distinct edge styles (per pilot `SysML2PlantUMLStyle`):
 *     - containment → thin solid, owner-end glyph (◆/◇/⊕)
 *     - specialization/typing/redefinition/subsetting → solid, hollow triangle
 *     - dependency/annotation → dotted
 *     - connector/binding → thick solid
 *     - requirement_edge → labelled
 *   - Variation decoration on node border
 */

import React, { useCallback, useEffect, useState } from "react";
import {
  ReactFlow,
  useNodesState,
  useEdgesState,
  useReactFlow,
  Background,
  BackgroundVariant,
  Controls,
  type Node,
  type Edge,
} from "@xyflow/react";
import type { ViewModel, SourceRange } from "./types";
import type { EdgeRouting } from "./Diagram";
import { layoutViewModel, routingAlgorithm, type LayoutDirection, type LayoutOptions } from "./layout";
import { EdgeMarkers } from "./EdgeMarkers";
import { EDGE_TYPES } from "./FloatingEdge";
import { NavigateContext } from "./NavigateContext";
import { LayoutFailureBanner } from "./LayoutFailureBanner";
import { NODE_TYPES } from "./nodes";
import { NO_MATCHES, type SearchMatches } from "./search";
import { useEdgeSelection } from "./edge-selection";
import { LockControl } from "./LockControl";
import { LoadingOverlay } from "./LoadingOverlay";
import { FitAfterLayout, FitToMatches, SyncViewportTransition } from "./ViewportTransitions";
import { useFontMetricEpoch } from "./font-metrics-lifecycle";


// ─────────────────────────── v2 component ────────────────────────────────────

interface Props {
  model: ViewModel;
  routing: EdgeRouting;
  uri: string;
  onNavigate: (uri: string, range: SourceRange) => void;
  /** Node id to scroll into view and pulse-highlight. */
  highlightNodeId?: string;
  /**
   * Index of the compartment row to highlight within `highlightNodeId`, when
   * the editor cursor landed on a specific attribute rather than on the
   * declaration name.
   */
  highlightCompartment?: number;
  /** Free-text search hits to mark and to frame. */
  matches?: SearchMatches;
  /**
   * Whether a reader may drag nodes. Defaults to locked: the ELK layout is
   * authoritative, and a dragged node desyncs from the rectangle its edges were
   * routed against. Surfaced in the diagram's Settings popover.
   */
  nodesDraggable?: boolean;
  /**
   * Lift or re-apply the lock. React Flow's own `<Controls>` padlock writes
   * straight to its store, which the `nodesDraggable` prop then overwrites on
   * the next render — so the padlock looked live but could not unlock anything,
   * and merely dropped `selectable` off every node on the way. Routing it back
   * to the state that owns the lock is what makes the two controls one control.
   */
  onNodesDraggableChange?: (draggable: boolean) => void;
  /** Heritage view may rotate its layered DAG without rebuilding the model. */
  direction?: LayoutDirection;
  /** Present only for Heritage, where orientation is an explicit reader control. */
  onDirectionChange?: (direction: LayoutDirection) => void;
}

export function TreeFlowView({ model, routing, uri, onNavigate, highlightNodeId, highlightCompartment, matches, nodesDraggable = false, onNodesDraggableChange, direction = "DOWN", onDirectionChange }: Props) {
  const fontMetricEpoch = useFontMetricEpoch();
  const [nodes, setNodes, onNodesChange] = useNodesState<Node>([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState<Edge>([]);
  const [layoutTick, setLayoutTick] = useState(0);
  const [layoutFailed, setLayoutFailed] = useState<Error | undefined>(undefined);
  const [layoutPending, setLayoutPending] = useState(false);
  const { fitView } = useReactFlow();

  // Selecting an edge frames both of its endpoints so the relation is readable
  // even when source and target are far apart in the layout. Framing alone
  // moves the viewport without saying which of the lines now on screen was
  // clicked, so it runs as the selection hook's side effect and the hook's own
  // marking says that.
  const frameEndpoints = useCallback(
    (edge: Edge) => {
      fitView({
        nodes: [{ id: edge.source }, { id: edge.target }],
        padding: 0.3,
        duration: 300,
      });
    },
    [fitView]
  );
  const edgeSelection = useEdgeSelection(frameEndpoints);

  useEffect(() => {
    let cancelled = false;
    setLayoutPending(true);
    // Yield one frame so the delayed progress cover is committed before a
    // large synchronous ELK pass can occupy the UI thread.
    const id = setTimeout(() => {
      const edgeRouting = routingAlgorithm(routing);
      const opts: LayoutOptions = { direction, edgeRouting, containment: "tree" };
      void layoutViewModel(model, opts).then(({ nodes: n, edges: e, layoutFailed: failed }) => {
        if (cancelled) return;
        setNodes(n);
        setEdges(e);
        setLayoutTick(t => t + 1);
        // Clear a stale banner from a previous failed layout so it cannot
        // outlive the failure that caused it.
        setLayoutFailed(failed);
        setLayoutPending(false);
      });
    }, 0);
    return () => {
      cancelled = true;
      clearTimeout(id);
    };
  }, [model, routing, direction, fontMetricEpoch, setNodes, setEdges]);

  // Cursor highlight and search hits both decorate nodes, and a node can carry
  // both at once, so they are applied in one pass rather than layered maps.
  const hits = matches ?? NO_MATCHES;
  const matchedNodes = nodes.map(n => {
    const isCursor = n.id === highlightNodeId;
    const isHit = hits.nodes.has(n.id);
    if (!isCursor && !isHit) return n;
    const classes = [n.className, isCursor && "smlml-node-highlight", isHit && "smlml-node-match"]
      .filter(Boolean)
      .join(" ");
    // Re-wrapping `data` is what makes the row decorations reach the node
    // component: React Flow only re-renders a node whose `data` identity
    // changed, so mutating in place would paint nothing.
    return {
      ...n,
      className: classes,
      data: {
        ...n.data,
        ...(isCursor ? { highlightCompartment } : {}),
        matchCompartments: hits.rows.get(n.id),
      },
    };
  });

  // Sorted so the framing effect keys on the CONTENT of the result set.
  const matchIds = Array.from(hits.nodes).sort();

  const matchedEdges = edges.map(e =>
    hits.edges.has(e.id)
      ? { ...e, className: [e.className, "smlml-edge-match"].filter(Boolean).join(" ") }
      : e
  );

  // Clicking a relation marks it and both elements it relates — applied
  // last so it layers over the cursor/search decoration above.
  const { decorate, onEdgeClick, onPaneClick } = edgeSelection;
  const { nodes: paintedNodes, edges: paintedEdges } = decorate(matchedNodes, matchedEdges);

  const handleNodeClick = (_: React.MouseEvent, node: Node) => {
    const range = node.data?.range as SourceRange | undefined;
    if (range) onNavigate((node.data?.uri as string | undefined) ?? uri, range);
  };

  return (
    <NavigateContext.Provider value={{ navigate: onNavigate, uri }}>
      <LayoutFailureBanner error={layoutFailed} />
      {layoutPending && (
        <LoadingOverlay
          message={`Laying out ${model.nodes.length} elements…`}
          delayMs={model.nodes.length >= 100 ? 0 : 1000}
        />
      )}
      <ReactFlow
        nodes={paintedNodes}
        edges={paintedEdges}
        nodeTypes={NODE_TYPES}
        edgeTypes={EDGE_TYPES}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onNodeClick={handleNodeClick}
        onEdgeClick={onEdgeClick}
        onPaneClick={onPaneClick}
        fitView
        minZoom={0.1}
        maxZoom={4}
        // Nodes are locked by default: the ELK layout is authoritative, and a
        // dragged node desyncs from the rectangle edges were routed against.
        // The diagram's Settings popover can lift it per session.
        nodesDraggable={nodesDraggable}
        nodesConnectable={false}
      >
        <EdgeMarkers />
        <FitAfterLayout trigger={layoutTick} />
        <SyncViewportTransition nodeId={highlightNodeId} />
        <FitToMatches nodeIds={matchIds} />
        <Background variant={BackgroundVariant.Dots} gap={20} size={1} />
        {/* `showInteractive={false}`: React Flow's own padlock derives its
            state from three store flags and writes all three, which cannot
            express "locked for dragging, still selectable". See LockControl. */}
        <Controls position="bottom-left" showInteractive={false}>
          {onDirectionChange && (
            <button
              type="button"
              className="react-flow__controls-button"
              title={direction === "DOWN" ? "Lay out left to right" : "Lay out top to bottom"}
              aria-label="Toggle Heritage view orientation"
              onClick={() => onDirectionChange(direction === "DOWN" ? "RIGHT" : "DOWN")}
            >
              {direction === "DOWN" ? "↔" : "↕"}
            </button>
          )}
          <LockControl
            locked={!nodesDraggable}
            onChange={locked => onNodesDraggableChange?.(!locked)}
          />
        </Controls>
      </ReactFlow>
    </NavigateContext.Provider>
  );
}
