import type { SourceRange } from "../types.ts";

export interface NavigationLocation {
  uri: string;
  range: SourceRange;
}

const sameLocation = (a: NavigationLocation, b: NavigationLocation): boolean =>
  a.uri === b.uri &&
  a.range.startLine === b.range.startLine &&
  a.range.startCol === b.range.startCol &&
  a.range.endLine === b.range.endLine &&
  a.range.endCol === b.range.endCol;

/** Browser-style source-location history with per-document cursor memory. */
export class NavigationHistory {
  private readonly backStack: NavigationLocation[] = [];
  private readonly forwardStack: NavigationLocation[] = [];
  private readonly latestByUri = new Map<string, NavigationLocation>();
  private current: NavigationLocation | null = null;

  get canGoBack(): boolean { return this.backStack.length > 0; }
  get canGoForward(): boolean { return this.forwardStack.length > 0; }

  /** Track cursor movement without creating a history entry. */
  observe(location: NavigationLocation): void {
    this.current = location;
    this.latestByUri.set(location.uri, location);
  }

  /** Record an explicit jump and clear the abandoned forward branch. */
  navigate(location: NavigationLocation): NavigationLocation {
    if (this.current && !sameLocation(this.current, location)) this.backStack.push(this.current);
    this.forwardStack.length = 0;
    this.current = location;
    this.latestByUri.set(location.uri, location);
    return location;
  }

  back(): NavigationLocation | null {
    const target = this.backStack.pop();
    if (!target) return null;
    if (this.current) this.forwardStack.push(this.current);
    this.current = target;
    this.latestByUri.set(target.uri, target);
    return target;
  }

  forward(): NavigationLocation | null {
    const target = this.forwardStack.pop();
    if (!target) return null;
    if (this.current) this.backStack.push(this.current);
    this.current = target;
    this.latestByUri.set(target.uri, target);
    return target;
  }

  locationFor(uri: string): NavigationLocation {
    return this.latestByUri.get(uri) ?? {
      uri,
      range: { startLine: 0, startCol: 0, endLine: 0, endCol: 0 },
    };
  }

  removeUri(uri: string): void {
    this.latestByUri.delete(uri);
    for (const stack of [this.backStack, this.forwardStack]) {
      for (let i = stack.length - 1; i >= 0; i--) {
        if (stack[i].uri === uri) stack.splice(i, 1);
      }
    }
    if (this.current?.uri === uri) this.current = null;
  }
}
