/**
 * CodeMirror 6 editor wrapper for the active workspace file.
 *
 * Responsibilities:
 *   - render/replace the active document (file switch resets history cleanly);
 *   - surface debounced edits (→ didChange) and cursor moves (→ diagram sync);
 *   - apply LSP diagnostics as squiggles + a lint gutter;
 *   - apply semantic-token decorations;
 *   - reveal/select a source range (node-click navigation).
 *
 * Positions on the wire are 0-based line + UTF-16 character; we convert to/from
 * CodeMirror document offsets.
 */

import { EditorState, type Extension } from "@codemirror/state";
import {
  EditorView,
  highlightActiveLine,
  highlightActiveLineGutter,
  hoverTooltip,
  keymap,
  lineNumbers,
  drawSelection,
  tooltips,
} from "@codemirror/view";
import { defaultKeymap, history, historyKeymap, indentWithTab } from "@codemirror/commands";
import { indentUnit } from "@codemirror/language";
import { lintGutter, setDiagnostics, type Diagnostic as CmDiagnostic } from "@codemirror/lint";

import type { Diagnostic, Lang, LspRange, SourceRange } from "../types.ts";
import { semanticTokensExtension, setSemanticTokens } from "./semantic-tokens.ts";
import { smlLanguageSupport } from "./sml-language.ts";
import { calcDecorationsExtension, setCalcResults, type CalcResult } from "./calc-decorations.ts";
import { renderMarkdown } from "./markdown.ts";

export interface EditorCallbacks {
  /** Debounced document edit. */
  onChange(text: string): void;
  /** Cursor moved (0-based line + UTF-16 character). */
  onSelection(line: number, character: number): void;
  /**
   * Hover requested at a 0-based (line, UTF-16 character) position.  Return the
   * hover text (markdown/plain) to show, or null for none.  Optional.
   */
  onHover?(line: number, character: number): Promise<string | null>;
  /** Navigate from the reference at this position back to its definition. */
  onDefinition?(line: number, character: number): Promise<void>;
  onNavigateBack?(): void;
  onNavigateForward?(): void;
}

const DEBOUNCE_MS = 250;

export class SmlEditor {
  private readonly view: EditorView;
  private readonly disposeGeometryRefresh: () => void;
  private suppressChange = false;
  private changeTimer: ReturnType<typeof setTimeout> | null = null;
  private lang: Lang = "sysml";

  constructor(parent: HTMLElement, private readonly cbs: EditorCallbacks) {
    this.view = new EditorView({ parent, state: this.makeState("") });
    this.disposeGeometryRefresh = this.installGeometryRefresh();
  }

  /**
   * Keep CodeMirror's synthetic caret and tiled text DOM synchronized with the
   * font the browser is actually painting. This matters when Windows finishes
   * resolving a local font after startup or managed display settings change
   * the effective scale without changing editor state.
   */
  private installGeometryRefresh(): () => void {
    let disposed = false;
    let frame = 0;
    const signature = () => {
      const style = getComputedStyle(this.view.contentDOM);
      return [
        window.devicePixelRatio,
        window.visualViewport?.scale ?? 1,
        style.fontFamily,
        style.fontSize,
        style.lineHeight,
      ].join("|");
    };
    let previous = signature();
    const refresh = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => {
        if (disposed) return;
        previous = signature();
        this.view.requestMeasure();
      });
    };
    const refreshIfChanged = () => {
      if (signature() !== previous) refresh();
    };

    const fonts = document.fonts;
    void fonts?.ready.then(refresh);
    fonts?.addEventListener("loadingdone", refresh);
    fonts?.addEventListener("loadingerror", refresh);
    window.addEventListener("resize", refreshIfChanged);
    window.visualViewport?.addEventListener("resize", refreshIfChanged);

    const styleObserver = new MutationObserver(refresh);
    styleObserver.observe(document.body, { attributes: true, attributeFilter: ["class", "style"] });

    return () => {
      disposed = true;
      cancelAnimationFrame(frame);
      fonts?.removeEventListener("loadingdone", refresh);
      fonts?.removeEventListener("loadingerror", refresh);
      window.removeEventListener("resize", refreshIfChanged);
      window.visualViewport?.removeEventListener("resize", refreshIfChanged);
      styleObserver.disconnect();
    };
  }

  private baseExtensions(): Extension[] {
    return [
      lineNumbers(),
      highlightActiveLine(),
      highlightActiveLineGutter(),
      drawSelection(),
      history(),
      indentUnit.of("    "),
      // `indentWithTab` last so Tab indents in the editor instead of moving
      // focus to the next UI element.
      keymap.of([
        {
          key: "F12",
          run: (view) => {
            const onDefinition = this.cbs.onDefinition;
            if (!onDefinition) return false;
            const pos = view.state.selection.main.head;
            const line = view.state.doc.lineAt(pos);
            void onDefinition(line.number - 1, pos - line.from);
            return true;
          },
        },
        { key: "Alt-ArrowLeft", run: () => { this.cbs.onNavigateBack?.(); return true; } },
        { key: "Alt-ArrowRight", run: () => { this.cbs.onNavigateForward?.(); return true; } },
        ...defaultKeymap,
        ...historyKeymap,
        indentWithTab,
      ]),
      lintGutter(),
      // Render tooltips in document.body (fixed) so the hover popup is not
      // clipped by `.editor-host { overflow: hidden }`.
      tooltips({ position: "fixed", parent: document.body }),
      smlLanguageSupport(this.lang),
      semanticTokensExtension(),
      calcDecorationsExtension(),
      this.hoverExtension(),
      EditorView.domEventHandlers({
        mousedown: (event, view) => {
          if (event.button === 3 || event.button === 4) {
            event.preventDefault();
            if (event.button === 3) this.cbs.onNavigateBack?.();
            else this.cbs.onNavigateForward?.();
            return true;
          }
          const onDefinition = this.cbs.onDefinition;
          if (!onDefinition || event.button !== 0 || (!event.ctrlKey && !event.metaKey)) {
            return false;
          }
          const pos = view.posAtCoords({ x: event.clientX, y: event.clientY });
          if (pos === null) return false;
          const line = view.state.doc.lineAt(pos);
          event.preventDefault();
          void onDefinition(line.number - 1, pos - line.from);
          return true;
        },
      }),
      EditorView.updateListener.of((update) => {
        if (update.docChanged && !this.suppressChange) {
          this.scheduleChange();
        }
        if (update.selectionSet) {
          const pos = update.state.selection.main.anchor;
          const line = update.state.doc.lineAt(pos);
          this.cbs.onSelection(line.number - 1, pos - line.from);
        }
      }),
    ];
  }

  private makeState(text: string): EditorState {
    return EditorState.create({ doc: text, extensions: this.baseExtensions() });
  }

  /** LSP-backed hover tooltips, driven by the optional `onHover` callback. */
  private hoverExtension(): Extension {
    return hoverTooltip(async (view, pos) => {
      const onHover = this.cbs.onHover;
      if (!onHover) return null;
      const line = view.state.doc.lineAt(pos);
      const text = await onHover(line.number - 1, pos - line.from);
      if (!text) return null;
      return {
        pos,
        above: true,
        create: () => {
          const dom = document.createElement("div");
          dom.className = "cm-sml-hover";
          renderMarkdown(dom, text);
          return { dom };
        },
      };
    });
  }

  private scheduleChange(): void {
    if (this.changeTimer) clearTimeout(this.changeTimer);
    this.changeTimer = setTimeout(() => {
      this.changeTimer = null;
      this.cbs.onChange(this.getText());
    }, DEBOUNCE_MS);
  }

  /** Replace the whole document (on file switch) without emitting onChange. */
  setDoc(text: string, lang: Lang): void {
    this.lang = lang;
    this.suppressChange = true;
    this.view.setState(this.makeState(text));
    this.suppressChange = false;
  }

  getText(): string {
    return this.view.state.doc.toString();
  }

  getLang(): Lang {
    return this.lang;
  }

  // ─────────────────────────── diagnostics ───────────────────────────

  setDiagnostics(diags: Diagnostic[]): void {
    const cmDiags: CmDiagnostic[] = [];
    for (const d of diags) {
      const from = this.offsetOf(d.range.start.line, d.range.start.character);
      let to = this.offsetOf(d.range.end.line, d.range.end.character);
      if (to < from) to = from;
      if (to === from) to = Math.min(from + 1, this.view.state.doc.length);
      cmDiags.push({
        from,
        to,
        severity: d.severity === 1 ? "error" : d.severity === 3 || d.severity === 4 ? "info" : "warning",
        message: d.message,
        source: d.source,
      });
    }
    this.view.dispatch(setDiagnostics(this.view.state, cmDiags));
  }

  setSemanticTokens(data: number[]): void {
    this.view.dispatch({ effects: setSemanticTokens.of(data) });
  }

  /** Inline `= value unit` annotations for solved calc features. */
  setCalcResults(results: CalcResult[]): void {
    this.view.dispatch({ effects: setCalcResults.of(results) });
  }

  // ─────────────────────────── navigation ───────────────────────────

  revealRange(range: SourceRange): void {
    const from = this.offsetOf(range.startLine, range.startCol);
    const to = this.offsetOf(range.endLine, range.endCol);
    this.view.dispatch({
      selection: { anchor: from, head: Math.max(from, to) },
      scrollIntoView: true,
    });
    this.view.focus();
  }

  focus(): void {
    this.view.focus();
  }

  destroy(): void {
    this.disposeGeometryRefresh();
    this.view.destroy();
  }

  // ─────────────────────────── helpers ───────────────────────────

  private offsetOf(line: number, character: number): number {
    const doc = this.view.state.doc;
    if (line < 0) return 0;
    if (line >= doc.lines) return doc.length;
    const info = doc.line(line + 1);
    return Math.min(info.from + Math.max(0, character), info.to);
  }
}

/** Convert an LSP range to the view-model SourceRange shape (for reuse). */
export function lspRangeToSource(range: LspRange): SourceRange {
  return {
    startLine: range.start.line,
    startCol: range.start.character,
    endLine: range.end.line,
    endCol: range.end.character,
  };
}
