/**
 * Participant box — the frame around a run of lifelines sharing an owner.
 *
 * The pilot draws this as PlantUML's `box "<owner>" … end box`, and
 * `render_sequence_dot` (`crates/smlml-cli/src/cmd/render.rs`) draws it as a
 * solid grey DOT cluster with the owner's name in bold. This is the same
 * frame in React Flow's language.
 *
 * It stamps no `data-form`. Form is a property of a *wire node*, and the wire
 * carries no element for this frame: `sequenceLayout`'s `ownerOf` reads the
 * grouping back off the participants' own qualified-name paths, exactly as the
 * DOT painter does and for the reason recorded there. Stamping a form here
 * would put a box the model never declared into the conformance probe's
 * per-form counts.
 */

import React from "react";

export function SequenceBoxNode({ data }: { data: Record<string, unknown> }) {
  const label = (data.label as string | undefined) ?? "";
  return (
    <div className="smlml-seqbox">
      <div className="smlml-seqbox-label" title={label}>
        {label}
      </div>
    </div>
  );
}
