/**
 * The About dialog: what this build is, and where it came from.
 *
 * Every field is injected by `esbuild.config.js` from a file that already holds
 * the fact (both editors' `package.json`, plus `git rev-parse`), so nothing
 * here can drift from the build it describes — see `buildInfo()` there.
 *
 * The repository URL and deployed license are rendered as anchors. Everything
 * else is inert text.
 */

/** Injected at build time as a JSON string; see `esbuild.config.js`. */
declare const __SMLML_BUILD__: string;

export interface BuildInfo {
  shortName: string;
  tagline: string;
  overview: string;
  author: string;
  capabilities: Array<{ title: string; description: string }>;
  releases: Array<{ version: string; label: string; highlights: string[] }>;
  name: string;
  version: string;
  description: string;
  license: string;
  publisher: string;
  repository: string;
  commit: string;
  built: string;
}

/**
 * The build metadata, or a placeholder when the define is absent.
 *
 * The fallback is what a unit test or an unbundled `tsx` run sees: reading an
 * undeclared identifier is a ReferenceError, and About is not worth a crash.
 */
export function buildInfo(): BuildInfo {
  try {
    return JSON.parse(__SMLML_BUILD__) as BuildInfo;
  } catch {
    return {
      name: "smlml-web",
      shortName: "smlml",
      tagline: "SysML v2 and KerML language tooling, everywhere.",
      overview: "SysML v2 / KerML editor and viewer.",
      author: "unknown",
      capabilities: [],
      releases: [],
      version: "unknown",
      description: "SysML v2 / KerML editor and viewer.",
      license: "unknown",
      publisher: "unknown",
      repository: "unknown",
      commit: "unknown",
      built: "unknown",
    };
  }
}

/**
 * Strip the `git+…​.git` decoration a package.json repository URL carries.
 *
 * Returns `null` for anything that is not http(s) after stripping — an `ssh://`
 * or `git@host:org/repo` remote is not a page a browser can open, and rendering
 * it as an anchor would produce a link that navigates nowhere.
 */
export function webUrl(repository: string): string | null {
  const url = repository.replace(/^git\+/, "").replace(/\.git$/, "");
  return /^https?:\/\//.test(url) ? url : null;
}

/** Show the About modal. Resolves when it is dismissed. */
export function showAbout(): Promise<void> {
  const info = buildInfo();
  return new Promise<void>((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "modal-overlay";
    const box = document.createElement("div");
    box.className = "modal-box about-box";

    const title = document.createElement("div");
    title.className = "about-title";
    title.textContent = info.shortName;
    const sub = document.createElement("div");
    sub.className = "about-sub";
    sub.textContent = info.tagline;

    const overview = document.createElement("p");
    overview.className = "about-overview";
    overview.textContent = info.overview;

    const heading = (text: string) => {
      const element = document.createElement("h3");
      element.className = "about-heading";
      element.textContent = text;
      return element;
    };

    const capabilities = document.createElement("div");
    capabilities.className = "about-capabilities";
    for (const capability of info.capabilities) {
      const card = document.createElement("div");
      card.className = "about-capability";
      const strong = document.createElement("strong");
      strong.textContent = capability.title;
      const detail = document.createElement("span");
      detail.textContent = capability.description;
      card.append(strong, detail);
      capabilities.appendChild(card);
    }

    const rows = document.createElement("dl");
    rows.className = "about-rows";
    const add = (label: string, value: Node | string) => {
      const dt = document.createElement("dt");
      dt.textContent = label;
      const dd = document.createElement("dd");
      if (typeof value === "string") dd.textContent = value;
      else dd.appendChild(value);
      rows.append(dt, dd);
    };

    add("Version", `${info.version} (${info.commit})`);
    add("Built", info.built);
    add("Author", info.author);

    const license = document.createElement("a");
    license.href = "./LICENSE.txt";
    license.textContent = info.license;
    license.target = "_blank";
    license.rel = "noopener noreferrer";
    add("License", license);

    const url = webUrl(info.repository);
    if (url) {
      const a = document.createElement("a");
      a.href = url;
      a.textContent = url;
      a.target = "_blank";
      // Opening a page in a new tab hands it a `window.opener` back to this
      // document unless it is severed; `noreferrer` implies `noopener`, and
      // both are named so removing one does not silently drop the other.
      a.rel = "noopener noreferrer";
      add("Repository", a);
    } else {
      add("Repository", info.repository);
    }

    const releaseList = document.createElement("div");
    releaseList.className = "about-releases";
    for (const release of info.releases) {
      const item = document.createElement("details");
      if (release === info.releases[0]) item.open = true;
      const summary = document.createElement("summary");
      summary.textContent = `${release.version} — ${release.label}`;
      const list = document.createElement("ul");
      for (const highlight of release.highlights) {
        const li = document.createElement("li");
        li.textContent = highlight;
        list.appendChild(li);
      }
      item.append(summary, list);
      releaseList.appendChild(item);
    }

    const actions = document.createElement("div");
    actions.className = "modal-actions";
    const close = document.createElement("button");
    close.className = "modal-btn primary";
    close.textContent = "Close";
    actions.appendChild(close);

    box.append(title, sub, overview);
    if (info.capabilities.length > 0) box.append(heading("Capabilities"), capabilities);
    box.append(heading("Build information"), rows);
    if (info.releases.length > 0) box.append(heading("What’s new"), releaseList);
    box.append(actions);
    overlay.appendChild(box);

    function finish(): void {
      overlay.remove();
      document.removeEventListener("keydown", onKey, true);
      resolve();
    }
    function onKey(e: KeyboardEvent): void {
      if (e.key === "Escape") finish();
    }

    close.addEventListener("click", finish);
    overlay.addEventListener("mousedown", (e) => {
      if (e.target === overlay) finish();
    });
    document.addEventListener("keydown", onKey, true);
    document.body.appendChild(overlay);
    close.focus();
  });
}
