/**
 * Shared geometry helpers for the two edge renderers (`FloatingEdge`,
 * `RoutedEdge`). Extracted so `RoutedEdge` can fall back to the exact same
 * "floating" path a dragged node needs without importing the `FloatingEdge`
 * component itself (which would create a module cycle, since `FloatingEdge`
 * imports `RoutedEdge` for `EDGE_TYPES`).
 */

import {
  getBezierPath,
  getStraightPath,
  getSmoothStepPath,
  Position,
  type InternalNode,
  type Node,
} from "@xyflow/react";

/** Point where the centre→centre line crosses `intersectionNode`'s border. */
export function nodeIntersection(intersectionNode: InternalNode<Node>, targetNode: InternalNode<Node>) {
  const w = (intersectionNode.measured.width ?? 0) / 2;
  const h = (intersectionNode.measured.height ?? 0) / 2;
  const ipos = intersectionNode.internals.positionAbsolute;
  const tpos = targetNode.internals.positionAbsolute;

  const x2 = ipos.x + w;
  const y2 = ipos.y + h;
  const x1 = tpos.x + (targetNode.measured.width ?? 0) / 2;
  const y1 = tpos.y + (targetNode.measured.height ?? 0) / 2;

  if (w === 0 || h === 0) return { x: x2, y: y2 };

  const xx1 = (x1 - x2) / (2 * w) - (y1 - y2) / (2 * h);
  const yy1 = (x1 - x2) / (2 * w) + (y1 - y2) / (2 * h);
  const denom = Math.abs(xx1) + Math.abs(yy1);
  const a = denom === 0 ? 0 : 1 / denom;
  const xx3 = a * xx1;
  const yy3 = a * yy1;
  return { x: w * (xx3 + yy3) + x2, y: h * (-xx3 + yy3) + y2 };
}

/** Which side of `node` the point `p` sits on (for orthogonal routing). */
export function sideOf(node: InternalNode<Node>, p: { x: number; y: number }): Position {
  const px = Math.round(p.x);
  const py = Math.round(p.y);
  const nx = Math.round(node.internals.positionAbsolute.x);
  const ny = Math.round(node.internals.positionAbsolute.y);
  const w = node.measured.width ?? 0;
  if (px <= nx + 1) return Position.Left;
  if (px >= nx + w - 1) return Position.Right;
  if (py <= ny + 1) return Position.Top;
  return Position.Bottom;
}

export function edgeParams(source: InternalNode<Node>, target: InternalNode<Node>) {
  const sp = nodeIntersection(source, target);
  const tp = nodeIntersection(target, source);
  return {
    sx: sp.x, sy: sp.y, tx: tp.x, ty: tp.y,
    sourcePos: sideOf(source, sp),
    targetPos: sideOf(target, tp),
  };
}

/**
 * The floating (border-intersection) path between two live nodes, picking
 * the concrete path-drawing function from ELK's routing algorithm the same
 * way `FloatingEdge` does. Shared so `RoutedEdge` can fall back to exactly
 * this when a node has been dragged away from its laid-out position.
 */
export function computeFloatingPath(
  source: InternalNode<Node>,
  target: InternalNode<Node>,
  routing: string | undefined,
  sourceInset = 0,
  targetInset = 0,
): [path: string, labelX: number, labelY: number, ...rest: number[]] {
  const params = edgeParams(source, target);
  const sourcePoint = insetEndpoint({ x: params.sx, y: params.sy }, params.sourcePos, sourceInset);
  const targetPoint = insetEndpoint({ x: params.tx, y: params.ty }, params.targetPos, targetInset);
  const { sourcePos, targetPos } = params;
  const { x: sx, y: sy } = sourcePoint;
  const { x: tx, y: ty } = targetPoint;
  if (routing === "straight") {
    return getStraightPath({ sourceX: sx, sourceY: sy, targetX: tx, targetY: ty });
  }
  if (routing === "step") {
    return getSmoothStepPath({
      sourceX: sx, sourceY: sy, targetX: tx, targetY: ty,
      sourcePosition: sourcePos, targetPosition: targetPos, borderRadius: 4,
    });
  }
  return getBezierPath({
    sourceX: sx, sourceY: sy, targetX: tx, targetY: ty,
    sourcePosition: sourcePos, targetPosition: targetPos,
  });
}

/** Move a path endpoint away from its node along that endpoint's tangent. */
export function insetEndpoint(
  point: { x: number; y: number },
  side: Position,
  distance: number,
): { x: number; y: number } {
  switch (side) {
    case Position.Left: return { x: point.x - distance, y: point.y };
    case Position.Right: return { x: point.x + distance, y: point.y };
    case Position.Top: return { x: point.x, y: point.y - distance };
    case Position.Bottom: return { x: point.x, y: point.y + distance };
  }
}

/** Trim a routed polyline at both ends while preserving all interior bends. */
export function insetPolylineEnds(
  points: PolyPoint[],
  startInset: number,
  endInset: number,
): PolyPoint[] {
  if (points.length < 2) return points;
  const out = points.map(point => ({ ...point }));
  const inset = (index: number, neighbour: number, distance: number) => {
    if (distance <= 0) return;
    const dx = out[neighbour].x - out[index].x;
    const dy = out[neighbour].y - out[index].y;
    const length = Math.hypot(dx, dy);
    if (length === 0) return;
    const amount = Math.min(distance, length);
    out[index].x += dx / length * amount;
    out[index].y += dy / length * amount;
  };
  inset(0, 1, startInset);
  inset(out.length - 1, out.length - 2, endInset);
  return out;
}

/** A point pinned in flow space, e.g. the position ELK laid a node out at. */
export interface LayoutPoint { x: number; y: number }

/**
 * Has `node`'s live position drifted from the position it was laid out at
 * (`baked`)? Used to detect a user drag: `RoutedEdge` draws a route frozen at
 * layout time, so once a node moves the frozen route no longer starts/ends
 * where the node's border actually is — this is the signal to fall back to
 * `computeFloatingPath`, which re-derives the border intersection from the
 * node's *current* position on every render.
 *
 * `eps` absorbs float/rounding noise (see `endpointGap`'s doc block in
 * `metrics.mjs` for the same sub-pixel-disagreement phenomenon) — it is not
 * meant to tolerate a real drag distance.
 */
export function hasDrifted(
  node: InternalNode<Node> | undefined,
  baked: LayoutPoint | undefined,
  eps = 0.5
): boolean {
  if (!node || !baked) return false;
  const p = node.internals.positionAbsolute;
  return Math.abs(p.x - baked.x) > eps || Math.abs(p.y - baked.y) > eps;
}

// ─────────────────────────── Marker clearance ────────────────────────────────

export interface PolyPoint { x: number; y: number }

/**
 * Move an edge's last corner far enough from its endpoint that the end
 * decoration sits on a straight run.
 *
 * An SVG marker is painted along the path direction at the endpoint, so it
 * occupies the final `reach` px of the path. ELK routes the approach segment on
 * a slot grid whose first slot is a fixed 10px from the node border — a
 * constant internal to its router, unmoved by `elk.spacing.edgeNode` or
 * `elk.layered.spacing.edgeNodeBetweenLayers` (both were tried at 3x their
 * value and the segment stayed 10px). So a 14px triangle or a 19px diamond
 * straddles the corner, and what the reader sees is the line arriving at the
 * *side* of the glyph instead of its base — the defect in
 * `tree/3c-Function-based Behavior-structure mod-2`.
 *
 * The fix is a local nudge of the route, not a redraw of it: slide the corner
 * back along the approach axis by the shortfall (at most `reach - 10` px), and
 * slide the vertex before it by the same amount so the run into that corner
 * stays parallel to where it was. The segment before *that* simply gets
 * shorter. Both endpoints are left exactly where ELK put them — on their node's
 * border — so nothing this function does can move an endpoint off the boundary
 * it was routed to.
 *
 * Returns a new array; the input is not modified. A polyline with fewer than
 * three points has no corner to move and is returned unchanged.
 */
export function reserveMarkerRuns(
  points: PolyPoint[],
  startReach: number,
  endReach: number
): PolyPoint[] {
  if (points.length < 3) return points;
  const out = points.map(p => ({ ...p }));

  /**
   * `end` picks which end to work from: the endpoint is `out[e]`, its corner
   * `out[c]`, and `out[b]` the vertex before that. `b` is skipped when it is
   * the *other* endpoint, which must not move.
   */
  const widen = (e: number, c: number, b: number, reach: number) => {
    if (reach <= 0) return;
    const dx = out[c].x - out[e].x;
    const dy = out[c].y - out[e].y;
    const len = Math.hypot(dx, dy);
    // A zero-length final segment has no direction to widen along; leave it.
    if (len === 0 || len >= reach) return;
    const k = (reach - len) / len;   // fraction of the segment to add
    const ox = dx * k;
    const oy = dy * k;
    out[c] = { x: out[c].x + ox, y: out[c].y + oy };
    if (b >= 0 && b !== 0 && b !== points.length - 1) {
      out[b] = { x: out[b].x + ox, y: out[b].y + oy };
    }
  };

  const n = out.length;
  widen(n - 1, n - 2, n - 3, endReach);
  widen(0, 1, 2, startReach);
  return out;
}
