/**
 * Toolbar — theme switching, File and AST menus, Format / Reparse, the status
 * pill, and the file-browser toggle. Source language comes from the file suffix.
 */

import { showAbout } from "./about.ts";

export type StatusKind = "starting" | "analyzing" | "ok" | "warning" | "error";

/**
 * Pill kind + text for a given error/warning split.
 *
 * Errors and warnings are reported separately rather than as one combined
 * "N problems" count: an error-free file with only namespace-collision
 * warnings must not read the same as a clean one, and must not read the same
 * as a file that still fails to compile.
 */
export function pillStatus(errors: number, warnings: number): { kind: StatusKind; text: string } {
  if (errors > 0) {
    const w = warnings > 0 ? `, ${warnings} warning${warnings === 1 ? "" : "s"}` : "";
    return { kind: "error", text: `${errors} error${errors === 1 ? "" : "s"}${w}` };
  }
  if (warnings > 0) {
    return { kind: "warning", text: `${warnings} warning${warnings === 1 ? "" : "s"}` };
  }
  return { kind: "ok", text: "no problems" };
}

export interface ToolbarCallbacks {
  onToggleFiles(): void;
  onNavigateBack(): void;
  onNavigateForward(): void;
  onFormat(): void;
  onReparse(): void;
  /** Raw files chosen for import (.zip / loose .sysml / .kerml). */
  onImportFiles(files: File[]): void;
  onExport(): void;
  /** Wipe every file and folder (the caller confirms first). */
  onClearWorkspace(): void;
  /** Reload the example workspace on demand, replacing the current workspace. */
  onLoadExamples(): void;
  /** Export the active file's dependency closure as OMG DataVersion JSON. */
  onExportAst(): void;
  /** Import an AST JSON file, splitting it into one source file per root. */
  onImportAstFile(file: File): void;
  onOpenProblems(): void;
  onToggleEval(enabled: boolean): void;
}

type ThemeMode = "light" | "dark" | "system";

export class Toolbar {
  private themeMode: ThemeMode;
  private evalEnabled = true;
  private readonly mql = window.matchMedia("(prefers-color-scheme: dark)");

  constructor(private readonly cbs: ToolbarCallbacks) {
    this.themeMode = (localStorage.getItem("smlml-theme") as ThemeMode) || "system";
    this.wireTheme();
    this.wireButtons();
    this.applyTheme(this.themeMode);
  }

  setStatus(kind: StatusKind, text: string): void {
    const pill = document.getElementById("status")!;
    pill.classList.toggle("ok", kind === "ok");
    pill.classList.toggle("err", kind === "error");
    // Warnings-only (e.g. an unresolved namespace collision) get their own
    // class rather than falling back to the unstyled default: the dot is
    // already amber without it, but the class is the hook a reader — or a
    // future style — can key "there is something, but it does not block you" on.
    pill.classList.toggle("warn", kind === "warning");
    // Amber (the default dot colour) plus a busy cursor, so "still working" is
    // visibly distinct from "done, and fine".
    pill.classList.toggle("busy", kind === "analyzing");
    document.getElementById("status-text")!.textContent = text;
  }

  setNavigationState(canGoBack: boolean, canGoForward: boolean): void {
    const back = document.querySelector<HTMLButtonElement>("#btn-nav-back");
    const forward = document.querySelector<HTMLButtonElement>("#btn-nav-forward");
    if (back) back.disabled = !canGoBack;
    if (forward) forward.disabled = !canGoForward;
  }

  /**
   * Gate the "Export AST JSON" menu action behind unresolved errors — the
   * export walks a dependency closure that a broken model cannot honestly
   * describe.  `tooltip` is only applied while disabled.
   */
  setExportGate(disabled: boolean, tooltip: string): void {
    const btn = document.querySelector<HTMLButtonElement>('#ast-menu button[data-act="export"]');
    if (!btn) return;
    btn.disabled = disabled;
    btn.title = disabled ? tooltip : "";
  }

  /**
   * How many features the last solve resolved, shown on the Eval button.
   *
   * Hidden at zero rather than shown as "0": the button already reads as
   * inactive when evaluation is off, and a permanent zero on a file with no
   * calcs is noise. Counts are abbreviated (`1.2k`, `3.4M`) so a large model
   * cannot widen the toolbar.
   */
  setEvalCount(n: number): void {
    const el = document.getElementById("count-eval");
    if (!el) return;
    el.textContent = formatCount(n);
    el.classList.toggle("hidden", !this.evalEnabled || n === 0);
  }

  // ─────────────────────────── theme ───────────────────────────

  private themeClass(mode: ThemeMode): string {
    if (mode === "system") return this.mql.matches ? "vscode-dark" : "vscode-light";
    return mode === "dark" ? "vscode-dark" : "vscode-light";
  }

  private applyTheme(mode: ThemeMode): void {
    document.body.classList.remove("vscode-dark", "vscode-light");
    document.body.classList.add(this.themeClass(mode));
    localStorage.setItem("smlml-theme", mode);
    document
      .querySelectorAll<HTMLButtonElement>("#theme-seg button")
      .forEach((b) => b.classList.toggle("active", b.dataset.mode === mode));
  }

  private wireTheme(): void {
    document.querySelectorAll<HTMLButtonElement>("#theme-seg button").forEach((b) =>
      b.addEventListener("click", () => {
        this.themeMode = b.dataset.mode as ThemeMode;
        this.applyTheme(this.themeMode);
      })
    );
    this.mql.addEventListener("change", () => {
      if (this.themeMode === "system") this.applyTheme("system");
    });
  }

  // ─────────────────────────── buttons ───────────────────────────

  private wireButtons(): void {
    document.getElementById("btn-files")?.addEventListener("click", () => this.cbs.onToggleFiles());
    document.getElementById("btn-nav-back")?.addEventListener("click", () => this.cbs.onNavigateBack());
    document.getElementById("btn-nav-forward")?.addEventListener("click", () => this.cbs.onNavigateForward());
    document.getElementById("btn-format")?.addEventListener("click", () => this.cbs.onFormat());
    document.getElementById("btn-reparse")?.addEventListener("click", () => this.cbs.onReparse());
    document.getElementById("btn-export")?.addEventListener("click", () => this.cbs.onExport());
    document.getElementById("btn-clear")?.addEventListener("click", () => this.cbs.onClearWorkspace());
    document
      .getElementById("btn-load-examples")
      ?.addEventListener("click", () => this.cbs.onLoadExamples());
    document.getElementById("status")?.addEventListener("click", () => this.cbs.onOpenProblems());

    const importInput = this.makeFileInput({ multiple: true, accept: ".zip,.sysml,.kerml" }, (files) =>
      this.cbs.onImportFiles(files)
    );
    document.getElementById("btn-import")?.addEventListener("click", () => importInput.click());

    document.getElementById("btn-about")?.addEventListener("click", () => void showAbout());

    const evalBtn = document.getElementById("btn-eval");
    if (evalBtn) {
      evalBtn.classList.toggle("active", this.evalEnabled);
      evalBtn.addEventListener("click", () => {
        this.evalEnabled = !this.evalEnabled;
        evalBtn.classList.toggle("active", this.evalEnabled);
        evalBtn.title = this.evalEnabled ? "Calc evaluation: on (click to disable)" : "Calc evaluation: off (click to enable)";
        // Switching evaluation off leaves the last count on screen describing
        // results that are no longer being computed; `setEvalCount` hides the
        // badge whenever evaluation is off, so re-asserting it here is what
        // clears it.
        if (!this.evalEnabled) this.setEvalCount(0);
        this.cbs.onToggleEval(this.evalEnabled);
      });
    }

    // Dropdown menus — only one stays open, and selecting any action closes it.
    const fileBtn = document.getElementById("btn-workspace");
    const fileMenu = document.getElementById("workspace-menu");
    const astBtn = document.getElementById("btn-ast");
    const astMenu = document.getElementById("ast-menu");
    const setOpen = (btn: HTMLElement | null, menu: HTMLElement | null, open: boolean): void => {
      menu?.classList.toggle("open", open);
      btn?.setAttribute("aria-expanded", String(open));
    };
    fileBtn?.addEventListener("click", () => {
      const open = !fileMenu?.classList.contains("open");
      setOpen(astBtn, astMenu, false);
      setOpen(fileBtn, fileMenu, open);
    });
    astBtn?.addEventListener("click", () => {
      const open = !astMenu?.classList.contains("open");
      setOpen(fileBtn, fileMenu, false);
      setOpen(astBtn, astMenu, open);
    });
    document.addEventListener("click", (e) => {
      const target = e.target as Node;
      if (!fileMenu?.contains(target) && !fileBtn?.contains(target)) setOpen(fileBtn, fileMenu, false);
      if (!astMenu?.contains(target) && !astBtn?.contains(target)) setOpen(astBtn, astMenu, false);
    });
    fileMenu?.querySelectorAll("button").forEach((b) =>
      b.addEventListener("click", () => setOpen(fileBtn, fileMenu, false))
    );

    const astImportInput = this.makeFileInput({ accept: ".json,application/json" }, (files) => {
      if (files[0]) this.cbs.onImportAstFile(files[0]);
    });

    astMenu?.querySelectorAll<HTMLButtonElement>("button[data-act]").forEach((b) =>
      b.addEventListener("click", () => {
        setOpen(astBtn, astMenu, false);
        if (b.dataset.act === "export") this.cbs.onExportAst();
        else astImportInput.click();
      })
    );
  }

  private makeFileInput(
    opts: { multiple?: boolean; accept?: string },
    handler: (files: File[]) => void
  ): HTMLInputElement {
    const input = document.createElement("input");
    input.type = "file";
    input.style.display = "none";
    if (opts.multiple) input.multiple = true;
    if (opts.accept) input.accept = opts.accept;
    input.addEventListener("change", () => {
      handler(Array.from(input.files ?? []));
      input.value = "";
    });
    document.body.appendChild(input);
    return input;
  }
}

/**
 * A count short enough to sit on a toolbar button: `999`, `1.2k`, `3.4M`.
 *
 * Rounds toward zero rather than nearest, so the badge never claims a
 * threshold the model has not reached (999,999 reads `999k`, not `1M`).
 */
export function formatCount(n: number): string {
  if (!Number.isFinite(n) || n < 0) return "0";
  if (n < 1_000) return String(Math.trunc(n));
  const [value, suffix] =
    n < 1_000_000 ? [n / 1_000, "k"]
    : n < 1_000_000_000 ? [n / 1_000_000, "M"]
    : [n / 1_000_000_000, "B"];
  const truncated = Math.trunc(value * 10) / 10;
  // Drop a trailing `.0`: "12k" reads better than "12.0k", and at three
  // significant figures the tenth carries no information anyway.
  return `${truncated % 1 === 0 ? Math.trunc(truncated) : truncated.toFixed(1)}${suffix}`;
}
