import { FAMILY_HUES } from "./palette";
import { LoadingOverlay } from "./LoadingOverlay";
// Split out of the initial bundle: `GeometryView` is the only importer of
// `three`, `@react-three/fiber`, and `@react-three/drei` (which itself pulls
// `@mediapipe/tasks-vision` and `hls.js`). A static import puts all of that in
// `app.js` for every user, including the majority who never open the Geometry
// view. This mirrors the ELK treatment in `layout.ts`.
const GeometryView = React.lazy(() =>
  import("./GeometryView").then(({ GeometryView }) => ({ default: GeometryView })),
);

