/**
 * One place that turns "how long did that take?" into a log line.
 *
 * Before this, four things were timed — WASM instantiate, `wasm_init`, the
 * transport handshake and `initialize` — and everything else the user waits on
 * was silent: AST export and import, format, reparse, view build, workspace
 * load. Each of those had its own `log.log(...)` line already; wrapping them
 * here means the duration is added at one site with one format, rather than
 * seven hand-written `performance.now()` deltas that can disagree.
 *
 * `performance.now()` rather than `Date.now()`: it is monotonic, so a clock
 * adjustment mid-operation cannot produce a negative duration.
 */

import type { LogSink, LogTag } from "../types.ts";

/** A duration, in the log's one format. */
export function formatMs(ms: number): string {
  return `${ms.toFixed(0)} ms`;
}

/**
 * Run `fn`, log its duration under `tag`, and return its value.
 *
 * `detail` optionally turns the result into a short suffix — "3 file(s)" — so a
 * call site that already logged a count keeps logging it, now with the time
 * attached. A throw is logged too, at `warn`, and rethrown: an operation that
 * failed after four seconds is exactly the one whose timing matters.
 */
export async function timed<T>(
  log: LogSink,
  tag: LogTag,
  label: string,
  fn: () => Promise<T>,
  detail?: (value: T) => string
): Promise<T> {
  const t0 = performance.now();
  try {
    const value = await fn();
    const suffix = detail ? ` — ${detail(value)}` : "";
    log.log(tag, `${label}${suffix} in ${formatMs(performance.now() - t0)}`, "op");
    return value;
  } catch (err) {
    log.log(tag, `${label} failed after ${formatMs(performance.now() - t0)}: ${String(err)}`, "warn");
    throw err;
  }
}

/** `timed` for synchronous work (the seed/zip workspace load). */
export function timedSync<T>(
  log: LogSink,
  tag: LogTag,
  label: string,
  fn: () => T,
  detail?: (value: T) => string
): T {
  const t0 = performance.now();
  try {
    const value = fn();
    const suffix = detail ? ` — ${detail(value)}` : "";
    log.log(tag, `${label}${suffix} in ${formatMs(performance.now() - t0)}`, "op");
    return value;
  } catch (err) {
    log.log(tag, `${label} failed after ${formatMs(performance.now() - t0)}: ${String(err)}`, "warn");
    throw err;
  }
}
