/**
 * CodeMirror decoration layer fed from `textDocument/semanticTokens/full`.
 *
 * The LSP returns a flat array (5 ints per token: deltaLine, deltaStart, length,
 * tokenType, tokenModifiers).  We decode it to absolute positions and map each
 * token type (per the server legend in smlml-lsp) to a `tok-*` CSS class defined
 * in theme.css.
 */

import { EditorState, StateEffect, StateField, type Extension } from "@codemirror/state";
import { Decoration, EditorView, type DecorationSet } from "@codemirror/view";

/** Server legend order (smlml-lsp): NAMESPACE, TYPE, VARIABLE, KEYWORD, COMMENT. */
const TOKEN_CLASS: Record<number, string> = {
  0: "tok-type", // namespace
  1: "tok-type", // type
  2: "tok-id", // variable
  3: "tok-kw", // keyword
  4: "tok-cmt", // comment
};

export const setSemanticTokens = StateEffect.define<number[]>();

function buildDecorations(state: EditorState, data: number[]): DecorationSet {
  const marks: ReturnType<typeof Decoration.mark>[] = [];
  const ranges: { from: number; to: number; deco: Decoration }[] = [];
  let line = 0;
  let char = 0;
  for (let i = 0; i + 4 < data.length; i += 5) {
    const deltaLine = data[i];
    const deltaStart = data[i + 1];
    const length = data[i + 2];
    const tokenType = data[i + 3];
    if (deltaLine > 0) {
      line += deltaLine;
      char = deltaStart;
    } else {
      char += deltaStart;
    }
    const cls = TOKEN_CLASS[tokenType];
    if (!cls || length <= 0) continue;
    if (line >= state.doc.lines) continue;
    const lineInfo = state.doc.line(line + 1);
    const from = Math.min(lineInfo.from + char, lineInfo.to);
    const to = Math.min(from + length, lineInfo.to);
    if (to <= from) continue;
    ranges.push({ from, to, deco: Decoration.mark({ class: cls }) });
  }
  void marks;
  ranges.sort((a, b) => a.from - b.from || a.to - b.to);
  return Decoration.set(
    ranges.map((r) => r.deco.range(r.from, r.to)),
    true
  );
}

export function semanticTokensExtension(): Extension {
  return StateField.define<DecorationSet>({
    create: () => Decoration.none,
    update(deco, tr) {
      let next = tr.docChanged ? deco.map(tr.changes) : deco;
      for (const e of tr.effects) {
        if (e.is(setSemanticTokens)) {
          next = buildDecorations(tr.state, e.value);
        }
      }
      return next;
    },
    provide: (f) => EditorView.decorations.from(f),
  });
}
