/**
 * Edge selection — click a relation, and the relation *and both the elements it
 * relates* light up.
 *
 * A line on a dense canvas is hard to follow with the eye alone: an edge and
 * its two endpoints are one fact, and reading it meant tracing the line by
 * hand. `TreeFlowView` and `MetamodelFlowView` already framed both endpoints on
 * click, which moves the viewport but marks nothing; the other views did not
 * even do that.
 *
 * The decoration is applied here, as class names, rather than by each view
 * re-implementing the same three-way map — the views already carry four
 * near-identical copies of the search/cursor decoration pass, and this is the
 * same shape again. Classes rather than inline style so `theme.css` owns the
 * appearance and `contrast.vtest.ts` can see it.
 *
 * Selection is cleared by clicking the empty canvas (`onPaneClick`), which is
 * the gesture readers already use to dismiss a React Flow selection.
 */

import { useCallback, useState } from "react";
import type { Edge, Node } from "@xyflow/react";

export interface EdgeSelection {
  /** The selected edge's id, or undefined when nothing is selected. */
  selectedEdgeId: string | undefined;
  /** Wire to `<ReactFlow onEdgeClick>`. */
  onEdgeClick: (event: unknown, edge: Edge) => void;
  /** Wire to `<ReactFlow onPaneClick>` — clicking the canvas clears it. */
  onPaneClick: () => void;
  /** Add `smlml-edge-selected` / `smlml-node-endpoint` to the affected items. */
  decorate: (nodes: Node[], edges: Edge[]) => { nodes: Node[]; edges: Edge[] };
}

/** Append `cls` to an existing className without dropping what was there. */
function withClass<T extends { className?: string }>(item: T, cls: string): T {
  return { ...item, className: [item.className, cls].filter(Boolean).join(" ") };
}

export function useEdgeSelection(onSelect?: (edge: Edge) => void): EdgeSelection {
  const [selectedEdgeId, setSelectedEdgeId] = useState<string | undefined>(undefined);

  const onEdgeClick = useCallback(
    (_event: unknown, edge: Edge) => {
      // Clicking the selected edge again clears it, so the decoration is
      // dismissable without hunting for empty canvas on a dense graph.
      setSelectedEdgeId(prev => (prev === edge.id ? undefined : edge.id));
      onSelect?.(edge);
    },
    [onSelect]
  );

  const onPaneClick = useCallback(() => setSelectedEdgeId(undefined), []);

  const decorate = useCallback(
    (nodes: Node[], edges: Edge[]) => {
      if (!selectedEdgeId) return { nodes, edges };
      const selected = edges.find(e => e.id === selectedEdgeId);
      // The selected edge can vanish under the reader — a re-layout after an
      // edit rebuilds the edge list — so an id with no edge decorates nothing
      // rather than marking endpoints of a relation no longer on screen.
      if (!selected) return { nodes, edges };
      const ends = new Set([selected.source, selected.target]);
      return {
        nodes: nodes.map(n => (ends.has(n.id) ? withClass(n, "smlml-node-endpoint") : n)),
        edges: edges.map(e => (e.id === selectedEdgeId ? withClass(e, "smlml-edge-selected") : e)),
      };
    },
    [selectedEdgeId]
  );

  return { selectedEdgeId, onEdgeClick, onPaneClick, decorate };
}
