/**
 * Workspace persistence.
 *
 * Two facts drove the choice of IndexedDB. It is available in every current
 * browser and needs no permission prompt — note that
 * `navigator.storage.persist()`, which DOES prompt, only asks for eviction
 * resistance and is not needed for this. And a workspace is a set of whole
 * source files: `localStorage` is a synchronous ~5 MB string store, which is
 * both the wrong shape and a main-thread stall on every save.
 *
 * `SnapshotStore` is an interface, not a class, for one reason: everything
 * interesting here — what is captured, when it is written, and what happens
 * when storage is blocked — is testable against an in-memory implementation on
 * a runner that has no `indexedDB` at all. Only the API binding below is left
 * to browser verification.
 */

import type { ZipEntry } from "./zip.ts";
import type { WorkspaceStore } from "./workspace-store.ts";

/** Everything about a workspace worth surviving a reload. */
export interface WorkspaceSnapshot {
  files: ZipEntry[];
  /** Explicitly-created folders, including empty ones. */
  folders: string[];
  /** Workspace-relative path of the active file, or null when there is none. */
  activePath: string | null;
}

export interface SnapshotStore {
  /** The stored snapshot, or null when nothing has been stored yet. */
  load(): Promise<WorkspaceSnapshot | null>;
  save(snapshot: WorkspaceSnapshot): Promise<void>;
  clear(): Promise<void>;
}

/** The current state of `store`, in snapshot form. */
export function snapshotOf(store: WorkspaceStore): WorkspaceSnapshot {
  const active = store.activeFile;
  return {
    files: store.toEntries(),
    folders: store.folderPaths(),
    activePath: active ? active.path : null,
  };
}

/**
 * Validate a raw stored record, element by element.
 *
 * `Array.isArray(raw.files)` alone would accept `["a.sysml"]` or
 * `[{ path: "a.sysml" }]`, and the missing `text` only surfaces much later, as a
 * throw from `normalizePath(undefined)` deep inside `replaceAll` — which lands
 * in the boot catch and reports "WASM failed" on every subsequent reload.
 *
 * A record that fails any element check is REJECTED whole rather than repaired:
 * a record we cannot fully trust is far more likely truncated mid-write than
 * genuinely half-valid, and silently restoring the readable half would lose
 * files without saying so. Rejecting means the caller seeds the examples, which
 * is visible and recoverable. An empty `files: []` is valid, not corrupt — that
 * is exactly what a deliberate "Clear workspace" stores.
 */
export function sanitizeSnapshot(raw: unknown): WorkspaceSnapshot | null {
  if (!raw || typeof raw !== "object") return null;
  const rec = raw as { files?: unknown; folders?: unknown; activePath?: unknown };
  if (!Array.isArray(rec.files)) return null;

  const files: ZipEntry[] = [];
  for (const f of rec.files) {
    if (!f || typeof f !== "object") return null;
    const { path, text } = f as { path?: unknown; text?: unknown };
    if (typeof path !== "string" || typeof text !== "string") return null;
    files.push({ path, text });
  }

  let folders: string[] = [];
  if (rec.folders !== undefined) {
    if (!Array.isArray(rec.folders)) return null;
    if (rec.folders.some((d) => typeof d !== "string")) return null;
    folders = [...(rec.folders as string[])];
  }

  return {
    files,
    folders,
    activePath: typeof rec.activePath === "string" ? rec.activePath : null,
  };
}

/**
 * Read the stored workspace, turning any failure into "there is nothing stored".
 *
 * A blocked store and a malformed record must both degrade to seeding the
 * examples — never to a boot failure. The bad record is discarded on the way
 * out (best effort) so the fallback is a one-boot event rather than a permanent
 * state that only devtools can clear.
 */
export async function loadSnapshot(
  snapshots: SnapshotStore,
  opts: { onError?: (err: unknown) => void } = {}
): Promise<WorkspaceSnapshot | null> {
  try {
    return await snapshots.load();
  } catch (err) {
    opts.onError?.(err);
    try {
      await snapshots.clear();
    } catch {
      // Storage that cannot be read usually cannot be written either; the
      // warning above is the diagnosable part.
    }
    return null;
  }
}

const DB_NAME = "smlml-workspace";
const STORE_NAME = "snapshot";
const RECORD_KEY = "current";

function request<T>(req: IDBRequest<T>): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error ?? new Error("IndexedDB request failed"));
  });
}

function openDb(dbName: string): Promise<IDBDatabase> {
  return new Promise<IDBDatabase>((resolve, reject) => {
    // Some embedded WebViews expose `indexedDB` as `null` rather than leaving it
    // undefined, so both shapes are checked. A blocked-storage context can also
    // make the property GETTER throw, which happens on the line below and is
    // carried out of this executor as a rejection — the caller
    // (`loadSnapshot`) treats it the same as any other read failure.
    if (typeof indexedDB === "undefined" || indexedDB === null) {
      reject(new Error("IndexedDB is unavailable in this context"));
      return;
    }
    const open = indexedDB.open(dbName, 1);
    open.onupgradeneeded = () => {
      const db = open.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) db.createObjectStore(STORE_NAME);
    };
    open.onsuccess = () => resolve(open.result);
    open.onerror = () => reject(open.error ?? new Error("IndexedDB open failed"));
    // Private-browsing modes and blocked-storage settings surface here rather
    // than as a throw from `open()`.
    open.onblocked = () => reject(new Error("IndexedDB open was blocked"));
  });
}

/** The real store: one record in one object store in one database. */
export function idbSnapshotStore(dbName: string = DB_NAME): SnapshotStore {
  const withStore = async <T>(
    mode: IDBTransactionMode,
    fn: (s: IDBObjectStore) => IDBRequest<T>
  ): Promise<T> => {
    const db = await openDb(dbName);
    try {
      const tx = db.transaction(STORE_NAME, mode);
      const result = await request(fn(tx.objectStore(STORE_NAME)));
      return result;
    } finally {
      db.close();
    }
  };

  return {
    async load() {
      const raw = await withStore<unknown>("readonly", (s) =>
        s.get(RECORD_KEY) as IDBRequest<unknown>
      );
      if (raw === undefined || raw === null) return null;
      const snapshot = sanitizeSnapshot(raw);
      // Rejected rather than returned as `null`: "nothing stored" and "what is
      // stored is unusable" are different events, and only the second one is
      // worth a warning and worth discarding the record over. `loadSnapshot`
      // does both.
      if (!snapshot) throw new Error("the stored workspace record is malformed");
      return snapshot;
    },
    async save(snapshot) {
      // Structured-clone the plain data explicitly: `toEntries()` already
      // returns fresh objects, but a future field holding a class instance
      // would fail the clone at write time rather than at read time.
      await withStore("readwrite", (s) =>
        s.put(
          {
            files: snapshot.files.map((f) => ({ path: f.path, text: f.text })),
            folders: [...snapshot.folders],
            activePath: snapshot.activePath,
          },
          RECORD_KEY
        ) as IDBRequest<IDBValidKey>
      );
    },
    async clear() {
      await withStore("readwrite", (s) => s.delete(RECORD_KEY) as IDBRequest<undefined>);
    },
  };
}

/**
 * Mirror `store` into `snapshots`, debounced, until the returned disposer runs.
 *
 * Debounced because every keystroke emits a `changed` event, and a write per
 * keystroke would serialise the whole workspace on each one. A wipe is written
 * like any other change, which is what makes a clear survive a refresh.
 *
 * `onError` fires at most once per attach: a blocked store fails on every
 * write, and a log line per keystroke would bury the one that mattered.
 */
export function attachPersistence(
  store: WorkspaceStore,
  snapshots: SnapshotStore,
  opts: { debounceMs?: number; onError?: (err: unknown) => void } = {}
): () => void {
  const debounceMs = opts.debounceMs ?? 400;
  let timer: ReturnType<typeof setTimeout> | null = null;
  let reported = false;
  let disposed = false;

  const flush = (): void => {
    timer = null;
    if (disposed) return;
    void snapshots.save(snapshotOf(store)).catch((err) => {
      if (reported) return;
      reported = true;
      opts.onError?.(err);
    });
  };

  const unsubscribe = store.onEvent((e) => {
    switch (e.type) {
      case "opened":
      case "changed":
      case "closed":
      case "folders":
      case "active":
        if (timer) clearTimeout(timer);
        timer = setTimeout(flush, debounceMs);
        break;
      case "diagnostics":
        // Server output, not user content — recomputed on every load.
        break;
    }
  });

  return () => {
    disposed = true;
    if (timer) clearTimeout(timer);
    unsubscribe();
  };
}
