/**
 * Bottom dock controller — tab switching, collapse, per-tab counts, and
 * show/hide of the (initially hidden) Run tab.
 */

export type DockTab = "problems" | "values" | "run" | "log";

export class Dock {
  private readonly root: HTMLElement;
  private readonly tabs: HTMLButtonElement[];
  private readonly panes: HTMLElement[];

  constructor(root: HTMLElement) {
    this.root = root;
    this.tabs = Array.from(root.querySelectorAll<HTMLButtonElement>(".dock-tab"));
    this.panes = Array.from(root.querySelectorAll<HTMLElement>(".tabpane"));

    for (const tab of this.tabs) {
      tab.addEventListener("click", () => this.show(tab.dataset.tab as DockTab));
    }
    root.querySelector("#dock-collapse")?.addEventListener("click", () => this.toggleCollapse());
  }

  show(tab: DockTab): void {
    if (this.root.classList.contains("collapsed")) this.root.classList.remove("collapsed");
    for (const t of this.tabs) t.classList.toggle("active", t.dataset.tab === tab);
    for (const p of this.panes) p.classList.toggle("active", p.dataset.tab === tab);
  }

  toggleCollapse(): void {
    this.root.classList.toggle("collapsed");
  }

  setTabVisible(tab: DockTab, visible: boolean): void {
    this.tabs.find((t) => t.dataset.tab === tab)?.classList.toggle("hidden", !visible);
  }

  setCount(tab: "problems" | "values", n: number): void {
    const el = document.getElementById(`count-${tab}`);
    if (el) el.textContent = String(n);
  }
}
