/**
 * Run panel — simulation trace log.  Fed by ViewHost simulation step results
 * (the in-pane SimulationView drives the steps; this mirrors the trace in the
 * dock and tracks the current state).
 */

export class RunPanel {
  private steps = 0;

  constructor(private readonly container: HTMLElement) {
    this.reset();
  }

  reset(): void {
    this.steps = 0;
    this.container.innerHTML =
      `<div class="run-head"><span class="cur">current state: <b>—</b></span></div>` +
      `<div class="run-log"><div class="run-empty">No steps yet — use the Simulation view's Step control.</div></div>`;
  }

  add(currentState: string, traceText: string): void {
    const head = this.container.querySelector(".run-head .cur b");
    if (head) head.textContent = currentState || "—";

    let log = this.container.querySelector(".run-log");
    if (!log) {
      log = document.createElement("div");
      log.className = "run-log";
      this.container.appendChild(log);
    }
    const empty = log.querySelector(".run-empty");
    if (empty) empty.remove();

    this.steps += 1;
    const row = document.createElement("div");
    row.className = "levent";
    const n = document.createElement("span");
    n.className = "n";
    n.textContent = String(this.steps);
    const to = document.createElement("span");
    to.className = "to";
    to.textContent = traceText || currentState;
    row.append(n, to);
    log.appendChild(row);
    log.scrollTop = log.scrollHeight;
  }
}
