/**
 * State node — three-compartment box: name | entry/do/exit actions.
 * Active state is highlighted via data.active or data.isActive.
 *
 * Supports both v1 data (entryActions/doActions/exitActions arrays) and
 * v2 data (compartments: CompartmentEntry[]).
 * Parallel states show a "||" badge.
 */

import React from "react";
import { Handle, Position, type NodeProps } from "@xyflow/react";
import type { CompartmentEntry } from "../types";
import { useNavigate } from "../NavigateContext";
import { formOf } from "./form";

export function StateNode({ data, selected }: NodeProps) {
  const navigate = useNavigate();
  const label = data.label as string | undefined;
  // v1 compat
  const isActive = (data.active as boolean | undefined) || (data.isActive as boolean | undefined);
  const entryActions = data.entryActions as string[] | undefined;
  const doActions = data.doActions as string[] | undefined;
  const exitActions = data.exitActions as string[] | undefined;
  // v2 fields
  const compartments = (data.compartments as CompartmentEntry[] | undefined) ?? [];
  // Set by the flow view when the editor cursor is sitting on this row,
  // so a source selection reaches the attribute rather than only the box.
  const highlightCompartment = data.highlightCompartment as number | undefined;
  // Rows matching the diagram search, set by the flow view.
  const matchCompartments = data.matchCompartments as Set<number> | undefined;
  // Wrapped lines per entry, aligned with `compartments` — see DefaultNode.
  const entryLines = (data.entryLines as string[][] | undefined) ?? [];
  const isParallel = data.isParallel as boolean | undefined;
  // ARCH-4 semantic display fields: the wire label is creole-free; render
  // intent here (strikethrough noname, italic abstract, ^ inherited,
  // ~<short> ), matching DefaultNode's idiom.
  const nameSynthesized = data.nameSynthesized as boolean | undefined;
  const isAbstract = data.isAbstract as boolean | undefined;
  const isInherited = data.isInherited as boolean | undefined;
  const shortName = data.shortName as string | undefined;
  // Server-classified family, authoritative and shared with the CLI painters;
  // "default" is the wire's own fallback for a node with no family tint.
  const family = (data.family as string | undefined) ?? "default";
  const familyClass = ` fam-${family}`;

  // Build the compartment display — prefer v2 compartments when present,
  // fall back to v1 entry/do/exit arrays.
  const hasV2Compartments = compartments.length > 0;
  const hasV1Actions =
    (entryActions?.length ?? 0) > 0 ||
    (doActions?.length ?? 0) > 0 ||
    (exitActions?.length ?? 0) > 0;

  return (
    <div
      className={`smlml-state-node${familyClass}${isActive || selected ? " active" : ""}`}
      data-form={formOf(data)}
    >
      <Handle type="target" position={Position.Top} />

      <div
        className="smlml-state-name"
        style={{
          ...(nameSynthesized ? { textDecoration: "line-through" } : undefined),
          ...(isAbstract ? { fontStyle: "italic" } : undefined),
        }}
      >
        {isInherited ? "^" : ""}
        {shortName ? `~<${shortName}> ` : ""}
        {label ?? "?"}
        {isParallel && (
          <span className="smlml-parallel-badge" title="parallel state"> ‖</span>
        )}
      </div>

      {hasV2Compartments && (
        <div className="smlml-state-actions">
          {compartments.map((c, i) => (
            <div
              key={i}
              className={`smlml-compartment-entry smlml-compartment-${c.kind}${c.range && navigate ? " smlml-compartment-navigable" : ""}${i === highlightCompartment ? " smlml-compartment-highlight" : ""}${matchCompartments?.has(i) ? " smlml-compartment-match" : ""}`}
              onClick={c.range && navigate ? (e) => { e.stopPropagation(); navigate("", c.range!); } : undefined}
            >
              {c.kind !== "attribute" && c.kind !== "doc" && (
                <span className="smlml-compartment-kind">{c.kind} / </span>
              )}
              {entryLines[i]?.length
                ? entryLines[i].map((l, li) => <div key={li} className="smlml-line">{l}</div>)
                : c.label}
            </div>
          ))}
        </div>
      )}

      {!hasV2Compartments && hasV1Actions && (
        <div className="smlml-state-actions">
          {entryActions?.map((a, i) => (
            <div key={`entry-${i}`}>entry / {a}</div>
          ))}
          {doActions?.map((a, i) => (
            <div key={`do-${i}`}>do / {a}</div>
          ))}
          {exitActions?.map((a, i) => (
            <div key={`exit-${i}`}>exit / {a}</div>
          ))}
        </div>
      )}

      <Handle type="source" position={Position.Bottom} />
    </div>
  );
}
