/**
 * Real text measurement for layout sizing.
 *
 * `layout.ts` has to know how big a node will paint *before* React Flow paints
 * it, because ELK lays the whole graph out against that number. It used to
 * guess: `CHAR_W = 6.6` px per character, one average advance applied to text
 * that paints at 10px italic, 11px, and 12px medium — in `--vscode-font-family`
 * under VS Code and `system-ui` under the lab harness. One constant cannot be
 * right for six font roles in two font stacks, and the corpus said so: 63 of
 * 169 non-empty fixtures had text clipped by `overflow: hidden`, 2,697px of it
 * (Facet 0 census).
 *
 * So nothing here is estimated from a constant. Every number is read back off a
 * hidden **probe** — a real DOM subtree carrying the real `theme.css` classes,
 * appended to `document.body` so it inherits the same font stack the diagram
 * does:
 *
 *   - **widths** come from a canvas 2D context set to the probe element's own
 *     resolved `font`, because wrapping asks for many widths per node and
 *     `measureText` is far cheaper than forcing a layout per word;
 *   - **heights** come from the probe element's own `offsetHeight` with `n`
 *     line children in it — the exact structure the renderers emit — so
 *     padding, borders, margins and line-height need no arithmetic at all;
 *   - **limits** such as max node width come from CSS custom properties; the
 *     documentation height limit is derived here from the measured line height
 *     so both renderers can share the same twenty-line policy.
 *
 * Everything is memoised: the probe is built once, and each distinct
 * `(text, role)` / `(role, lineCount)` is measured once.
 *
 * **Wrapping is owned here, not by the browser.** `wrap()` computes the greedy
 * line breaks and the renderers emit one element per computed line with
 * `white-space: pre`. The rendered line count then equals the computed line
 * count *by construction*, rather than by the estimator and the browser
 * happening to agree — which is why no measure-then-relayout second pass is
 * needed.
 *
 * ## The jsdom path
 *
 * Under vitest there is no canvas 2D context and no layout engine
 * (`offsetHeight` is always 0), so measurement is impossible and the estimate
 * fallback below stands in. It is deliberately the *old* constant set: those
 * numbers were never right, but the unit tests assert relationships (a node
 * with compartments is taller than one without), not absolute pixels. Read
 * `measured === false` as "this is the test path" — in a browser it is always
 * true, and `probeFailureReason()` says why if it ever is not.
 */

/** A measurable text role: the key names the probe element it is measured on. */
export type Role =
  | "stereotype"
  | "name"
  | "compartmentTitle"
  | "compartmentEntry"
  | "packageTab"
  | "stateName"
  | "stateAction"
  | "annotationTag"
  | "annotationBody"
  | "edgeLabel"
  // Metamodel view — its box paints none of the roles above (see the
  // `.smlml-metamodel-*` block in theme.css).
  | "metamodelField"
  | "metamodelValue"
  | "metamodelSlice"
  | "metamodelControl"
  | "metamodelTruncationLabel"
  | "metamodelTruncationDetail";

/** A measurable box: an element whose padding/border/margin overhead counts. */
export type Box =
  | "node"
  | "compartment"
  | "packageFrame"
  | "packageTabOuter"
  | "packageTab"
  | "stateNode"
  | "stateName"
  | "stateActions"
  | "annotationOuter"
  | "annotationInner"
  | "edgeLabel"
  | "metamodelRow";

/**
 * The probe subtree, as `id → (class chain from the probe root)`. Each entry is
 * rendered as nested `<div>`s carrying exactly those classes, so every element
 * resolves the same computed style the real node gives it — including styles
 * that only apply in context, like `.smlml-state-actions`'s 10px cascading down
 * to the entries inside it.
 *
 * Keep this in step with the renderers: an element measured under a different
 * class chain than it paints under is the same two-places-one-fact bug in a new
 * costume.
 */
const PROBE_TREE: Record<Role | Box, string[]> = {
  // .smlml-node family (DefaultNode)
  node:             ["smlml-node"],
  stereotype:       ["smlml-node", "smlml-node-metaclass"],
  name:             ["smlml-node", "smlml-node-label"],
  compartment:      ["smlml-node", "smlml-compartment"],
  compartmentTitle: ["smlml-node", "smlml-compartment", "smlml-compartment-title"],
  compartmentEntry: ["smlml-node", "smlml-compartment", "smlml-compartment-entry"],
  // .smlml-package family (PackageNode)
  packageFrame:     ["smlml-package-symbol", "smlml-package"],
  packageTabOuter:  ["smlml-package-symbol", "smlml-package-tab"],
  packageTab:       ["smlml-package-symbol", "smlml-package-tab", "smlml-package-tab-inner"],
  // .smlml-state-node family (StateNode)
  stateNode:        ["smlml-state-node"],
  stateName:        ["smlml-state-node", "smlml-state-name"],
  stateActions:     ["smlml-state-node", "smlml-state-actions"],
  stateAction:      ["smlml-state-node", "smlml-state-actions", "smlml-compartment-entry"],
  // .smlml-annotation family (AnnotationNode)
  annotationOuter:  ["smlml-annotation"],
  annotationInner:  ["smlml-annotation", "smlml-annotation-inner"],
  annotationTag:    ["smlml-annotation", "smlml-annotation-inner", "smlml-annotation-tag"],
  annotationBody:   ["smlml-annotation", "smlml-annotation-inner", "smlml-annotation-body"],
  // .smlml-edge-label (EdgeLabel) — its own role *and* its own box: the pill
  // is one element that both paints the text and carries the padding, so
  // `textWidth(t, "edgeLabel") + padX("edgeLabel")` is its full width. It is
  // rendered through `EdgeLabelRenderer`'s portal rather than inside a node,
  // but the portal is a plain descendant of the flow container and inherits
  // the same font stack, so the probe's own placement measures it correctly.
  edgeLabel:        ["smlml-edge-label"],
  // .smlml-metamodel-node family (MetamodelNode). The row is a *box* — it
  // carries the padding — and the field/value spans inside it are the roles,
  // because the two paint at different sizes on one line.
  metamodelRow:     ["smlml-node", "smlml-metamodel-node", "smlml-metamodel-row"],
  metamodelField:   ["smlml-node", "smlml-metamodel-node", "smlml-metamodel-row", "smlml-metamodel-field"],
  metamodelValue:   ["smlml-node", "smlml-metamodel-node", "smlml-metamodel-row", "smlml-metamodel-value"],
  metamodelSlice:   ["smlml-node", "smlml-metamodel-node", "smlml-metamodel-slice"],
  metamodelControl: ["smlml-node", "smlml-metamodel-node", "smlml-metamodel-control"],
  metamodelTruncationLabel:
    ["smlml-node", "smlml-metamodel-truncation", "smlml-metamodel-truncation-label"],
  metamodelTruncationDetail:
    ["smlml-node", "smlml-metamodel-truncation", "smlml-metamodel-truncation-detail"],
};

/**
 * Roles the renderers wrap: their element holds one `.smlml-line` child per
 * computed line. Every other role paints its text directly into the element.
 *
 * `blockHeight` has to reproduce whichever it is. A block child establishes its
 * own line box; raw text sits in an anonymous inline box in the parent, and the
 * two do not resolve `line-height: normal` to the same height — measuring a
 * raw-text role with a line child inside came back ~2px short on every node,
 * which is enough on its own to push the last compartment line past the bottom
 * padding.
 */
const WRAPS: ReadonlySet<Role> = new Set<Role>([
  "compartmentEntry",
  "stateAction",
  "annotationBody",
]);

/**
 * Estimates for the jsdom test path only — see the module header. `charW` is
 * the average advance at that role's font size; `lineH` the rendered line box;
 * `padX`/`padY` the element's own horizontal/vertical padding + border.
 */
const ESTIMATE: Record<Role | Box, { charW: number; lineH: number; padX: number; padY: number }> = {
  node:             { charW: 0,   lineH: 0,  padX: 23, padY: 12 },
  stereotype:       { charW: 5.5, lineH: 14, padX: 0,  padY: 2 },
  name:             { charW: 6.6, lineH: 18, padX: 0,  padY: 0 },
  compartment:      { charW: 0,   lineH: 0,  padX: 0,  padY: 9 },
  compartmentTitle: { charW: 5.5, lineH: 12, padX: 0,  padY: 1 },
  compartmentEntry: { charW: 6.1, lineH: 15, padX: 0,  padY: 2 },
  packageFrame:     { charW: 0,   lineH: 0,  padX: 3,  padY: 3 },
  packageTabOuter:  { charW: 0,   lineH: 0,  padX: 3,  padY: 3 },
  packageTab:       { charW: 7.1, lineH: 16, padX: 24, padY: 5 },
  stateNode:        { charW: 0,   lineH: 0,  padX: 3,  padY: 3 },
  stateName:        { charW: 7.1, lineH: 16, padX: 20, padY: 10 },
  stateActions:     { charW: 0,   lineH: 0,  padX: 16, padY: 9 },
  stateAction:      { charW: 5.5, lineH: 13, padX: 0,  padY: 2 },
  annotationOuter:  { charW: 0,   lineH: 0,  padX: 2,  padY: 2 },
  annotationInner:  { charW: 0,   lineH: 0,  padX: 16, padY: 10 },
  annotationTag:    { charW: 5.5, lineH: 14, padX: 0,  padY: 2 },
  annotationBody:   { charW: 6.1, lineH: 15, padX: 0,  padY: 0 },
  edgeLabel:        { charW: 5.5, lineH: 13, padX: 8,  padY: 0 },
  metamodelRow:     { charW: 0,   lineH: 0,  padX: 0,  padY: 2 },
  metamodelField:   { charW: 5.0, lineH: 12, padX: 0,  padY: 0 },
  metamodelValue:   { charW: 6.1, lineH: 15, padX: 0,  padY: 0 },
  metamodelSlice:   { charW: 5.4, lineH: 12, padX: 0,  padY: 0 },
  metamodelControl: { charW: 5.5, lineH: 13, padX: 0,  padY: 0 },
  metamodelTruncationLabel:  { charW: 6.6, lineH: 16, padX: 0, padY: 0 },
  metamodelTruncationDetail: { charW: 5.5, lineH: 13, padX: 0, padY: 0 },
};

/** Limits declared as CSS custom properties on `.smlml-node` (see theme.css). */
const LIMIT_ESTIMATE: Record<string, number> = {
  "--smlml-max-w": 280,
};

interface Probe {
  root: HTMLElement;
  el: Record<Role | Box, HTMLElement>;
  ctx: CanvasRenderingContext2D;
}

let probe: Probe | null = null;
let probeTried = false;
let probeReason = "";

/** Why measurement is unavailable, or `""` when it is available. */
export function probeFailureReason(): string {
  ensureProbe();
  return probeReason;
}

function ensureProbe(): Probe | null {
  if (probeTried) return probe;
  probeTried = true;
  try {
    if (typeof document === "undefined") {
      probeReason = "no document (non-DOM environment)";
      return null;
    }
    const ctx = document.createElement("canvas").getContext("2d");
    if (!ctx) {
      probeReason = "no canvas 2d context (jsdom)";
      return null;
    }
    const root = document.createElement("div");
    root.setAttribute("aria-hidden", "true");
    root.dataset.smlmlProbe = "";
    // Out of flow, out of sight, and unconstrained in width so a probe element
    // reports its *intrinsic* single-line height rather than one wrapped by
    // whatever width it happened to inherit.
    root.style.cssText =
      "position:absolute;left:-99999px;top:0;width:max-content;visibility:hidden;pointer-events:none;contain:layout";
    document.body.appendChild(root);

    const el = {} as Record<Role | Box, HTMLElement>;
    // One chain per key. Chains share prefixes in the CSS sense but each gets
    // its own DOM path, which keeps every element a leaf we can size on its own
    // without a sibling's content changing its box.
    for (const key of Object.keys(PROBE_TREE) as (Role | Box)[]) {
      let parent: HTMLElement = root;
      let node: HTMLElement = root;
      for (const cls of PROBE_TREE[key]) {
        node = document.createElement("div");
        node.className = cls;
        parent.appendChild(node);
        parent = node;
      }
      el[key] = node;
    }

    // A DOM with no layout engine (jsdom) reports 0 for everything; so would a
    // stylesheet that never loaded. Either way the numbers would be nonsense,
    // so check one known-nonzero fact before trusting any of them.
    el.name.textContent = "Mg";
    if (el.name.offsetHeight <= 0) {
      probeReason = "probe reports zero height (no layout engine or theme.css not loaded)";
      root.remove();
      return null;
    }
    el.name.textContent = "";

    probe = { root, el, ctx };
    return probe;
  } catch (err) {
    probeReason = `probe construction failed: ${String(err)}`;
    return null;
  }
}

function lineEl(text: string): HTMLElement {
  const d = document.createElement("div");
  d.style.whiteSpace = "pre";
  d.textContent = text;
  return d;
}

/** True when widths and heights are really measured (always so in a browser). */
export function measured(): boolean {
  return ensureProbe() !== null;
}

/**
 * Drop the probe and every cached measurement. Only useful when the font stack
 * itself can change under a live document (a VS Code theme switch), and in
 * tests.
 */
export function resetMetrics(): void {
  probe?.root.remove();
  probe = null;
  probeTried = false;
  probeReason = "";
  widthCache.clear();
  heightCache.clear();
  fontCache.clear();
  widthScaleCache.clear();
  limitCache.clear();
  padCache.clear();
}

const widthCache = new Map<string, number>();
const heightCache = new Map<string, number>();
const fontCache = new Map<Role, string>();
const limitCache = new Map<string, number>();
const padCache = new Map<string, number>();
const widthScaleCache = new Map<Role, number>();

/**
 * Estimates are a last-resort path (no canvas or usable DOM). Leave a modest
 * margin rather than pretending an average character advance is exact.
 */
const FALLBACK_BUFFER = 1.12;
/** Real measurements still get a small allowance for fractional-pixel paint. */
const MEASURED_WIDTH_BUFFER_PX = 2;
const MEASURED_HEIGHT_BUFFER_PX = 1;

function fontFor(p: Probe, role: Role): string {
  const hit = fontCache.get(role);
  if (hit !== undefined) return hit;
  const cs = getComputedStyle(p.el[role]);
  // The `font` shorthand is the whole point — it carries style, weight, size,
  // line-height and family in the exact form the canvas parses. Chrome fills it
  // in; rebuild it by hand if some engine leaves it empty.
  const font =
    cs.font ||
    `${cs.fontStyle} ${cs.fontWeight} ${cs.fontSize}/${cs.lineHeight} ${cs.fontFamily}`;
  fontCache.set(role, font);
  return font;
}

/**
 * Calibrate canvas advances against text painted by the browser's DOM engine.
 *
 * Managed-browser minimum-font settings and Windows font substitution can be
 * applied differently to off-screen canvas text and ordinary DOM text. One
 * real DOM sample per role captures that ratio without forcing layout for
 * every label. Never scale down: spare room is safer than clipping.
 */
function widthScale(p: Probe, role: Role): number {
  const hit = widthScaleCache.get(role);
  if (hit !== undefined) return hit;
  const sample = "MWil. 0123456789 attribute PowerValue";
  const el = p.el[role];
  el.textContent = sample;
  const range = document.createRange();
  range.selectNodeContents(el);
  const domWidth = range.getBoundingClientRect().width;
  range.detach();
  el.textContent = "";
  p.ctx.font = fontFor(p, role);
  const canvasWidth = p.ctx.measureText(sample).width;
  const scale = canvasWidth > 0 && domWidth > 0
    ? Math.max(1, domWidth / canvasWidth)
    : 1;
  widthScaleCache.set(role, scale);
  return scale;
}

/** Width in px of `text` painted in `role`'s resolved font. */
export function textWidth(text: string, role: Role): number {
  const key = `${role}�${text}`;
  const hit = widthCache.get(key);
  if (hit !== undefined) return hit;
  const p = ensureProbe();
  const w = p
    ? (p.ctx.font = fontFor(p, role),
      p.ctx.measureText(text).width * widthScale(p, role) + MEASURED_WIDTH_BUFFER_PX)
    : text.length * ESTIMATE[role].charW * FALLBACK_BUFFER + MEASURED_WIDTH_BUFFER_PX;
  widthCache.set(key, w);
  return w;
}

/**
 * Vertical space `role`'s element takes in normal flow while holding `lines`
 * line children — its own padding, border, line-height **and margins** all
 * included, because the browser is the one adding them.
 *
 * The margins are not an afterthought. `getBoundingClientRect()` reports the
 * border box and says nothing about margins, so a first cut of this function
 * silently dropped `.smlml-node-metaclass`'s 2px `margin-bottom` and
 * `.smlml-compartment-title`'s 1px — 3px on every compartmented node, which is
 * exactly enough to push the last compartment line past the bottom padding of a
 * box that otherwise fit. What a caller needs is what the element *costs its
 * parent*, and that is the border box plus its margins.
 */
export function blockHeight(role: Role, lines: number): number {
  if (lines <= 0) return 0;
  const key = `${role}�${lines}`;
  const hit = heightCache.get(key);
  if (hit !== undefined) return hit;
  const p = ensureProbe();
  let h: number;
  if (p) {
    const el = p.el[role];
    el.textContent = "";
    if (WRAPS.has(role)) {
      for (let i = 0; i < lines; i++) el.appendChild(lineEl("Mg"));
    } else {
      // Raw text, exactly as the renderer emits it — see `WRAPS`.
      el.textContent = Array.from({ length: lines }, () => "Mg").join("\n");
    }
    // `offsetHeight` rounds to an integer; the fractional part matters once a
    // node stacks a dozen of these, so take the layout rect instead.
    const cs = getComputedStyle(el);
    h = el.getBoundingClientRect().height +
      (parseFloat(cs.marginTop) || 0) + (parseFloat(cs.marginBottom) || 0) +
      MEASURED_HEIGHT_BUFFER_PX;
    el.textContent = "";
  } else {
    const e = ESTIMATE[role];
    h = (lines * e.lineH + e.padY) * FALLBACK_BUFFER + MEASURED_HEIGHT_BUFFER_PX;
  }
  heightCache.set(key, h);
  return h;
}

/**
 * Box overhead of `box` on one axis: everything its own content does not cover
 * — padding, border and margins.
 *
 * Padding and border are **measured**, by emptying the probe element and taking
 * the rect it collapses to, rather than summed from `getComputedStyle`.
 * Serialized border widths are not the widths the browser lays out with: Chrome
 * reports `border: 1.5px solid` back as `1px`, so reading the strings lost 1px
 * per border and 2px per box — enough on its own to leave every `.smlml-node`
 * a pixel short of its own content, which is where the last of the corpus's
 * clipped text was coming from. Margins have no such rounding and are read as
 * declared.
 *
 * The element is neutralised for the measurement (`min-*`, `max-*` and flex
 * sizing cleared) so that a floor or cap cannot answer in place of the padding
 * being read — `.smlml-state-node`'s `min-width: 120px` and
 * `.smlml-package-tab`'s `max-width: calc(100% - …)` both otherwise would.
 */
function pad(box: Role | Box, axis: "x" | "y"): number {
  const key = `${box}�${axis}`;
  const hit = padCache.get(key);
  if (hit !== undefined) return hit;
  const p = ensureProbe();
  let v: number;
  if (p) {
    const el = p.el[box];
    const kids = Array.prototype.slice.call(el.childNodes) as ChildNode[];
    const saved = el.getAttribute("style") ?? "";
    el.textContent = "";
    el.setAttribute(
      "style",
      `${saved};min-width:0;min-height:0;max-width:none;max-height:none;` +
        `width:max-content;height:auto;flex:none;align-self:auto`
    );
    const r = el.getBoundingClientRect();
    const cs = getComputedStyle(el);
    const px = (s: string) => parseFloat(s) || 0;
    v =
      axis === "x"
        ? r.width + px(cs.marginLeft) + px(cs.marginRight)
        : r.height + px(cs.marginTop) + px(cs.marginBottom);
    if (saved) el.setAttribute("style", saved);
    else el.removeAttribute("style");
    for (const k of kids) el.appendChild(k);
  } else {
    v = axis === "x" ? ESTIMATE[box].padX : ESTIMATE[box].padY;
  }
  padCache.set(key, v);
  return v;
}

/** Horizontal box overhead (padding + border) of `box`. */
export const padX = (box: Role | Box): number => pad(box, "x");
/** Vertical box overhead (padding + border + margin) of `box`. */
export const padY = (box: Role | Box): number => pad(box, "y");

/**
 * Horizontal indent, in px, per `CompartmentEntry.indent` level (a
 * `##//metadata//##` block's nesting depth — see that field's doc comment in
 * `types.ts`). One constant shared by `layout.ts` (reserving the width) and
 * `DefaultNode.tsx` (painting the `padding-left`), so the two never drift.
 */
export const COMPARTMENT_INDENT_PX = 12;

/** Maximum visible wrapped lines in a documentation scroller. */
export const DOC_MAX_LINES = 20;

/**
 * Border-box height reserved by layout and applied by the renderer before a
 * documentation body starts scrolling. Keeping this in the metric layer means
 * enlarged/substituted fonts still get twenty real lines rather than a stale
 * fixed pixel allowance.
 */
export function docMaxHeight(role: "compartmentEntry" | "annotationBody"): number {
  return blockHeight(role, DOC_MAX_LINES);
}

/** Shared renderer style for a documentation body that scrolls after the cap. */
export function docScrollStyle(role: "compartmentEntry" | "annotationBody") {
  return {
    boxSizing: "border-box" as const,
    maxHeight: docMaxHeight(role),
    overflowY: "auto" as const,
  };
}

/**
 * Resolved px of a sizing-limit custom property (`--smlml-max-w`,
 * `--smlml-tab-trail`).
 *
 * Declared on `body` in `theme.css` and read here off the `.smlml-node` probe,
 * which inherits them. That declaration is the only place the number exists —
 * see the block in `theme.css` for why it is px rather than `em`.
 */
export function limit(prop: string): number {
  const hit = limitCache.get(prop);
  if (hit !== undefined) return hit;
  const p = ensureProbe();
  let v = LIMIT_ESTIMATE[prop] ?? 0;
  if (p) {
    const raw = getComputedStyle(p.el.node).getPropertyValue(prop).trim();
    // `em` values on a custom property are *not* resolved by getComputedStyle
    // (custom properties compute to a token stream, not a length), so hand the
    // value to a real length property and read that back instead.
    if (raw) {
      const probeEl = p.el.node;
      const saved = probeEl.style.maxWidth;
      probeEl.style.maxWidth = raw;
      const resolved = parseFloat(getComputedStyle(probeEl).maxWidth);
      probeEl.style.maxWidth = saved;
      if (Number.isFinite(resolved) && resolved > 0) v = resolved;
    }
  }
  limitCache.set(prop, v);
  return v;
}

/**
 * Greedy line breaks for `text` at `maxWidth`, in `role`'s font.
 *
 * Breaks at spaces; a single word wider than `maxWidth` is broken
 * character-wise rather than allowed to overhang, because the caller is about
 * to reserve exactly `maxWidth` for it. Qualified SysML names
 * (`>>ScalarQuantityValue::mRef`) are one unbroken word and hit that path
 * routinely.
 */
export function wrap(text: string, maxWidth: number, role: Role): string[] {
  if (maxWidth <= 0) return [text];
  const out: string[] = [];
  for (const paragraph of text.split("\n")) {
    if (paragraph === "") { out.push(""); continue; }
    let line = "";
    for (const word of paragraph.split(" ")) {
      const candidate = line === "" ? word : `${line} ${word}`;
      if (textWidth(candidate, role) <= maxWidth) { line = candidate; continue; }
      if (line !== "") { out.push(line); line = ""; }
      if (textWidth(word, role) <= maxWidth) { line = word; continue; }
      // Oversized single word: fill characters up to the limit, repeatedly.
      let chunk = "";
      for (const ch of word) {
        if (chunk !== "" && textWidth(chunk + ch, role) > maxWidth) {
          out.push(chunk);
          chunk = ch;
        } else {
          chunk += ch;
        }
      }
      line = chunk;
    }
    out.push(line);
  }
  return out.length > 0 ? out : [""];
}
