/**
 * Shared types for the extension-host ↔ webview message protocol and for the
 * view-model shapes returned by the `smlml/buildView` LSP request.
 *
 * Both sides import from this file so the contract stays in one place.
 */

// ─────────────────────────────── View kinds ──────────────────────────────────

/// Mirrors `smlml_viewgen::ViewKind`'s wire strings, plus the two client-only
/// modes. `auto` asks the server to choose; `simulation` is a panel mode the
/// server resolves to `state`.
///
/// The server's `auto` resolution returns whatever the OMG selection logic
/// picks, which includes kinds with no React painter yet — so every kind the
/// server can return must be nameable here, or the dispatch silently falls
/// through to a blank panel.
export type ViewKind =
  | "default"
  | "tree"
  | "interconnection"
  | "action"
  | "state"
  | "sequence"
  | "case"
  | "mixed"
  | "metamodel"
  | "heritage"
  | "geometry"
  | "simulation"
  | "auto";

/// Kinds with a dedicated React painter. Anything else the server resolves to
/// is rendered by an explicit "no renderer" notice rather than nothing at all.
export const PAINTED_KINDS = [
  "tree",
  "interconnection",
  "action",
  "state",
  "sequence",
  "case",
  // The server's mixed view is generated by the tree visitor in mixed mode,
  // so it has the same ViewModel/layout contract as the tree painter.
  "mixed",
  "metamodel",
  "heritage",
  "geometry",
] as const;

// ─────────────────────────────── Source range ────────────────────────────────

export interface SourceRange {
  startLine: number;
  startCol: number;
  endLine: number;
  endCol: number;
}

// ═══════════════════════════ View-model schema ═══════════════════════════════
// Mirrors the Rust `smlml-view` types (`crates/smlml-view/src/lib.rs`) — the
// single `ViewModel` every view kind is delivered on.

// ─────────────────────────────── Port direction ──────────────────────────────

export type PortDirection = "in" | "out" | "inout";

// ─────────────────────────────── Node kinds ──────────────────────────────────

export type NodeKind =
  | { type: "element"; metaclass: string }
  | { type: "port"; direction: PortDirection }
  | { type: "action" }
  | { type: "decision" }
  | { type: "merge" }
  | { type: "fork" }
  | { type: "join" }
  | { type: "start" }
  | { type: "done" }
  | { type: "send"; payload?: string; via?: string; to?: string }
  | { type: "accept"; via?: string }
  | { type: "pin_in" }
  | { type: "pin_out" }
  | { type: "state"; is_parallel: boolean }
  /**
   * A participant lifeline in a Sequence view (`smlml_view::NodeKind::Lifeline`).
   * The sequence view's only node kind, as `message` is its only edge kind.
   */
  | { type: "lifeline" }
  | { type: "entry_point" }
  | { type: "exit_point" }
  /**
   * A standalone annotation rendered as the dog-eared note symbol, attached to
   * its annotated element by a dashed `annotation` edge. Used when a comment /
   * documentation / metadata is shown as its own node rather than folded into a
   * host node's compartment (per-view policy — OMG `VComment`/`VMetadata`).
   */
  | { type: "annotation"; annotation: "doc" | "metadata" | "comment" }
  /**
   * Not an element: the affordance reporting what a node budget left out.
   * Carries no `element_id` and no `range`, and its `label` is empty — the
   * painter composes the text it shows from {@link Truncation}'s numbers.
   */
  | { type: "truncation"; truncation: Truncation };

// ─────────────────────────────── Truncation ──────────────────────────────────

/**
 * What a truncation placeholder offers, mirroring the Rust
 * `smlml_view::Truncation`.
 *
 * Two species, told apart by the `affordance` tag rather than by their text.
 */
export type Truncation =
  | {
      affordance: "branch";
      /** The node whose descendants were clipped — the expansion target. */
      parent: string;
      /** How many nodes are hidden beneath `parent`, at any depth. */
      hidden: number;
    }
  | {
      affordance: "all";
      /** Nodes the same request would draw with no budget applied. */
      total: number;
      /** The budget that clipped it. */
      budget: number;
      /** Expected cost of laying `total` nodes out, in ms of blocking layout. */
      estimated_layout_ms: number;
    };

// ─────────────────────────────── Compartment entry ───────────────────────────

export interface CompartmentEntry {
  /** Category: "attribute", "calc", "doc", "entry", "do", "exit", … */
  kind: string;
  /**
   * Structural content only — no presentation markup. A `##//metadata//##`
   * block's `""…""` creole monospace pad is NOT in here; {@link indent}
   * carries the nesting depth instead, so this component supplies its own
   * indent idiom.
   */
  label: string;
  /**
   * Nesting depth for a structural entry (currently only a `##//metadata//##`
   * block's member rows recurse). Omitted — read as 0 — for every other kind.
   */
  indent?: number;
  range?: SourceRange;
}

// ─────────────────────────────── Edge kinds ──────────────────────────────────

export type RequirementEdgeKind = "subject" | "assume" | "require" | "objective";

/**
 * How a contained element relates to its owner, selecting the containment
 * edge's owner-end glyph: composite ◆ (`*--`), reference ◇ (`o--`), or
 * namespace ownership ⊕ (`+--`).
 */
export type MembershipKind = "composite" | "reference" | "ownership";

export type EdgeKind =
  | { type: "containment"; membership: MembershipKind }
  | { type: "specialization" }
  | { type: "typing" }
  | { type: "redefinition" }
  | { type: "subsetting" }
  | { type: "connector" }
  | { type: "binding" }
  | { type: "interface" }
  | { type: "flow"; item?: string }
  | { type: "succession" }
  /**
   * `perform someAction` — a solid `-->` labelled «perform» from the performing
   * element to the referenced action (pilot `casePerformActionUsage`).
   */
  | { type: "perform" }
  | { type: "transition" }
  /** An ordered message between Sequence-view participants. */
  | { type: "message" }
  | { type: "dependency" }
  | { type: "allocation" }
  /**
   * A `VariantMembership` re-owning edge (pilot `caseVariantMembership`, `+---`).
   * Distinct from `containment` because the variant usage's rendered parent is
   * NOT this edge's source — see `smlml_view::EdgeKind::Variant`.
   */
  | { type: "variant" }
  /** Comment/doc → annotated element (OMG dashed `note ..` link). */
  | { type: "annotation" }
  /** Metadata note → annotated element (OMG dashed `note ..@` link). */
  | { type: "metadata" }
  | { type: "requirement_edge"; kind: RequirementEdgeKind };

/**
 * Every `EdgeKind["type"]` tag, restated as a value so it can be compared at
 * runtime against `crates/smlml-view/edge-kind-variants.json` — the wire
 * side's own manifest (see `smlml_view::edge_kind_variant_manifest_tests`).
 *
 * The two assertions below are the compile-time half of the tie: if a
 * variant is added, removed, or renamed on the `EdgeKind` union above without
 * updating this list, one of them stops type-checking as `true` and `tsc`
 * fails (`npm run compile:tests`, which `test:unit` runs first). The runtime
 * half — this list vs. the committed JSON manifest — lives in
 * `../../test/edge-kind-variants.test.ts`.
 */
export const EDGE_KIND_TAGS = [
  "allocation", "annotation", "binding", "connector", "containment",
  "dependency", "flow", "interface", "message", "metadata", "perform",
  "redefinition", "requirement_edge", "specialization", "subsetting",
  "succession", "transition", "typing", "variant",
] as const;

type _EdgeKindTag = EdgeKind["type"];
type _KnownTag = (typeof EDGE_KIND_TAGS)[number];

/** Fails to type-check as `true` if `EdgeKind` gained a tag missing here. */
type _AssertEveryEdgeKindTagListed =
  _EdgeKindTag extends _KnownTag ? true : ["EdgeKind tag missing from EDGE_KIND_TAGS:", Exclude<_EdgeKindTag, _KnownTag>];
/** Fails to type-check as `true` if this list has a tag `EdgeKind` dropped. */
type _AssertNoStaleEdgeKindTag =
  _KnownTag extends _EdgeKindTag ? true : ["EDGE_KIND_TAGS has a tag EdgeKind no longer has:", Exclude<_KnownTag, _EdgeKindTag>];
// eslint-disable-next-line @typescript-eslint/no-unused-vars
const _assertEveryEdgeKindTagListed: _AssertEveryEdgeKindTagListed = true;
// eslint-disable-next-line @typescript-eslint/no-unused-vars
const _assertNoStaleEdgeKindTag: _AssertNoStaleEdgeKindTag = true;

// ─────────────────────────────── Resolved appearance ─────────────────────────
// Mirrors smlml_view::style. Carried on the wire so every surface paints these
// directly instead of re-deriving from EdgeKind/NodeKind.

export type Line = "solid" | "dashed" | "dotted";

export type Arrow =
  | "none"
  | "triangle-hollow"
  | "triangle-hollow-colon"
  | "triangle-hollow-bar"
  | "arrow-filled"
  | "chevron-open"
  | "diamond-filled"
  | "diamond-hollow"
  | "circle-plus";

export interface EdgeStyle {
  line: Line;
  /** Glyph at the target end. */
  head: Arrow;
  /** Glyph at the source (owner) end. */
  tail: Arrow;
  /** Relative stroke weight; 1 is normal. */
  thickness: number;
  /** Explicit "#rrggbb" colour; absent ⇒ theme default. */
  color?: string;
}

// ─────────────────────────────── Guard evaluation ────────────────────────────

export type GuardValue = "true" | "false" | "undetermined";

/** One guarded transition's evaluation (mirrors the Rust `GuardEval`). */
export interface GuardEval {
  /** View edge id this guard belongs to. */
  edgeId: string;
  /** Guard expression text. */
  expression: string;
  value: GuardValue;
  /** Present only when `value === "undetermined"`. */
  reason?: string;
  source: "auto" | "override";
}

export type NodeShape =
  | "box"
  | "diamond"
  | "bar"
  | "circle"
  | "circle-final"
  | "port"
  | "note";

// ─────────────────────────────── ViewNode v2 ─────────────────────────────────

/** Colour family for type-based rendering (mirrors smlml_view::NodeFamily). */
export type NodeFamily =
  | "part"
  | "attribute"
  | "port"
  | "item"
  | "action"
  | "state"
  | "connection"
  | "requirement"
  | "package"
  | "default";

/** Box form for shape-based rendering (mirrors smlml_view::NodeForm). */
export type NodeForm =
  | "usage"
  | "definition"
  | "package"
  | "note"
  | "participant";

export interface ViewNode {
  /** Stable qualified-name identifier. */
  id: string;
  label: string;
  kind: NodeKind;
  /**
   * Colour family, classified server-side by `smlml_view`. Absent ⇒ `"default"`.
   * Authoritative — the client renders this rather than re-deriving the family.
   */
  family?: NodeFamily;
  /**
   * Box form for shape-based rendering, classified server-side by `smlml_view`.
   * Absent ⇒ `"usage"`. Authoritative — the client renders this rather than
   * re-deriving the form from the metaclass and stereotype.
   */
  form?: NodeForm;
  /**
   * Whether a port-shaped node paints filled (in-flowing) or hollow
   * (out-flowing), classified server-side by `smlml_view` from `kind`.
   * Absent ⇒ `true`. Authoritative — the client renders this rather than
   * re-deriving fill from `kind.direction`/`kind.type` itself.
   */
  filled?: boolean;
  parent_id?: string;
  range?: SourceRange;
  compartments?: CompartmentEntry[];
  /** Heritage-view provenance and standard-library source navigation. */
  heritage?: {
    origin: "local" | "library";
    source_path?: string;
  };
  stereotype?: string;
  is_variation?: boolean;
  is_variant?: boolean;
  is_individual?: boolean;
  multiplicity?: string;
  /** CLI layout position (absent when webview uses ELK). */
  layout?: { x: number; y: number };
  layout_rect?: { x: number; y: number; w: number; h: number };
  /** Simulation overlay: true when this is the current active state. */
  is_active?: boolean;
  /** Resolved outline shape; absent ⇒ derive from kind (transitional). */
  shape?: NodeShape;
  /** True when `label` is a synthesized "noname" placeholder — render struck-through. */
  name_synthesized?: boolean;
  /** True when the element renders as an abstract Type — render the name in italics. */
  is_abstract?: boolean;
  /** True when the box shows an inherited member — render a `^` prefix (or badge). */
  is_inherited?: boolean;
  /** Declared short name / alias — render as a `~<short>` prefix before the name. */
  short_name?: string;
  /**
   * True when `label` is a synthesized MARKER rather than a declared name —
   * render it as `«label»`. The pilot titles an anonymous objective
   * `«objective»` (`VCase.caseObjectiveMembership`, VCase.java:88) and the
   * wire carries the bare word. Exclusive of the rest of the name
   * composition: a `~<short>` alias, italics and strikethrough never combine
   * with it, though an inherited `^` still leads. Mirrors `display_name_parts`
   * in `crates/smlml-cli/src/cmd/render.rs`, which is how the DOT painter
   * reads the same field.
   */
  marker_title?: boolean;
  /**
   * The element's UUID. `metamodel`-view only; every other kind omits it and
   * carries the qualified name in {@link id}. In the metamodel view `id` is
   * the UUID too — most elements there are anonymous — so a consumer never
   * has to branch on view kind to find the element identity.
   */
  element_id?: string;
  /**
   * Whether a distinct grammar rule node produced this element.
   * `metamodel`-view only, and omitted from the wire when `true`.
   */
  has_source?: boolean;
  /** Whether this node has children not yet materialized. `metamodel`-view only. */
  expandable?: boolean;
  /** Whether this node's children have been materialized. `metamodel`-view only. */
  expanded?: boolean;
}

// ─────────────────────────────── ViewEdge v2 ─────────────────────────────────

export interface ViewEdge {
  /** Stable edge identifier: "<src_qn>→<tgt_qn>#<n>" or relationship QN. */
  id: string;
  source: string;
  target: string;
  kind: EdgeKind;
  label?: string;
  trigger?: string;
  guard?: string;
  effect?: string;
  multiplicity?: string;
  range?: SourceRange;
  /** Simulation overlay: true when this was the last-fired transition. */
  is_fired?: boolean;
  /** Simulation overlay: evaluated guard truth, for the edge badge. */
  guard_value?: GuardValue;
  /** Resolved visual style; absent ⇒ derive from kind (transitional). */
  style?: EdgeStyle;
  /** Stereotype text without guillemets (e.g. `"#Security"`) — display as `<<…>>`. */
  stereotype?: string;
  /**
   * The metamodel field on the source element that stores this reference
   * (`"type"`, `"general"`, `"ownedRelationship"`, …). `metamodel`-view only.
   */
  field?: string;
}

// ─────────────────────────────── ViewModel v2 ────────────────────────────────

export interface ViewModel {
  nodes: ViewNode[];
  edges: ViewEdge[];
  /** Painter-neutral scene carried only by the Geometry view. */
  geometry?: GeometryScene;
  /** Root node ids (QN strings) for tree views. */
  root_ids?: string[];
  /** Initial pseudo-node id for state/action views. */
  initial_id?: string;
  /** True when the extraction hit the visit budget — show a warning banner. */
  truncated?: boolean;
}

export interface GeometryScene {
  nodes: GeometryNode[];
}

export interface GeometryNode {
  id: string;
  label: string;
  parent_id?: string;
  primitive?: GeometryPrimitive;
  transform: GeometryTransform;
  range?: SourceRange;
  completeness: GeometryCompleteness;
  diagnostics?: GeometryDiagnostic[];
}

export type GeometryCompleteness = "complete" | "partial" | "invalid" | "unsupported";

export interface GeometryDiagnostic {
  code: string;
  message: string;
  range?: SourceRange;
}

export type GeometryPrimitive =
  | { type: "box"; length: number; width: number; height: number }
  | { type: "cylinder"; radius: number; height: number }
  | { type: "cone"; radius: number; height: number };

export interface GeometryTransform {
  translation: [number, number, number];
  rotations?: GeometryRotation[];
  matrix?: number[];
}

export interface GeometryRotation {
  axis: [number, number, number];
  angle_degrees: number;
  intrinsic?: boolean;
}

// ───────────────────────── Extension → Webview messages ──────────────────────

export type ExtToWebviewMsg =
  | {
      type: "loadView";
      /** The requested kind (may be "auto"). */
      kind: ViewKind;
      /** The resolved kind (never "auto" — always the concrete kind actually rendered). */
      resolvedKind: ViewKind;
      uri: string;
      viewJson: string;
      /**
       * Whether this file declares a state machine. `false` greys out the
       * Simulation view kind; omitted means the host did not report, and the
       * option stays available.
       */
      hasStates?: boolean;
      /**
       * Why the host has no view to show. Set when `smlml/buildView` reported a
       * failure; `viewJson` is then empty and must not be rendered as a graph,
       * which is indistinguishable from a file with no elements.
       */
      error?: string;
      /**
       * What the host's expansion set holds, for the metamodel painter's
       * collapse control. Absent from every other kind's `loadView`, and from
       * a host that does not track one.
       */
      expansion?: ExpansionSnapshot;
      /**
       * The host's current sync state — `smlml.viewSync.enabled` at panel
       * creation, then whatever the popover last reported via
       * `syncSettingChanged`. Seeds the webview's Settings-popover toggle so
       * a host-side default of `false` doesn't get overridden by the
       * webview's own hardcoded default; a host with no such setting (the
       * web editor) omits it and the webview's default of `true` stands.
       */
      syncEnabled?: boolean;
    }
  | {
      type: "stepResult";
      /** Active state node id after the step (overlay applied client-side). */
      currentState: string;
      traceText: string;
      /** View edge id of the transition that just fired, for animation. */
      firedEdgeId?: string | null;
      /** Per-guard evaluation table for this step (badges + Guards panel). */
      guards?: GuardEval[];
    }
  | { type: "stepError"; message: string }
  /**
   * The documentation for a concept the legend asked about, or `null` when the
   * host has none — which is also what a host that does not implement
   * `conceptDocs` never sends, leaving the row with no tooltip rather than a
   * spinner that never resolves.
   */
  | { type: "conceptDocsResult"; concept: string; markdown: string | null }
  | {
      type: "highlightNode";
      nodeId: string;
      /**
       * Index into that node's `compartments` when the cursor landed on a
       * specific row (an attribute, a value) rather than on the declaration
       * name. Absent means the whole node.
       */
      compartment?: number;
    };

// ───────────────────────── Webview → Extension messages ──────────────────────

export type WebviewToExtMsg =
  | { type: "ready" }
  | { type: "navigate"; uri: string; range: SourceRange }
  | { type: "simulateStep"; trigger: string | null; guardOverrides?: Record<string, boolean> }
  | { type: "viewKindChanged"; kind: ViewKind }
  /**
   * Ask the host for the language documentation behind a legend row.
   *
   * `concept` is one of {@link LEGEND_CONCEPTS}' keys — a name for a piece of
   * SysML syntax, not an element in the user's model, so the answer is about
   * the language and is the same in every file. The host resolves it through
   * the same hover lookup the editor uses for a hovered keyword; a host with
   * no way to do that simply never answers, and the row shows no tooltip.
   */
  | { type: "conceptDocs"; concept: string }
  /**
   * The session's Settings-popover sync toggle changed. The host is the only
   * side that can act on the cursor→node direction (it owns the text-editor
   * selection listener), so the webview reports the toggle rather than the
   * host polling for it; the node→text direction is gated in the webview
   * itself and never dispatches `navigate` while off.
   */
  | { type: "syncSettingChanged"; enabled: boolean }
  /**
   * Amend the accumulated expansion set. `metamodel`-view only;
   * `viewKindChanged`'s sibling — the host applies the amendment and re-issues
   * `smlml/buildView` with the resulting `expand`/`budget` params.
   *
   * An *amendment*, not a replacement: the spec's `+N` control "re-requests
   * with that node added to `expand.nodes`", and the algorithm table's
   * `nodes: [a, b]` is two subtrees open at once. A message that carried the
   * whole set would make expanding B collapse A.
   */
  | ({ type: "expandNodes" } & ExpandAmendment);

/**
 * A change to the expansion set, as the painter states it.
 *
 * `add`/`remove` name element UUIDs. `all` is the whole graph, which is not
 * expressible as an addition — the wire says "everything" with an *empty*
 * `nodes` list, so it needs its own flag rather than a sentinel in the set.
 */
export interface ExpandAmendment {
  /** UUIDs to open. */
  add?: string[];
  /** UUIDs to close. */
  remove?: string[];
  /** Replace the set with the whole graph. */
  all?: boolean;
  /** Absent leaves the current depth; the wire's absent depth is unbounded. */
  depth?: number;
  /** Node-budget override, already bounded by {@link MAX_CLIENT_BUDGET}. */
  budget?: number;
}

/**
 * The expansion set as the host holds it, sent to the painter with each view.
 *
 * `all` is whole-graph mode, which the wire spells as an empty `nodes` list and
 * so cannot be a member of the set. A node is *explicitly* open iff `all` or
 * `nodes` names it — which is a different question from `ViewNode.expanded`,
 * the server's statement that this node was drawn in its expanded form.
 */
export interface ExpansionSnapshot {
  all: boolean;
  nodes: string[];
}

// ───────────────────────────── Expansion budget ──────────────────────────────

/**
 * Measured cost of laying one node out, in milliseconds — the `mrtree` row of
 * the design's scale table (2685 ms at 4000 nodes).
 */
const LAYOUT_MS_PER_NODE = 0.8;

/**
 * The longest blocking layout the UI will ask the server to make possible.
 *
 * ELK runs synchronously on the main thread, so a node budget is a freeze
 * budget: nothing in the editor responds while it runs. Neither the LSP nor
 * the CLI surface bounds `budget`, so the bound has to be here, at the only
 * place that can know a freeze is what it is buying.
 */
const MAX_LAYOUT_FREEZE_MS = 10_000;

/** The largest `budget` any client message may carry. */
export const MAX_CLIENT_BUDGET = Math.floor(MAX_LAYOUT_FREEZE_MS / LAYOUT_MS_PER_NODE);

/**
 * The budget a control asking for `total` nodes may actually request.
 *
 * The server accepts any `budget` and ELK will faithfully freeze the editor for
 * as long as one implies, so the bound lives client-side — the only place that
 * knows the number is being spent on a main-thread stall. A control that clamps
 * must also *say* it clamped: see `truncationLabel`.
 */
export function boundedBudget(total: number): number {
  return Math.min(total, MAX_CLIENT_BUDGET);
}

/**
 * Above this many nodes, a layout is long enough to read as a hang, so the
 * painter shows progress before it starts and confirms before it requests one.
 */
export const SLOW_LAYOUT_NODES = 1000;
