/**
 * Default node — used for tree, interconnection, and action views.
 *
 * Supports both v1 (metaclass string) and v2 (stereotype + compartments) data.
 * Renders:
 *   «stereotype» above the name (v2) or «metaclass» (v1)
 *   name line
 *   compartment entries below (v2)
 *   variation border decoration (v2)
 */

import React from "react";
import { Handle, Position, type NodeProps } from "@xyflow/react";
import type { CompartmentEntry } from "../types";
import { useNavigate } from "../NavigateContext";
import { formOf } from "./form";
import { COMPARTMENT_INDENT_PX, docScrollStyle } from "../text-metrics";
import compartmentSections from "../../../../../../crates/smlml-view/compartment-sections.json";

/**
 * Display title for each compartment category (OMG `##//title//##`).
 *
 * The single override table both the DOT painter and this component consult
 * (`smlml_view::compartment_section_title`); most kinds already arrive as
 * their own final plural title and pass through `titleFor` unchanged.
 */
const COMPARTMENT_TITLES = compartmentSections as unknown as Record<string, string>;
const titleFor = (kind: string) => COMPARTMENT_TITLES[kind] ?? kind;

/**
 * Group consecutive entries of the same kind into one titled compartment.
 *
 * Groups carry each entry's index in the original flat array, not just the
 * entry, so the parallel `entryLines` array `layout.ts` measured against can be
 * indexed without a second traversal that could fall out of step with this one.
 */
function groupCompartments(
  entries: CompartmentEntry[]
): { kind: string; entries: { c: CompartmentEntry; i: number }[] }[] {
  const groups: { kind: string; entries: { c: CompartmentEntry; i: number }[] }[] = [];
  entries.forEach((c, i) => {
    const last = groups[groups.length - 1];
    if (last && last.kind === c.kind) last.entries.push({ c, i });
    else groups.push({ kind: c.kind, entries: [{ c, i }] });
  });
  return groups;
}

/**
 * Paint one element per line that `layout.ts` computed, with `white-space: pre`
 * so the browser adds no breaks of its own.
 *
 * The line arrays travel in the node's `data` because `layout.ts` reserved this
 * node's height against exactly those breaks; re-wrapping here — even with the
 * same algorithm — would put a second wrap implementation between the reserved
 * height and the painted height, which is the class of drift this whole change
 * removes. `lines` is absent only on the estimate path (see `text-metrics.ts`),
 * where handing the raw string to the browser is the honest fallback.
 */
function Lines({ lines, text }: { lines: string[] | undefined; text: string }) {
  if (!lines || lines.length === 0) return <>{text}</>;
  return <>{lines.map((l, i) => <div key={i} className="smlml-line">{l}</div>)}</>;
}

export function DefaultNode({ data, selected }: NodeProps) {
  const navigate = useNavigate();
  const label = data.label as string | undefined;
  // v1 compat
  const metaclass = data.metaclass as string | undefined;
  // v2 fields
  const stereotype = (data.stereotype as string | undefined) ?? metaclass;
  const compartments = (data.compartments as CompartmentEntry[] | undefined) ?? [];
  // Set by the flow view when the editor cursor is sitting on this row,
  // so a source selection reaches the attribute rather than only the box.
  const highlightCompartment = data.highlightCompartment as number | undefined;
  // Rows matching the diagram search, set by the flow view.
  const matchCompartments = data.matchCompartments as Set<number> | undefined;
  // Wrapped lines per entry, aligned index-for-index with `compartments`.
  // `groupCompartments` below preserves that order, so a running index over the
  // groups indexes back into this flat array.
  const entryLines = (data.entryLines as string[][] | undefined) ?? [];
  const isVariation = data.isVariation as boolean | undefined;
  const isVariant = data.isVariant as boolean | undefined;
  const isActive = data.isActive as boolean | undefined;
  // ARCH-4 semantic display fields: the wire label is creole-free; render
  // intent here (strikethrough noname, italic abstract, ^ inherited, ~<short>).
  const nameSynthesized = data.nameSynthesized as boolean | undefined;
  const isAbstract = data.isAbstract as boolean | undefined;
  const isInherited = data.isInherited as boolean | undefined;
  const shortName = data.shortName as string | undefined;
  // `label` is a synthesized marker, not a declared name: paint it as
  // `«label»` and drop the rest of the composition. `structgraph::display_key`
  // and `render.rs`'s `display_name_parts` both branch the same way, which is
  // why the DOT painter draws the pilot's `«objective»` and this one did not.
  const markerTitle = data.markerTitle as boolean | undefined;
  const heritage = data.heritage as
    | { origin: "local" | "library"; source_path?: string }
    | undefined;

  // SysML shape rule: definitions are sharp rectangles, usages are rounded.
  // `form` is classified once, server-side, by `smlml_view` and shared with
  // the CLI painters; `formOf` is the sole reader of it (the wire's `usage`
  // default when the field is omitted).
  const form = formOf(data);
  // Every node gets a shape class, including a package or other pure
  // namespace that carries no stereotype.
  const shapeClass =
    form === "definition"
      ? " smlml-def"
      : form === "package"
      ? " smlml-package"
      : form === "note"
      ? " smlml-annotation"
      : " smlml-usage";
  // Server-classified family, authoritative and shared with the CLI painters;
  // "default" is the wire's own fallback for a node with no family tint.
  const family = (data.family as string | undefined) ?? "default";
  const familyClass = ` fam-${family}`;

  const borderStyle = isVariation
    ? "2px dashed var(--vscode-editorWarning-foreground, #cca700)"
    : isVariant
    ? "1px dashed var(--vscode-editorInfo-foreground, #75beff)"
    : undefined;

  return (
    <div
      className={`smlml-node${shapeClass}${familyClass}${heritage ? ` smlml-heritage-${heritage.origin}` : ""}${selected ? " selected" : ""}${isActive ? " active" : ""}`}
      // The form this box was drawn as, readable without consulting the
      // stylesheet — see `formOf` in ./form.
      data-form={form}
      style={borderStyle ? { border: borderStyle } : undefined}
    >
      <Handle type="target" position={Position.Top} />
      {heritage && (
        <span
          className="smlml-heritage-badge"
          aria-label={`${heritage.origin} declaration`}
          title={heritage.source_path ?? "Current model"}
        >
          {heritage.origin === "library" ? "◇" : "●"}
        </span>
      )}
      {/* Name compartment (header): «stereotype» over the name. */}
      {stereotype && (
        <div className="smlml-node-metaclass">«{stereotype}»</div>
      )}
      {/* The name is an identifier: it grows to `--smlml-max-w` and then
          ellipsizes rather than wrapping over three lines, with the full text
          on hover. */}
      <div
        className="smlml-node-label"
        title={label ?? "?"}
        style={
          markerTitle
            ? undefined
            : {
                ...(nameSynthesized ? { textDecoration: "line-through" } : undefined),
                ...(isAbstract ? { fontStyle: "italic" } : undefined),
              }
        }
      >
        {isInherited ? "^" : ""}
        {markerTitle ? (
          `«${label ?? "?"}»`
        ) : (
          <>
            {shortName ? `~<${shortName}> ` : ""}
            {label ?? "?"}
          </>
        )}
      </div>
      {/* Feature compartments: one titled, separated panel per category. */}
      {groupCompartments(compartments).map((g, gi) => (
        <div key={gi} className="smlml-compartment">
          <div className="smlml-compartment-title">{titleFor(g.kind)}</div>
          {g.entries.map(({ c, i }) => (
            <div
              key={i}
              className={`smlml-compartment-entry smlml-compartment-${c.kind}${c.kind === "doc" ? " nowheel" : ""}${c.range && navigate ? " smlml-compartment-navigable" : ""}${i === highlightCompartment ? " smlml-compartment-highlight" : ""}${matchCompartments?.has(i) ? " smlml-compartment-match" : ""}`}
              onClick={c.range && navigate ? (e) => { e.stopPropagation(); navigate("", c.range!); } : undefined}
              // A structural entry's nesting depth (currently only a
              // `##//metadata//##` block's member rows) has no `""…""` creole
              // pad on the wire — this is this painter's own indent idiom,
              // the same per-level px `layout.ts` reserved width against.
              style={{
                ...(c.indent ? { paddingLeft: c.indent * COMPARTMENT_INDENT_PX } : undefined),
                ...(c.kind === "doc" ? docScrollStyle("compartmentEntry") : undefined),
              }}
            >
              <Lines lines={entryLines[i]} text={c.label} />
            </div>
          ))}
        </div>
      ))}
      <Handle type="source" position={Position.Bottom} />
    </div>
  );
}
