/**
 * Annotation node — the OMG dog-eared "note" symbol for a standalone comment,
 * documentation, or metadata annotation (`VComment` / `VMetadata`). Attached to
 * its annotated element by a dashed `annotation` edge.
 *
 * The note body is drawn as two stacked clipped layers (outer = border colour,
 * inner inset = fill) so the folded-corner (notch) edge keeps a visible stroke
 * — a plain `clip-path` would clip the border away on the diagonal. A small
 * triangle overlay draws the turned-down "dog-ear" with its fold line.
 *
 * Pilot `VComment.addCommentInternal` (VComment.java:65-72) writes only
 * `note as <id> … end note` — no title line — for a plain comment or doc,
 * and `VMetadata.addMetadataFeature` folds the metaclass name into the body
 * text itself rather than a separate compartment. So the title line is
 * painted only when the wire's `stereotype` carries one; most notes have none.
 *
 * Long bodies are capped in width and height and scroll, rather than growing the
 * note unbounded (matching the doc compartment policy in DefaultNode/theme.css).
 */

import React from "react";
import { Handle, Position, type NodeProps } from "@xyflow/react";
import { formOf } from "./form";
import { docScrollStyle } from "../text-metrics";

export function AnnotationNode({ data, selected }: NodeProps) {
  const body = (data.label as string | undefined) ?? "";
  // The line breaks `layout.ts` reserved this note's height against — see the
  // `Lines` note in DefaultNode for why the renderer does not re-wrap.
  const bodyLines = (data.bodyLines as string[] | undefined) ?? [];
  const stereotype = data.stereotype as string | undefined;
  // Server-classified family, authoritative and shared with the CLI painters;
  // "default" is the wire's own fallback for a node with no family tint.
  const family = (data.family as string | undefined) ?? "default";
  const familyClass = ` fam-${family}`;
  return (
    <div
      className={`smlml-annotation${familyClass}${selected ? " selected" : ""}`}
      data-form={formOf(data)}
    >
      <div className="smlml-annotation-inner">
        <Handle type="target" position={Position.Top} style={{ opacity: 0 }} />
        {stereotype && <div className="smlml-annotation-tag">«{stereotype}»</div>}
        <div
          className="smlml-annotation-body nowheel"
          style={docScrollStyle("annotationBody")}
        >
          {bodyLines.length
            ? bodyLines.map((l, i) => <div key={i} className="smlml-line">{l}</div>)
            : body}
        </div>
        <Handle type="source" position={Position.Bottom} style={{ opacity: 0 }} />
      </div>
      {/* Turned-down corner ("dog-ear"): fills the folded triangle and strokes
          the fold line along the diagonal. */}
      <svg className="smlml-annotation-fold" width="11" height="11" viewBox="0 0 11 11" aria-hidden>
        <path className="smlml-annotation-fold-fill" d="M0,0 L11,11 L0,11 Z" />
        <path className="smlml-annotation-fold-line" d="M0,0 L11,11" />
      </svg>
    </div>
  );
}
