/**
 * Multi-file workspace model.
 *
 * Pure state + a typed event stream — no DOM, no LSP coupling — so it is unit
 * testable headlessly.  The composition root subscribes to `onEvent` and turns
 * `opened`/`changed`/`closed` into LSP `didOpen`/`didChange`/`didClose`
 * notifications, and re-renders the file browser / problems / status on any
 * event.  All files share one workspace, so names resolve across files.
 */

import { isCollisionDiagnostic, type Diagnostic, type Lang } from "../types.ts";
import type { ZipEntry } from "./zip.ts";
import { canMove } from "./tree.ts";

export interface WorkspaceFile {
  /** `file:///<path>` */
  uri: string;
  /** Workspace-relative path, e.g. `parts/Wheel.sysml`. */
  path: string;
  lang: Lang;
  text: string;
  /** LSP document version, bumped on each edit. */
  version: number;
}

export type StoreEvent =
  | { type: "opened"; file: WorkspaceFile }
  | { type: "changed"; file: WorkspaceFile }
  | { type: "closed"; uri: string }
  | { type: "active"; uri: string | null }
  | { type: "diagnostics"; uri: string }
  | { type: "folders" };

export type Dispose = () => void;

export function langForPath(path: string): Lang {
  return /\.kerml$/i.test(path) ? "kerml" : "sysml";
}

export function pathToUri(path: string): string {
  return "file:///" + path.replace(/^\/+/, "");
}

export class WorkspaceStore {
  private readonly filesByUri = new Map<string, WorkspaceFile>();
  private readonly order: string[] = [];
  private readonly diags = new Map<string, Diagnostic[]>();
  private readonly folders = new Set<string>();
  private active: string | null = null;
  private readonly listeners = new Set<(e: StoreEvent) => void>();

  // ─────────────────────────── subscription ───────────────────────────

  onEvent(cb: (e: StoreEvent) => void): Dispose {
    this.listeners.add(cb);
    return () => this.listeners.delete(cb);
  }

  private emit(e: StoreEvent): void {
    for (const cb of this.listeners) cb(e);
  }

  // ─────────────────────────── queries ───────────────────────────

  get files(): WorkspaceFile[] {
    return this.order.map((uri) => this.filesByUri.get(uri)!);
  }

  get activeUri(): string | null {
    return this.active;
  }

  get activeFile(): WorkspaceFile | null {
    return this.active ? this.filesByUri.get(this.active) ?? null : null;
  }

  file(uri: string): WorkspaceFile | undefined {
    return this.filesByUri.get(uri);
  }

  diagnostics(uri: string): Diagnostic[] {
    return this.diags.get(uri) ?? [];
  }

  /** Explicitly-created folder paths (empty ones persist here). */
  folderPaths(): string[] {
    return [...this.folders].sort();
  }

  /** Error / warning counts for a file (severity 1 = error, else warning). */
  counts(uri: string): { errors: number; warnings: number } {
    let errors = 0;
    let warnings = 0;
    for (const d of this.diagnostics(uri)) {
      if (d.severity === 1) errors++;
      else warnings++;
    }
    return { errors, warnings };
  }

  totalCounts(): { errors: number; warnings: number } {
    let errors = 0;
    let warnings = 0;
    for (const uri of this.order) {
      const c = this.counts(uri);
      errors += c.errors;
      warnings += c.warnings;
    }
    return { errors, warnings };
  }

  /** Namespace-collision diagnostics (E1003/E1004) across every open file. */
  totalCollisions(): number {
    let n = 0;
    for (const uri of this.order) {
      for (const d of this.diagnostics(uri)) {
        if (isCollisionDiagnostic(d)) n++;
      }
    }
    return n;
  }

  // ─────────────────────────── mutations ───────────────────────────

  /** Add (or replace) a file by path.  Returns the stored file. */
  addFile(path: string, text: string, lang?: Lang): WorkspaceFile {
    const uri = pathToUri(path);
    const existing = this.filesByUri.get(uri);
    if (existing) {
      // Same path re-added → treat as an edit.
      this.setText(uri, text);
      return this.filesByUri.get(uri)!;
    }
    const file: WorkspaceFile = { uri, path, lang: lang ?? langForPath(path), text, version: 1 };
    this.filesByUri.set(uri, file);
    this.order.push(uri);
    this.emit({ type: "opened", file });
    if (this.active === null) this.setActive(uri);
    return file;
  }

  /** Create a new empty file (no-op edit if the path already exists). */
  createFile(path: string, text = ""): WorkspaceFile {
    return this.addFile(normalizePath(path), text);
  }

  /** Register an explicit (possibly empty) folder. */
  createFolder(path: string): void {
    const dir = normalizePath(path).replace(/\/+$/, "");
    if (!dir || this.folders.has(dir)) return;
    this.folders.add(dir);
    this.emit({ type: "folders" });
  }

  /**
   * Returns true when `path` already names something in the workspace:
   * a file, an explicit folder, or a directory prefix of any file.
   */
  private pathExists(path: string): boolean {
    if (this.filesByUri.has(pathToUri(path))) return true;
    if (this.folders.has(path)) return true;
    const prefix = path + "/";
    for (const f of this.files) {
      if (f.path.startsWith(prefix)) return true;
    }
    return false;
  }

  /** Move/rename a file or folder subtree from `oldPath` to `newPath`. */
  private repath(oldPath: string, newPath: string): void {
    if (oldPath === newPath) return;
    const moves = this.files
      .filter((f) => f.path === oldPath || f.path.startsWith(oldPath + "/"))
      .map((f) => ({
        oldUri: f.uri,
        newPath: newPath + f.path.slice(oldPath.length),
        text: f.text,
        wasActive: f.uri === this.active,
      }));
    for (const m of moves) {
      this.removeFile(m.oldUri);
      const nf = this.addFile(m.newPath, m.text);
      if (m.wasActive) this.setActive(nf.uri);
    }
    const remapped = [...this.folders].map((d) =>
      d === oldPath || d.startsWith(oldPath + "/") ? newPath + d.slice(oldPath.length) : d
    );
    this.folders.clear();
    for (const d of remapped) if (d) this.folders.add(d);
    this.emit({ type: "folders" });
  }

  /** Rename a file or folder in place (parent unchanged). */
  renameItem(oldPath: string, newName: string): void {
    const old = normalizePath(oldPath);
    const slash = old.lastIndexOf("/");
    const parent = slash >= 0 ? old.slice(0, slash) : "";
    const newPath = parent ? `${parent}/${newName}` : newName;
    if (newPath !== old && this.pathExists(newPath)) return;
    this.repath(old, newPath);
  }

  /** Move a file or folder into `destFolder` ("" = root). */
  moveItem(srcPath: string, destFolder: string): void {
    const src = normalizePath(srcPath);
    const dest = normalizePath(destFolder);
    if (!canMove(src, dest)) return;
    const name = src.includes("/") ? src.slice(src.lastIndexOf("/") + 1) : src;
    const newPath = dest ? `${dest}/${name}` : name;
    if (newPath !== src && this.pathExists(newPath)) return;
    this.repath(src, newPath);
  }

  /** Delete a file, or a folder and all of its descendants. */
  deleteItem(path: string): void {
    const p = normalizePath(path);
    const uri = pathToUri(p);
    if (this.filesByUri.has(uri)) {
      this.removeFile(uri);
      return;
    }
    for (const f of this.files) {
      if (f.path === p || f.path.startsWith(p + "/")) this.removeFile(f.uri);
    }
    for (const d of [...this.folders]) {
      if (d === p || d.startsWith(p + "/")) this.folders.delete(d);
    }
    this.emit({ type: "folders" });
  }

  setText(uri: string, text: string): void {
    const file = this.filesByUri.get(uri);
    if (!file || file.text === text) return;
    file.text = text;
    file.version += 1;
    this.emit({ type: "changed", file });
  }

  /** Bump the version and re-emit `changed` without altering text (reparse). */
  touch(uri: string): void {
    const file = this.filesByUri.get(uri);
    if (!file) return;
    file.version += 1;
    this.emit({ type: "changed", file });
  }

  removeFile(uri: string): void {
    if (!this.filesByUri.has(uri)) return;
    this.filesByUri.delete(uri);
    this.diags.delete(uri);
    const idx = this.order.indexOf(uri);
    if (idx >= 0) this.order.splice(idx, 1);
    this.emit({ type: "closed", uri });
    if (this.active === uri) {
      this.setActive(this.order[Math.min(idx, this.order.length - 1)] ?? null);
    }
  }

  setActive(uri: string | null): void {
    if (this.active === uri) return;
    if (uri !== null && !this.filesByUri.has(uri)) return;
    this.active = uri;
    this.emit({ type: "active", uri });
  }

  setDiagnostics(uri: string, diagnostics: Diagnostic[]): void {
    this.diags.set(uri, diagnostics);
    this.emit({ type: "diagnostics", uri });
  }

  // ─────────────────────────── bulk import/export ───────────────────────────

  /** Replace the whole workspace with the given files and folders. */
  replaceAll(entries: ZipEntry[], folders: string[] = []): void {
    for (const uri of [...this.order]) this.removeFile(uri);
    this.folders.clear();
    for (const d of folders) {
      const dir = normalizePath(d).replace(/\/+$/, "");
      if (dir) this.folders.add(dir);
    }
    for (const e of entries) this.addFile(normalizePath(e.path), e.text);
    if (folders.length) this.emit({ type: "folders" });
  }

  toEntries(): ZipEntry[] {
    return this.files.map((f) => ({ path: f.path, text: f.text }));
  }
}

/** Strip leading slashes / `./` so paths are workspace-relative. */
export function normalizePath(path: string): string {
  return path.replace(/^\.?\/+/, "");
}
