/**
 * Local types for the smlml-web app.
 *
 * LSP wire shapes are declared here (rather than pulling a dependency) so the
 * pure modules — lsp-client, workspace-store, resolve-node — stay self-contained
 * and headlessly testable.  The richer view-model / message types live with the
 * reused React app (editors/smlml-vscode/src/views/app/types.ts) and are imported
 * directly by the modules that drive it (view-host, mount-app).
 */

export type Lang = "sysml" | "kerml";

/** LSP Position — 0-based line, 0-based UTF-16 character. */
export interface LspPosition {
  line: number;
  character: number;
}

export interface LspRange {
  start: LspPosition;
  end: LspPosition;
}

/** LSP DiagnosticSeverity. */
export const enum Severity {
  Error = 1,
  Warning = 2,
  Information = 3,
  Hint = 4,
}

/** LSP Diagnostic (the subset we render). */
export interface Diagnostic {
  range: LspRange;
  severity?: Severity;
  message: string;
  source?: string;
  code?: string | number;
}

/**
 * Namespace-collision codes (`crates/smlml-ide/src/types.rs` `diagnostic_codes`).
 * Both are `Severity::Warning`, deliberately — the vendored stdlib carries
 * genuine collisions and making them errors would block ordinary work — so
 * they never gate render/export the way errors do, but a reader still needs
 * to be told a collision exists and which declaration won.
 */
export const AMBIGUOUS_IMPORT_CODE = "E1003";
export const AMBIGUOUS_REFERENCE_CODE = "E1004";

export function isCollisionDiagnostic(d: Diagnostic): boolean {
  return d.code === AMBIGUOUS_IMPORT_CODE || d.code === AMBIGUOUS_REFERENCE_CODE;
}

/** A source range as emitted by the view-model (matches the app's SourceRange). */
export interface SourceRange {
  startLine: number;
  startCol: number;
  endLine: number;
  endCol: number;
}

export type LogLevel = "info" | "wasm" | "op" | "warn" | "err";

/**
 * What a log line is *about*.
 *
 * `"OP"` used to cover the server's logMessage passthrough, reparse, format,
 * workspace export, file delete, seven AST export/import branches, the eval
 * toggle, the boot timings and buildView errors — WASM, LSP and UI work under
 * one label, which answered no question a reader of the Log tab could have had.
 *
 * A union rather than a string so a typo or a stale tag is a compile error.
 * `theme.css` keys its colours off the LEVEL, not the tag, so adding a tag
 * needs no CSS.
 *
 *   INFO       — app lifecycle breadcrumbs
 *   LSP        — server-originated messages (`window/logMessage`)
 *   WASM       — module instantiate and worker lifecycle
 *   EDITOR     — reparse, format, analyse the active file
 *   WORKSPACE  — import/export, delete, clear, seed, the eval toggle
 *   AST        — the `smlml/exportAst` / `smlml/importAst` cluster
 *   VIEW       — diagram view builds
 */
export type LogTag = "INFO" | "LSP" | "WASM" | "EDITOR" | "WORKSPACE" | "AST" | "VIEW";

export interface LogSink {
  log(tag: LogTag, msg: string, level?: LogLevel): void;
}
