/**
 * Minimal promise-based modal dialogs: a merge/replace chooser for zip import
 * and a yes/no confirmation.  Each resolves when the user clicks a button or
 * dismisses (overlay click / Esc → the cancel value).
 */

interface Choice<T> {
  label: string;
  value: T;
  primary?: boolean;
}

function dialog<T>(message: string, choices: Choice<T>[], cancelValue: T): Promise<T> {
  return new Promise<T>((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "modal-overlay";
    const box = document.createElement("div");
    box.className = "modal-box";
    const msg = document.createElement("div");
    msg.className = "modal-msg";
    msg.textContent = message;
    const row = document.createElement("div");
    row.className = "modal-actions";
    box.append(msg, row);
    overlay.appendChild(box);

    function finish(value: T): void {
      overlay.remove();
      document.removeEventListener("keydown", onKey, true);
      resolve(value);
    }
    function onKey(e: KeyboardEvent): void {
      if (e.key === "Escape") finish(cancelValue);
    }

    for (const c of choices) {
      const btn = document.createElement("button");
      btn.className = "modal-btn" + (c.primary ? " primary" : "");
      btn.textContent = c.label;
      btn.addEventListener("click", () => finish(c.value));
      row.appendChild(btn);
    }
    overlay.addEventListener("mousedown", (e) => {
      if (e.target === overlay) finish(cancelValue);
    });
    document.addEventListener("keydown", onKey, true);
    document.body.appendChild(overlay);
    (row.querySelector(".modal-btn.primary") as HTMLButtonElement | null)?.focus();
  });
}

/** Ask whether to merge a zip into the workspace or replace it. */
export function chooseMergeOrReplace(): Promise<"merge" | "replace" | null> {
  return dialog<"merge" | "replace" | null>(
    "Import zip into the current workspace?",
    [
      { label: "Merge", value: "merge", primary: true },
      { label: "Replace", value: "replace" },
      { label: "Cancel", value: null },
    ],
    null
  );
}

/** Yes/no confirmation (defaults to false on dismiss). */
export function confirmDialog(message: string, okLabel = "Delete"): Promise<boolean> {
  return dialog<boolean>(
    message,
    [
      { label: okLabel, value: true, primary: true },
      { label: "Cancel", value: false },
    ],
    false
  );
}
