/**
 * What each legend row *is*, in SysML source.
 *
 * A legend row names a piece of notation — a fork bar, a dashed line, a
 * boundary square — and a reader asking "what is this?" wants the language's
 * own answer. The editor already gives that answer when you hover the source
 * in the text panel, so a row is mapped here to a scrap of source that means
 * the same thing, and the host resolves it through that same hover lookup.
 * Nothing about the documentation is restated here: this file holds only the
 * row → source mapping, and the prose comes back from the language server.
 *
 * Each entry is a snippet plus the offset to ask about. A snippet rather than
 * a bare token because hover resolves against a parse, and a token alone does
 * not parse.
 *
 * Which token to point at depends on where the documentation lives. A modifier
 * or control keyword (`in`, `fork`, `decide`) has its own entry in the keyword
 * overlay, so the keyword is the right target. A declaration keyword (`part`,
 * `action`, `state`) has none, and its token resolves to a doc-less grammar
 * node — for those the declared NAME is the target, because it resolves to the
 * usage whose hover carries the metaclass prose.
 *
 * ## Keeping this in step with the legend
 *
 * Keys are the row captions `KindRows` renders and the relationship labels
 * `kindLabel` produces. A caption reworded in one place and not the other
 * loses its tooltip — a missing tooltip, never a wrong one, which is why the
 * lookup is by exact caption rather than by a fuzzy match.
 */

/** A snippet and the UTF-16 offset within it to ask for documentation about. */
export interface ConceptQuery {
  src: string;
  /** UTF-16 offset of the token whose documentation the row wants. */
  offset: number;
  lang: "sysml" | "kerml";
}

/**
 * Locate `token` in `src`.
 *
 * A token that is not in its own snippet is a typo in the table below, and it
 * yields no entry at all rather than throwing: this runs at module load inside
 * the webview, where a throw would take down the whole diagram over a missing
 * tooltip. `conceptFor` then returns `undefined` and the row is simply not
 * annotated — the same outcome as a row deliberately left out.
 */
function at(src: string, token: string, lang: ConceptQuery["lang"] = "sysml"): ConceptQuery | null {
  const start = src.indexOf(token);
  // The token's MIDPOINT, not its first character. A position on a token's
  // opening boundary resolves to whichever node starts there, so asking at
  // offset 0 of `part p;` answered with the enclosing member rather than with
  // the thing the row is about.
  return start < 0 ? null : { src, offset: start + Math.floor(token.length / 2), lang };
}

/**
 * Row caption → the syntax to ask the language about.
 *
 * Rows with no honest keyword are deliberately absent (a "Fired transition" is
 * a simulation overlay, not notation), and absent means no tooltip.
 */
const TABLE: Record<string, ConceptQuery | null> = {
  // ── Tree view ──
  "Package / Element": at("package P { }", "package"),
  Variation: at("part def V { }\nvariation part v : V;", "variation"),
  // ── Interconnection view ──
  // `part`/`action`/`state` carry no keyword-docs entry, and their keyword
  // token resolves to a doc-less grammar node (`PartKeyword`). The declared
  // NAME resolves to the usage itself, whose hover carries the metaclass
  // prose — which is the documentation the row is asking for.
  "Part / Item": at("part aPart;", "aPart"),
  "Port (in)": at("port p { in item i; }", "in"),
  "Port (out)": at("port p { out item i; }", "out"),
  // ── Action view ──
  Action: at("action anAction;", "anAction"),
  "Decision / Merge": at("action def A { decide d; }", "decide"),
  "Fork / Join": at("action def A { fork f; }", "fork"),
  "Send / Accept": at("action def A { accept x; }", "accept"),
  // ── State view ──
  State: at("state aState;", "aState"),
  "Active state": at("state aState;", "aState"),
  "Parallel state": at("state def S parallel { }", "parallel"),
  // ── Relationships (labels come from `kindLabel`) ──
  "Feature typing": at("part p : P;", ":"),
  Specialization: at("part def A specializes B;", "specializes"),
  Redefinition: at("part def A { part b redefines c; }", "redefines"),
  Subsetting: at("part def A { part b subsets c; }", "subsets"),
  Connection: at("part def A { connect x to y; }", "connect"),
  "Binding connector": at("part def A { bind x = y; }", "bind"),
  Interface: at("interface def AnInterface { }", "AnInterface"),
  Flow: at("part def A { flow x to y; }", "flow"),
  Succession: at("action def A { first x then y; }", "first"),
  "Perform action": at("part def A { perform action b; }", "perform"),
  Transition: at("state def S { transition first a then b; }", "transition"),
  Dependency: at("dependency from A to B;", "dependency"),
  Allocation: at("allocation def AnAllocation { }", "AnAllocation"),
  Comment: at("comment /* text */", "comment"),
  Metadata: at("metadata def AMetadata { }", "AMetadata"),
  "Variant membership": at("part def V { variant part a; }", "variant"),
  Subject: at("requirement def R { subject s; }", "subject"),
  Assume: at("requirement def R { assume constraint { true } }", "assume"),
  Require: at("requirement def R { require constraint { true } }", "require"),
  Objective: at("case def C { objective { } }", "objective"),
  "Guard / conditional": at("action def A { first x if g then y; }", "if"),
};

/** The rows that resolved — a mistyped token drops out here, not at load. */
export const LEGEND_CONCEPTS: Record<string, ConceptQuery> = Object.fromEntries(
  Object.entries(TABLE).filter((e): e is [string, ConceptQuery] => e[1] !== null)
);

/** The syntax a legend row is about, or `undefined` for a row with none. */
export function conceptFor(label: string): ConceptQuery | undefined {
  return LEGEND_CONCEPTS[label];
}
