import React from "react";
import { Handle, Position, type NodeProps } from "@xyflow/react";
import { formOf } from "./form";

export function ActionForkJoinNode({ data }: NodeProps) {
  // Server-classified family, authoritative and shared with the CLI painters;
  // "default" is the wire's own fallback for a node with no family tint.
  const family = (data.family as string | undefined) ?? "default";
  // The bar lies ACROSS the flow: horizontal in a top-to-bottom graph, vertical
  // in a left-to-right one. `layout.ts` stamps the orientation on the node from
  // the same `direction` that sized the box, so the painted bar and the slot
  // ELK reserved for it cannot disagree. Absent ⇒ horizontal, the DOWN default.
  const vertical = (data.barVertical as boolean | undefined) ?? false;
  return (
    <div className={`fam-${family}`} data-form={formOf(data)}>
      <Handle type="target" position={vertical ? Position.Left : Position.Top} />
      <div className={`smlml-action-forkjoin${vertical ? " smlml-action-forkjoin-v" : ""}`} />
      <Handle type="source" position={vertical ? Position.Right : Position.Bottom} />
    </div>
  );
}
