/**
 * Client-side syntax highlighting for SysML/KerML.
 *
 * The WASM language server deliberately omits keyword/operator tokens from
 * `textDocument/semanticTokens/full` (it expects a TextMate grammar to colour
 * them — see crates/smlml-ide/src/semantic_tokens.rs).  In VS Code that grammar
 * supplies keyword/comment/string/number colour; the server's semantic tokens
 * add only definition *names* (type/namespace).  On the plain web page there is
 * no TextMate engine, so without this module only `Vehicle`/`Wheel`-style names
 * get colour.
 *
 * This is a lightweight CodeMirror `StreamLanguage` that recolours keywords,
 * comments, strings, numbers and operators.  It intentionally returns `null`
 * for plain identifiers so the server's semantic-token decorations (type and
 * namespace names) still show through on top.  Colours stay central in
 * theme.css via `HighlightStyle` class bindings (`tok-*`).
 */

import {
  HighlightStyle,
  LanguageSupport,
  StreamLanguage,
  syntaxHighlighting,
  type StreamParser,
} from "@codemirror/language";
import { tags as t } from "@lezer/highlight";
import type { Lang } from "../types.ts";

/** The KerML ∪ SysML reserved-keyword union (generated list, kept in sync with
 *  crates/smlml-syntax `#[token(...)]` entries). */
const KEYWORDS = new Set<string>(
  (
    "about abstract accept action actor after alias all allocate allocation analysis and as " +
    "assert assign assoc assume at attribute behavior bind binding bool by calc case chains " +
    "class classifier comment composite concern conjugate conjugates conjugation connect " +
    "connection connector const constant constraint crosses datatype decide def default " +
    "defined dependency derived differences disjoining disjoint do doc else end entry enum " +
    "event exhibit exit expose expr false feature featured featuring filter first flow for " +
    "fork frame from function hastype if implies import in include individual inout interaction " +
    "interface intersects inv inverse inverting istype item join language library locale loop " +
    "member merge message meta metaclass metadata multiplicity namespace new nonunique not " +
    "null objective occurrence of or ordered out package parallel part perform port portion " +
    "predicate private protected public redefines redefinition ref references render rendering " +
    "rep require requirement return satisfy send snapshot specialization specializes stakeholder " +
    "standard state step struct subclassifier subject subset subsets subtype succession " +
    "terminate then timeslice to transition true type typed typing unions until use var variant " +
    "variation verification verify via view viewpoint when while xor"
  ).split(" ")
);

const IDENT_START = /[A-Za-z_]/;
const IDENT_CHAR = /[A-Za-z0-9_]/;
const DIGIT = /[0-9]/;
const OPERATOR = /[-+*/%^&|=!<>~]/;

interface State {
  inBlockComment: boolean;
}

const parser: StreamParser<State> = {
  startState: () => ({ inBlockComment: false }),
  token(stream, state) {
    // Inside a block comment — consume until the closing */.
    if (state.inBlockComment) {
      while (!stream.eol()) {
        if (stream.match("*/")) {
          state.inBlockComment = false;
          break;
        }
        stream.next();
      }
      return "comment";
    }

    if (stream.eatSpace()) return null;

    // Line comment.
    if (stream.match("//")) {
      stream.skipToEnd();
      return "comment";
    }
    // Block comment.
    if (stream.match("/*")) {
      state.inBlockComment = true;
      while (!stream.eol()) {
        if (stream.match("*/")) {
          state.inBlockComment = false;
          break;
        }
        stream.next();
      }
      return "comment";
    }

    const ch = stream.peek() ?? "";

    // String literal.
    if (ch === '"') {
      stream.next();
      let escaped = false;
      while (!stream.eol()) {
        const c = stream.next();
        if (escaped) {
          escaped = false;
        } else if (c === "\\") {
          escaped = true;
        } else if (c === '"') {
          break;
        }
      }
      return "string";
    }

    // Number (decimal / exponential).
    if (DIGIT.test(ch)) {
      stream.eatWhile(/[0-9_]/);
      if (stream.eat(".")) stream.eatWhile(/[0-9_]/);
      if (stream.eat(/[eE]/)) {
        stream.eat(/[+-]/);
        stream.eatWhile(/[0-9]/);
      }
      return "number";
    }

    // Identifier or keyword.
    if (IDENT_START.test(ch)) {
      let word = "";
      while (!stream.eol() && IDENT_CHAR.test(stream.peek() ?? "")) {
        word += stream.next();
      }
      return KEYWORDS.has(word) ? "keyword" : null;
    }

    // Operator.
    if (OPERATOR.test(ch)) {
      stream.eatWhile(OPERATOR);
      return "operator";
    }

    stream.next();
    return null;
  },
};

/** Map highlight tags to the central `tok-*` classes defined in theme.css. */
const smlHighlightStyle = HighlightStyle.define([
  { tag: t.keyword, class: "tok-kw" },
  { tag: t.comment, class: "tok-cmt" },
  { tag: t.string, class: "tok-str" },
  { tag: t.number, class: "tok-num" },
  { tag: t.operator, class: "tok-op" },
]);

const smlLanguage = StreamLanguage.define(parser);

/** CodeMirror language support for SysML/KerML (the parser is shared; the two
 *  dialects differ only in which keywords are reserved, which is immaterial for
 *  colouring since the union is highlighted). */
export function smlLanguageSupport(_lang: Lang) {
  return new LanguageSupport(smlLanguage, [syntaxHighlighting(smlHighlightStyle)]);
}
