/**
 * Simulation overlay: mark the active state and the fired transition on a v2
 * ViewModel. The engine's `currentState` is a view node id and `firedEdgeId`
 * is a view edge id (see `state_machine_from_view` in smlml-view), so these
 * match the model's `id`s directly. Returns a new model; does not mutate.
 */
import type { ViewModel } from "./types";

export function applyStateOverlay(
  model: ViewModel,
  currentState: string,
  firedEdgeId: string | null,
): ViewModel {
  return {
    ...model,
    nodes: model.nodes.map(n => ({ ...n, is_active: n.id === currentState })),
    edges: model.edges.map(e => ({
      ...e,
      is_fired: firedEdgeId != null && e.id === firedEdgeId,
    })),
  };
}
