/**
 * Minimal, dependency-free Markdown renderer for hover tooltips.
 *
 * The LSP `textDocument/hover` response is Markdown (see smlml-lsp): fenced
 * ```sysml code blocks, `**bold**`, `*italic*`, inline `` `code` `` and a `—`
 * separator.  Rather than pull a full Markdown library, we render exactly that
 * subset into safe DOM nodes (all literal text goes through `textContent`, so no
 * HTML injection from element/identifier names).
 */

const FENCE = /```(\w*)\n([\s\S]*?)```/g;

/** Render `md` into `container` as DOM nodes (cleared first). */
export function renderMarkdown(container: HTMLElement, md: string): void {
  container.textContent = "";
  let last = 0;
  let m: RegExpExecArray | null;
  FENCE.lastIndex = 0;
  while ((m = FENCE.exec(md)) !== null) {
    if (m.index > last) appendText(container, md.slice(last, m.index));
    const pre = document.createElement("pre");
    const code = document.createElement("code");
    if (m[1]) code.dataset.lang = m[1];
    code.textContent = m[2].replace(/\n$/, "");
    pre.appendChild(code);
    container.appendChild(pre);
    last = m.index + m[0].length;
  }
  if (last < md.length) appendText(container, md.slice(last));
}

/**
 * A paragraph that is the SysML/KerML specification's own prose rather than the
 * model's.
 *
 * The server composes a hover from up to three parts — a fenced signature, the
 * element's own `doc`, and the metaclass's spec text — and the last is the one
 * that belongs to the language rather than to the file being edited. It is
 * recognisable by the citation it always closes with (`*[SysML 8.2.2.21.1
 * (Requirement Definitions)]*`), which is a stronger signal than "starts with
 * bold": an element's own doc may be bold too.
 */
const SPEC_CITATION = /\*\[(?:SysML|KerML)\s[^\]]*\]\*\s*$/;

/** Render a non-code Markdown segment: paragraphs split on blank lines, inline
 *  emphasis/code within. */
function appendText(container: HTMLElement, text: string): void {
  const trimmed = text.replace(/^\n+/, "").replace(/\n+$/, "");
  if (!trimmed) return;
  for (const para of trimmed.split(/\n{2,}/)) {
    // Rule off the spec prose from whatever the model itself said above it —
    // but only when there is something above it to separate. A keyword hover is
    // spec text and nothing else, and a leading rule there would divide the
    // popup from its own top edge.
    if (SPEC_CITATION.test(para) && container.childNodes.length > 0) {
      container.appendChild(document.createElement("hr"));
    }
    const p = document.createElement("div");
    p.className = "md-p";
    appendInline(p, para);
    container.appendChild(p);
  }
}

const INLINE = /(\*\*([^*]+)\*\*|\*([^*]+)\*|`([^`]+)`)/g;

/** Render inline `**bold**`, `*italic*`, `` `code` ``; newlines → <br>. */
function appendInline(parent: HTMLElement, text: string): void {
  let last = 0;
  let m: RegExpExecArray | null;
  INLINE.lastIndex = 0;
  while ((m = INLINE.exec(text)) !== null) {
    if (m.index > last) appendWithBreaks(parent, text.slice(last, m.index));
    let el: HTMLElement;
    if (m[2] !== undefined) {
      el = document.createElement("strong");
      el.textContent = m[2];
    } else if (m[3] !== undefined) {
      el = document.createElement("em");
      el.textContent = m[3];
    } else {
      el = document.createElement("code");
      el.textContent = m[4];
    }
    parent.appendChild(el);
    last = m.index + m[0].length;
  }
  if (last < text.length) appendWithBreaks(parent, text.slice(last));
}

function appendWithBreaks(parent: HTMLElement, text: string): void {
  const parts = text.split("\n");
  parts.forEach((part, i) => {
    if (i > 0) parent.appendChild(document.createElement("br"));
    if (part) parent.appendChild(document.createTextNode(part));
  });
}
