/**
 * Mounts the reused React/React-Flow diagram app — imported verbatim from the
 * VS Code extension, with ZERO edits to that package.
 *
 * The app's only host coupling is that it takes a `{ postMessage }` object and
 * listens on `window` `"message"` (see smlml-vscode/.../App.tsx).  We satisfy it
 * with an in-process bridge: a `postMessage` shim captures the app's outbound
 * `WebviewToExtMsg`, and host→app `ExtToWebviewMsg` are delivered by dispatching
 * a `window` MessageEvent.  No iframe, no real postMessage, no protocol change.
 */

import { createElement } from "react";
import { createRoot } from "react-dom/client";
import { App } from "../../../smlml-vscode/src/views/app/App";
import { installFamilyPalette } from "../../../smlml-vscode/src/views/app/palette";
import "../../../smlml-vscode/src/views/app/theme.css";
import "@xyflow/react/dist/style.css";
import type {
  ExtToWebviewMsg,
  WebviewToExtMsg,
} from "../../../smlml-vscode/src/views/app/types";

export interface MountedApp {
  /** Host → app: deliver a message the app expects on `window` "message". */
  post(msg: ExtToWebviewMsg): void;
  /** App → host: subscribe to messages the app sends via `vscode.postMessage`. */
  subscribe(cb: (msg: WebviewToExtMsg) => void): void;
  unmount(): void;
}

export function mountDiagramApp(container: HTMLElement): MountedApp {
  // Family CSS custom properties, injected against the container's own
  // document rather than the global `document` so this stays correct if the
  // web editor ever mounts the app into an iframe or a detached document.
  installFamilyPalette(container.ownerDocument ?? document);

  let sink: ((msg: WebviewToExtMsg) => void) | null = null;
  const buffered: WebviewToExtMsg[] = [];

  const vscodeShim = {
    postMessage: (msg: unknown) => {
      const m = msg as WebviewToExtMsg;
      if (sink) sink(m);
      else buffered.push(m); // e.g. the initial {type:"ready"} before subscribe
    },
  };

  const root = createRoot(container);
  root.render(createElement(App, { vscode: vscodeShim }));

  return {
    post: (msg) => window.dispatchEvent(new MessageEvent("message", { data: msg })),
    subscribe: (cb) => {
      sink = cb;
      for (const m of buffered.splice(0)) cb(m);
    },
    unmount: () => root.unmount(),
  };
}
