/**
 * Adapts the WASM web worker to the `RpcTransport` interface, and surfaces the
 * worker's out-of-band control messages (lifecycle log breadcrumbs + the
 * ready/error handshake) so the composition root can drive the boot sequence.
 */

import type { AnyMessage, RpcTransport } from "./lsp-client.ts";
import type { LogSink, LogTag } from "../types.ts";

interface WorkerControl {
  type: "smlml-log" | "smlml-ready" | "smlml-error" | "smlml-snippet-hover-result";
  tag?: string;
  msg?: string;
  message?: string;
  id?: number;
  markdown?: string | null;
}

export interface WorkerTransport extends RpcTransport {
  /** Resolves when the worker reports the WASM module is initialized. */
  ready: Promise<void>;
  /**
   * Documentation for a standalone snippet, at a UTF-16 offset into it.
   *
   * The same `analysis.hover_at_byte` lookup `textDocument/hover` performs,
   * reached without an open document — see the protocol note in `worker.js`
   * for why the legend needs that and why it is not a second doc source.
   * Resolves to `null` when the position has no documentation.
   */
  snippetHover(src: string, lang: string, offset: number): Promise<string | null>;
  /** Terminate the underlying worker. */
  dispose(): void;
}

/**
 * Create a transport over a freshly-spawned worker and kick off WASM init.
 * `log` receives the worker's lifecycle breadcrumbs (tagged WASM).
 */
export function createWorkerTransport(workerUrl: string | URL, log: LogSink): WorkerTransport {
  const worker = new Worker(workerUrl, { type: "module" });
  let rpcCallback: ((msg: AnyMessage) => void) | null = null;

  // Snippet-hover requests in flight, by id. Kept off the JSON-RPC id space so
  // a control message can never be mistaken for an LSP response.
  const pendingHovers = new Map<number, (markdown: string | null) => void>();
  let nextHoverId = 1;

  let resolveReady!: () => void;
  let rejectReady!: (e: Error) => void;
  const ready = new Promise<void>((res, rej) => {
    resolveReady = res;
    rejectReady = rej;
  });

  worker.onmessage = (ev: MessageEvent) => {
    const data = ev.data as WorkerControl | AnyMessage;
    const ctrl = data as WorkerControl;
    switch (ctrl.type) {
      case "smlml-log": {
        // `worker.js` only ever tags its breadcrumbs "WASM"; anything else would
        // be a message shape we do not know, so it logs as a lifecycle note
        // rather than claiming to be about the module.
        const tag: LogTag = ctrl.tag === "WASM" ? "WASM" : "INFO";
        log.log(tag, ctrl.msg ?? "", "wasm");
        return;
      }
      case "smlml-ready":
        resolveReady();
        return;
      case "smlml-error":
        log.log("WASM", `init failed: ${ctrl.message ?? "unknown"}`, "err");
        rejectReady(new Error(ctrl.message ?? "WASM init failed"));
        return;
      case "smlml-snippet-hover-result": {
        const resolve = ctrl.id === undefined ? undefined : pendingHovers.get(ctrl.id);
        if (resolve && ctrl.id !== undefined) {
          pendingHovers.delete(ctrl.id);
          resolve(ctrl.markdown ?? null);
        }
        return;
      }
      default:
        // A real JSON-RPC message.
        rpcCallback?.(data as AnyMessage);
    }
  };

  worker.onerror = (ev: ErrorEvent) => {
    log.log("WASM", `worker error: ${ev.message}`, "err");
    rejectReady(new Error(ev.message));
    // A dead worker answers nothing further, so settle every waiter rather
    // than leaving the callers holding promises that can no longer resolve.
    for (const [, resolve] of pendingHovers) resolve(null);
    pendingHovers.clear();
  };

  // Trigger initialization.
  worker.postMessage({ type: "smlml-init" });

  return {
    post: (msg: unknown) => worker.postMessage(msg),
    onMessage: (cb) => {
      rpcCallback = cb;
    },
    ready,
    snippetHover: (src, lang, offset) =>
      new Promise<string | null>((resolve) => {
        const id = nextHoverId++;
        pendingHovers.set(id, resolve);
        worker.postMessage({ type: "smlml-snippet-hover", id, src, lang, offset });
      }),
    dispose: () => {
      for (const [, resolve] of pendingHovers) resolve(null);
      pendingHovers.clear();
      worker.terminate();
    },
  };
}
