/**
 * Inline calculation-result decorations.
 *
 * Mirrors the VS Code `CalcResultDecoration` / CodeLens surface the prototype
 * showed: each solved calc feature gets an italic `= value unit` annotation at
 * the end of its declaration line.  Fed from `smlml/runCalc` results (see
 * ValuesPanel); colours come from theme.css (`.calc-deco`).
 */

import { EditorState, StateEffect, StateField, type Extension } from "@codemirror/state";
import { Decoration, EditorView, WidgetType, type DecorationSet } from "@codemirror/view";
import { calcAnnotationSpans, type CalcLock } from "./calc-annotation.ts";

// Re-exported so importers of this module keep working; the type itself lives
// with the annotation's structure, which both frontends have to agree on.
export type { CalcLock };

export interface CalcResult {
  /** 0-based line of the calc declaration. */
  line: number;
  value: string;
  unit: string | null;
  /** Binding mutability; absent when the server didn't classify it. */
  lock?: CalcLock | null;
}

export const setCalcResults = StateEffect.define<CalcResult[]>();

class CalcWidget extends WidgetType {
  constructor(
    private readonly value: string,
    private readonly unit: string | null,
    private readonly lock: CalcLock | null
  ) {
    super();
  }
  eq(other: CalcWidget): boolean {
    return (
      other.value === this.value &&
      other.unit === this.unit &&
      other.lock?.kind === this.lock?.kind
    );
  }
  toDOM(): HTMLElement {
    const span = document.createElement("span");
    span.className = "calc-deco";
    span.setAttribute("aria-hidden", "true");
    // One element per descriptor span, so `calc-marker` can be dimmed and
    // `calc-value` emphasised independently. See calc-annotation.ts.
    for (const s of calcAnnotationSpans(this.value, this.unit, this.lock)) {
      const el = document.createElement("span");
      el.className = s.className;
      el.textContent = s.text;
      if (s.title) el.title = s.title;
      span.appendChild(el);
    }
    return span;
  }
}

function build(state: EditorState, results: CalcResult[]): DecorationSet {
  const doc = state.doc;
  const ranges = [];
  for (const r of results) {
    if (r.line < 0 || r.line >= doc.lines) continue;
    const line = doc.line(r.line + 1);
    ranges.push(
      Decoration.widget({
        widget: new CalcWidget(r.value, r.unit, r.lock ?? null),
        side: 1,
      }).range(line.to)
    );
  }
  ranges.sort((a, b) => a.from - b.from);
  return Decoration.set(ranges, true);
}

export function calcDecorationsExtension(): Extension {
  return StateField.define<DecorationSet>({
    create: () => Decoration.none,
    update(deco, tr) {
      let next = tr.docChanged ? deco.map(tr.changes) : deco;
      for (const e of tr.effects) {
        if (e.is(setCalcResults)) {
          next = build(tr.state, e.value);
        }
      }
      return next;
    },
    provide: (f) => EditorView.decorations.from(f),
  });
}
