import type { LspRange } from "../types.ts";

export interface DefinitionTarget {
  uri: string;
  range: LspRange;
}

interface Location {
  uri: string;
  range: LspRange;
}

interface LocationLink {
  targetUri: string;
  targetRange: LspRange;
  targetSelectionRange: LspRange;
}

export type DefinitionResponse = Location | Location[] | LocationLink[] | null;

/** Pick the first declaration from any valid LSP definition response shape. */
export function firstDefinitionTarget(response: DefinitionResponse): DefinitionTarget | null {
  if (!response) return null;
  const first = Array.isArray(response) ? response[0] : response;
  if (!first) return null;
  if ("targetUri" in first) {
    return {
      uri: first.targetUri,
      range: first.targetSelectionRange ?? first.targetRange,
    };
  }
  return { uri: first.uri, range: first.range };
}
