/**
 * The canvas's node-position lock, as a control on the bottom-left toolbar.
 *
 * ## Why not React Flow's own padlock
 *
 * `<Controls>` ships an interactivity toggle, and it cannot express what this
 * diagram means by "locked". Its state is derived from three store flags at
 * once — `nodesDraggable`, `nodesConnectable`, `elementsSelectable` — and it
 * writes all three together. This canvas locks *dragging* while keeping nodes
 * selectable, because clicking a node navigates to its source. So the padlock
 * read the canvas as unlocked (selectable is true), its first click set all
 * three false, and only a second click made nodes draggable: the "lock it,
 * then unlock it" dance a reader had to perform before a node would move.
 * Worse, that first click silently dropped selectability and with it
 * click-to-navigate.
 *
 * This button holds no state of its own. It renders the lock the diagram
 * actually has and toggles that one flag, so the two cannot disagree —
 * `showInteractive={false}` retires the control that could.
 */

import React from "react";
import { ControlButton } from "@xyflow/react";

export function LockControl({
  locked,
  onChange,
}: {
  locked: boolean;
  /** Called with the new lock state. */
  onChange: (locked: boolean) => void;
}) {
  return (
    <ControlButton
      onClick={() => onChange(!locked)}
      title={locked ? "Unlock node positions" : "Lock node positions"}
      aria-label={locked ? "Unlock node positions" : "Lock node positions"}
      aria-pressed={locked}
      className="smlml-lock-control"
    >
      {/* Shackle up and open when unlocked, down and closed when locked — the
          state the diagram is in, not the action the click performs, matching
          how the Settings checkbox beside it reads. */}
      <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth={1.4}>
        <rect x="3.2" y="7" width="9.6" height="7" rx="1.2" fill="currentColor" stroke="none" />
        <path d={locked ? "M5.5 7V4.8a2.5 2.5 0 0 1 5 0V7" : "M5.5 7V4.8a2.5 2.5 0 0 1 5 0"} />
      </svg>
    </ControlButton>
  );
}
