/**
 * Seed workspace — a coherent Earth-observation satellite model.
 *
 * The source examples live under `editors/smlml-web/example/` so they can be
 * edited as ordinary SysML files. `esbuild.config.js` reads that directory and
 * defines `__SMLML_EXAMPLES__`, embedding the same files in the browser bundle;
 * the Node fallback keeps the source-level tests useful without a build first.
 *
 * Expected top-level calculation results:
 *
 *   totalMass   = 4×3.5  + 2×8 + 8×0.22 + 45 + 12  =  88.76 kg
 *   solarGen    = 4×120                               =  480    W
 *   houseLoad   = 50 + 80                             =  130    W
 *   powerMargin = 480 − 130                           =  350    W
 *   peakDemand  = max(480, 130)                       =  480    W
 *   totalEnergy = 2 × 1 296 000                       =  2 592 000 J
 *   eclipseTime = 2 592 000 J / 130 W                 ≈  19 938 s
 *   totalThrust = 8 × 0.5                             =    4    N
 *   overBudget  = (88.76 kg > 100 kg)                 =  false
 *   safePower   = (350 W > 0 W) ? 1 : 0               =  1
 *
 * Battery.peakPower  = 28 V × 46 A                    = 1 288 W
 * SolarPanel.area    = 0.6 m × 1.0 m                  = 0.6 m²
 *
 * CalculationPatterns.sysml additionally demonstrates nested equations,
 * typed and directly invoked calculations, constraint predicates and
 * derivation equations, bindings, stdlib collection/numeric functions, and
 * specialization/redefinition. Functions.kerml demonstrates a KerML Function
 * with a local equation and trailing result expression.
 */

import type { ZipEntry } from "./zip.ts";

/** The files included in the example workspace, in stable tree order. */
const EXAMPLE_PATHS = [
  "satellite.sysml",
  "interfaces/Interfaces.sysml",
  "subsystems/SolarPanel.sysml",
  "subsystems/Battery.sysml",
  "subsystems/Thruster.sysml",
  "structure/Geometry.sysml",
  "structure/GeometryStack.sysml",
  "structure/GeometryReferences.sysml",
  "structure/GeometryVehicleFrames.sysml",
  "structure/GeometryWheelPattern.sysml",
  "control/PowerMode.sysml",
  "behavior/Operations.sysml",
  "mission/MissionTimeline.sysml",
  "mission/FlightArticle.sysml",
  "requirements/Requirements.sysml",
  "analysis/CalculationPatterns.sysml",
  "analysis/Functions.kerml",
] as const;

/** Supplied by esbuild.config.js for the browser build. */
declare const __SMLML_EXAMPLES__: ZipEntry[];

type NodeProcess = {
  getBuiltinModule?: (name: string) => unknown;
  cwd?: () => string;
};

type NodeFs = {
  readFileSync(path: string, encoding: "utf8"): string;
};

type NodePath = {
  join(...parts: string[]): string;
};

/**
 * Read the checked-in examples when this module is loaded directly by Node.
 * `process.getBuiltinModule` avoids a static `node:fs` import, which would
 * otherwise become a browser-bundle dependency even though the build branch
 * embeds the files and never calls this fallback.
 */
function readExamplesFromDisk(): ZipEntry[] {
  const nodeProcess = (globalThis as { process?: NodeProcess }).process;
  const getBuiltinModule = nodeProcess?.getBuiltinModule;
  if (!getBuiltinModule) {
    throw new Error("Example files were not embedded; run the web build first.");
  }
  const fs = getBuiltinModule("node:fs") as NodeFs;
  const pathModule = getBuiltinModule("node:path") as NodePath;
  const cwd = nodeProcess?.cwd?.() ?? ".";
  return EXAMPLE_PATHS.map((path) => ({
    path,
    text: readExampleFile(fs, pathModule, cwd, path),
  }));
}

function readExampleFile(fs: NodeFs, pathModule: NodePath, cwd: string, path: string): string {
  const segments = path.split("/");
  const candidates = [
    pathModule.join(cwd, "example", ...segments),
    pathModule.join(cwd, "editors", "smlml-web", "example", ...segments),
  ];
  for (const candidate of candidates) {
    try {
      return fs.readFileSync(candidate, "utf8");
    } catch {
      // Try the other project-root shape used by direct source-level tests.
    }
  }
  throw new Error(`Example file not found: ${path}`);
}

function loadExamples(): ZipEntry[] {
  return typeof __SMLML_EXAMPLES__ === "undefined"
    ? readExamplesFromDisk()
    : __SMLML_EXAMPLES__;
}

/** The example workspace seeded on first launch or via the Examples button. */
export const SEED_FILES: ZipEntry[] = loadExamples();
