/**
 * Values panel — the calculation solve tree.
 *
 * Discovers calc features via `textDocument/codeLens` (the server emits a
 * `smlml.runCalc` lens per calc, carrying `{ uri, calcPath }`), then evaluates
 * each through `smlml/runCalc` and renders the resolved values.  Clicking a row
 * navigates the editor to the lens line.
 */

import type { LspGateway } from "../diagram/view-host.ts";
import type { CalcLock } from "../editor/calc-decorations.ts";

interface CodeLens {
  range: { start: { line: number; character: number } };
  command?: {
    command: string;
    title: string;
    arguments?: Array<{ uri: string; calcPath: string; lock?: CalcLock | null }>;
  };
}

interface RunCalcResult {
  value: string;
  path: string[];
  unit?: string | null;
}

export interface SolveRow {
  calcPath: string;
  value: string;
  unit: string | null;
  uri: string;
  line: number;
  /** Binding mutability (locked `=` vs modifiable `:=`/`default`), from the lens. */
  lock: CalcLock | null;
}

export interface ValuesCallbacks {
  onNavigate(uri: string, line: number, character: number): void;
}

export class ValuesPanel {
  constructor(
    private readonly container: HTMLElement,
    private readonly countEl: HTMLElement,
    private readonly lsp: LspGateway,
    private readonly cbs: ValuesCallbacks
  ) {}

  /** Re-evaluate and render the calc values for `uri`; returns the solved rows
   *  (so the caller can mirror them as inline editor annotations). */
  async refresh(uri: string): Promise<SolveRow[]> {
    let rows: SolveRow[] = [];
    try {
      const lenses = await this.lsp.sendRequest<CodeLens[]>("textDocument/codeLens", {
        textDocument: { uri },
      });
      const calcLenses = (lenses ?? []).filter((l) => l.command?.command === "smlml.runCalc");
      rows = await this.evaluate(calcLenses);
    } catch {
      rows = [];
    }
    this.render(rows);
    this.countEl.textContent = String(rows.length);
    return rows;
  }

  clear(): void {
    this.render([]);
    this.countEl.textContent = "0";
  }

  private async evaluate(lenses: CodeLens[]): Promise<SolveRow[]> {
    const out: SolveRow[] = [];
    for (const lens of lenses) {
      const arg = lens.command?.arguments?.[0];
      if (!arg) continue;
      try {
        const r = await this.lsp.sendRequest<RunCalcResult>("smlml/runCalc", {
          uri: arg.uri,
          calcPath: arg.calcPath,
        });
        out.push({
          calcPath: arg.calcPath,
          value: r.value,
          unit: r.unit ?? null,
          uri: arg.uri,
          line: lens.range.start.line,
          lock: arg.lock ?? null,
        });
      } catch {
        // Skip calcs that fail to evaluate.
      }
    }
    return out;
  }

  private render(rows: SolveRow[]): void {
    this.container.innerHTML = "";
    const status = document.createElement("div");
    status.className = "solve-status";
    status.innerHTML =
      rows.length > 0
        ? `<span class="ok">●</span> solved ${rows.length} feature${rows.length === 1 ? "" : "s"}`
        : `<span>no calculated features in this file</span>`;
    this.container.appendChild(status);

    if (rows.length === 0) return;

    const tree = document.createElement("div");
    tree.className = "solve-tree";
    for (const row of rows) {
      const el = document.createElement("div");
      el.className = "srow";
      el.innerHTML =
        `<span class="tw leaf">·</span>` +
        `<span class="path"></span><span class="eq">=</span>` +
        `<span class="value"></span><span class="unit"></span>`;
      el.querySelector(".path")!.textContent = row.calcPath;
      el.querySelector(".value")!.textContent = row.value;
      el.querySelector(".unit")!.textContent = row.unit ?? "";
      el.addEventListener("click", () => this.cbs.onNavigate(row.uri, row.line, 0));
      tree.appendChild(el);
    }
    this.container.appendChild(tree);
  }
}
