/**
 * File tree — renders the workspace as a nested, collapsible tree with
 * per-file error/warning badges and active-file highlighting.  Supports
 * create (header + buttons, inline), rename (context menu, inline), delete /
 * download (context menu), drag-and-drop moves between folders, and external
 * `.sysml` / `.kerml` file drops for import.
 */

import type { WorkspaceStore } from "../workspace/workspace-store.ts";
import { buildTree, isValidName, isValidFileName, canMove, type TreeNode } from "../workspace/tree.ts";
import { showContextMenu } from "./context-menu.ts";

const DRAG_TYPE = "application/x-smlml-path";

export interface FileTreeCallbacks {
  onSelect(uri: string): void;
  onCreateFile(path: string): void;
  onCreateFolder(path: string): void;
  onRename(oldPath: string, newName: string): void;
  onMove(srcPath: string, destFolder: string): void;
  onDelete(path: string): void;
  onDownload(path: string): void;
  onDropFiles(files: File[]): void;
}

/** A transient inline editor request, applied on the next render. */
type Pending =
  | { mode: "createFile" | "createFolder"; parent: string }
  | { mode: "rename"; path: string; kind: "file" | "folder" };

export class FileTree {
  private readonly collapsed = new Set<string>();
  private pending: Pending | null = null;

  constructor(
    private readonly listEl: HTMLElement,
    private readonly rootEl: HTMLElement,
    newFileBtn: HTMLElement,
    newFolderBtn: HTMLElement,
    private readonly store: WorkspaceStore,
    private readonly cbs: FileTreeCallbacks
  ) {
    this.installRootDnd();
    newFileBtn.addEventListener("click", () => {
      this.pending = { mode: "createFile", parent: "" };
      this.render();
    });
    newFolderBtn.addEventListener("click", () => {
      this.pending = { mode: "createFolder", parent: "" };
      this.render();
    });
  }

  render(): void {
    this.listEl.innerHTML = "";
    const nodes = buildTree(
      this.store.files.map((f) => ({ path: f.path, uri: f.uri })),
      this.store.folderPaths()
    );
    // Inline create at root goes above the tree.
    if (this.pending && this.pending.mode !== "rename" && this.pending.parent === "") {
      this.listEl.appendChild(this.editorRow(0, this.pending));
    }
    for (const n of nodes) this.renderNode(n, 0);
  }

  private renderNode(node: TreeNode, depth: number): void {
    if (node.kind === "folder") {
      this.listEl.appendChild(this.folderRow(node, depth));
      if (this.pending && this.pending.mode !== "rename" && this.pending.parent === node.path) {
        this.listEl.appendChild(this.editorRow(depth + 1, this.pending));
      }
      if (!this.collapsed.has(node.path)) {
        for (const c of node.children) this.renderNode(c, depth + 1);
      }
    } else {
      this.listEl.appendChild(this.fileRow(node, depth));
    }
  }

  private folderRow(node: Extract<TreeNode, { kind: "folder" }>, depth: number): HTMLElement {
    const row = document.createElement("div");
    row.className = "fb-folder";
    row.style.paddingLeft = `${12 + depth * 14}px`;
    const collapsed = this.collapsed.has(node.path);
    const tw = document.createElement("span");
    tw.className = "tw";
    tw.textContent = collapsed ? "▸" : "▾";
    const icon = document.createElement("span");
    icon.className = "ficon";
    const name = document.createElement("span");
    name.className = "fname";

    if (this.pending?.mode === "rename" && this.pending.path === node.path) {
      row.append(tw, icon, this.inlineInput(node.name, node.path, "folder"));
      return row;
    }
    name.textContent = node.name;
    row.append(tw, icon, name);
    row.addEventListener("click", () => {
      if (collapsed) this.collapsed.delete(node.path);
      else this.collapsed.add(node.path);
      this.render();
    });
    this.makeDraggable(row, node.path);
    this.makeDropTarget(row, node.path);
    row.addEventListener("contextmenu", (e) => this.openMenu(e, node.path, "folder"));
    return row;
  }

  private fileRow(node: Extract<TreeNode, { kind: "file" }>, depth: number): HTMLElement {
    const file = this.store.file(node.uri)!;
    const row = document.createElement("div");
    row.className =
      "file-item" + (file.lang === "kerml" ? " kerml" : "") + (node.uri === this.store.activeUri ? " active" : "");
    row.style.paddingLeft = `${14 + depth * 14}px`;
    const ico = document.createElement("span");
    ico.className = "fico";

    if (this.pending?.mode === "rename" && this.pending.path === node.path) {
      row.append(ico, this.inlineInput(node.name, node.path, "file"));
      return row;
    }

    const name = document.createElement("span");
    name.className = "fname";
    name.textContent = node.name;
    row.append(ico, name);

    const { errors, warnings } = this.store.counts(node.uri);
    if (errors + warnings > 0) {
      const badge = document.createElement("span");
      badge.className = "badge" + (errors > 0 ? " err" : "");
      badge.textContent = String(errors + warnings);
      row.appendChild(badge);
    }

    row.addEventListener("click", () => this.cbs.onSelect(node.uri));
    this.makeDraggable(row, node.path);
    row.addEventListener("contextmenu", (e) => this.openMenu(e, node.path, "file"));
    return row;
  }

  private openMenu(e: MouseEvent, path: string, kind: "file" | "folder"): void {
    e.preventDefault();
    e.stopPropagation();
    const parent = kind === "folder" ? path : "";
    const items =
      kind === "folder"
        ? [
            { label: "New File", action: () => this.startCreate("createFile", parent) },
            { label: "New Folder", action: () => this.startCreate("createFolder", parent) },
            { label: "Rename", action: () => this.startRename(path, kind) },
            { label: "Delete", action: () => this.cbs.onDelete(path) },
            { label: "Download", action: () => this.cbs.onDownload(path) },
          ]
        : [
            { label: "Rename", action: () => this.startRename(path, kind) },
            { label: "Delete", action: () => this.cbs.onDelete(path) },
            { label: "Download", action: () => this.cbs.onDownload(path) },
          ];
    showContextMenu(e.clientX, e.clientY, items);
  }

  private startCreate(mode: "createFile" | "createFolder", parent: string): void {
    this.collapsed.delete(parent);
    this.pending = { mode, parent };
    this.render();
  }

  private startRename(path: string, kind: "file" | "folder"): void {
    this.pending = { mode: "rename", path, kind };
    this.render();
  }

  /** Inline <input> for an in-progress rename. */
  private inlineInput(value: string, path: string, kind: "file" | "folder"): HTMLInputElement {
    const input = document.createElement("input");
    input.className = "fb-input";
    input.value = value;
    const siblings = this.siblingNames(this.parentOf(path), path);
    const commit = (): void => {
      const name = input.value.trim();
      const ok = kind === "file" ? isValidFileName(name, siblings) : isValidName(name, siblings);
      this.pending = null;
      if (ok && name !== value) this.cbs.onRename(path, name);
      else this.render();
    };
    this.wireInput(input, commit);
    return input;
  }

  /** Inline <input> for a new file/folder under `parent`. */
  private editorRow(depth: number, pending: Exclude<Pending, { mode: "rename" }>): HTMLElement {
    const isFile = pending.mode === "createFile";
    const row = document.createElement("div");
    row.className = isFile ? "file-item" : "fb-folder";
    row.style.paddingLeft = `${(isFile ? 14 : 12) + depth * 14}px`;
    const ico = document.createElement("span");
    ico.className = isFile ? "fico" : "ficon";
    const input = document.createElement("input");
    input.className = "fb-input";
    input.placeholder = isFile ? "name.sysml" : "folder";
    const siblings = this.siblingNames(pending.parent, null);
    const commit = (): void => {
      const name = input.value.trim();
      const ok = isFile ? isValidFileName(name, siblings) : isValidName(name, siblings);
      this.pending = null;
      if (!ok) {
        this.render();
        return;
      }
      const full = pending.parent ? `${pending.parent}/${name}` : name;
      if (isFile) this.cbs.onCreateFile(full);
      else this.cbs.onCreateFolder(full);
    };
    this.wireInput(input, commit);
    if (!isFile) {
      const tw = document.createElement("span");
      tw.className = "tw";
      tw.textContent = "▾";
      row.append(tw, ico, input);
    } else {
      row.append(ico, input);
    }
    queueMicrotask(() => input.focus());
    return row;
  }

  private wireInput(input: HTMLInputElement, commit: () => void): void {
    let done = false;
    const once = (): void => {
      if (done) return;
      done = true;
      commit();
    };
    input.addEventListener("keydown", (e) => {
      if (e.key === "Enter") once();
      else if (e.key === "Escape") {
        done = true;
        this.pending = null;
        this.render();
      }
    });
    input.addEventListener("blur", once);
    queueMicrotask(() => {
      input.focus();
      input.select();
    });
  }

  // ─────────────────────────── drag & drop ───────────────────────────

  private makeDraggable(row: HTMLElement, path: string): void {
    row.draggable = true;
    row.addEventListener("dragstart", (e) => {
      e.dataTransfer?.setData(DRAG_TYPE, path);
      e.dataTransfer!.effectAllowed = "move";
    });
  }

  private makeDropTarget(row: HTMLElement, destFolder: string): void {
    row.addEventListener("dragover", (e) => {
      const src = e.dataTransfer?.types.includes(DRAG_TYPE);
      if (src) {
        e.preventDefault();
        e.stopPropagation();
        row.classList.add("drop-into");
      }
    });
    row.addEventListener("dragleave", () => row.classList.remove("drop-into"));
    row.addEventListener("drop", (e) => {
      const src = e.dataTransfer?.getData(DRAG_TYPE);
      row.classList.remove("drop-into");
      if (!src) return;
      e.preventDefault();
      e.stopPropagation();
      if (canMove(src, destFolder)) this.cbs.onMove(src, destFolder);
    });
  }

  /** Root area: internal drops move to root; external file drops import. */
  private installRootDnd(): void {
    const el = this.rootEl;
    el.addEventListener("dragover", (e) => {
      e.preventDefault();
      if (!e.dataTransfer?.types.includes(DRAG_TYPE)) el.classList.add("drag-over");
    });
    el.addEventListener("dragleave", () => el.classList.remove("drag-over"));
    el.addEventListener("drop", (e) => {
      e.preventDefault();
      el.classList.remove("drag-over");
      const src = e.dataTransfer?.getData(DRAG_TYPE);
      if (src) {
        if (canMove(src, "")) this.cbs.onMove(src, "");
        return;
      }
      const files = Array.from(e.dataTransfer?.files ?? []).filter((f) => /\.(sysml|kerml)$/i.test(f.name));
      if (files.length > 0) this.cbs.onDropFiles(files);
    });
  }

  // ─────────────────────────── helpers ───────────────────────────

  private parentOf(path: string): string {
    return path.includes("/") ? path.slice(0, path.lastIndexOf("/")) : "";
  }

  /** Sibling names under `parent`, excluding `exclude` (a path being renamed). */
  private siblingNames(parent: string, exclude: string | null): string[] {
    const names = new Set<string>();
    const add = (p: string): void => {
      if (p === exclude) return;
      const rest = parent ? (p.startsWith(parent + "/") ? p.slice(parent.length + 1) : null) : p;
      if (rest === null) return;
      const top = rest.includes("/") ? rest.slice(0, rest.indexOf("/")) : rest;
      if (top) names.add(top);
    };
    for (const f of this.store.files) add(f.path);
    for (const d of this.store.folderPaths()) add(d);
    return [...names];
  }
}
