/**
 * Lifeline node — the SysML/UML sequence participant: a head box over a dashed
 * vertical stem.
 *
 * The two parts are one React Flow node rather than two, because they are one
 * element on the wire: a message's `source`/`target` name the participant, and
 * splitting the symbol would leave those ids pointing at a head that is not
 * where the message is drawn. `sequenceLayout` sizes the node to head-plus-
 * stem and hands the head's own height down as `headerH`, so this component
 * never has to measure itself to know where the stem begins.
 *
 * The head reuses `.smlml-node` (and the `.smlml-usage` rounding) rather than
 * restating a box: a participant is a usage box in the same vocabulary as
 * every other view, and `--fam` reaches it by ordinary inheritance from the
 * `fam-*` class this component stamps on its root — the same arrangement
 * `PackageNode` uses for its frame.
 *
 * The stem is dashed, matching the dashed chain `render_sequence_dot`
 * (`crates/smlml-cli/src/cmd/render.rs`) draws down each participant's column
 * (`style=dashed, arrowhead=none`).
 */

import React from "react";
import { Handle, Position, type NodeProps } from "@xyflow/react";
import { formOf } from "./form";

export function LifelineNode({ data, selected }: NodeProps) {
  const label = (data.label as string | undefined) ?? "?";
  const stereotype = data.stereotype as string | undefined;
  const headerH = data.headerH as number | undefined;
  // ARCH-4 semantic display fields: the wire label is creole-free; render
  // intent here, matching DefaultNode's idiom.
  const nameSynthesized = data.nameSynthesized as boolean | undefined;
  const isAbstract = data.isAbstract as boolean | undefined;
  const isInherited = data.isInherited as boolean | undefined;
  const shortName = data.shortName as string | undefined;
  // Server-classified family, authoritative and shared with the CLI painters;
  // "default" is the wire's own fallback for a node with no family tint.
  const family = (data.family as string | undefined) ?? "default";

  return (
    <div className={`smlml-lifeline fam-${family}`} data-form={formOf(data)}>
      <div
        className={`smlml-node smlml-usage smlml-lifeline-head${selected ? " selected" : ""}`}
        style={headerH !== undefined ? { height: headerH } : undefined}
      >
        <Handle type="target" position={Position.Top} style={{ opacity: 0 }} />
        {stereotype && <div className="smlml-node-metaclass">«{stereotype}»</div>}
        <div
          className="smlml-node-label"
          title={label}
          style={{
            ...(nameSynthesized ? { textDecoration: "line-through" } : undefined),
            ...(isAbstract ? { fontStyle: "italic" } : undefined),
          }}
        >
          {isInherited ? "^" : ""}
          {shortName ? `~<${shortName}> ` : ""}
          {label}
        </div>
        <Handle type="source" position={Position.Bottom} style={{ opacity: 0 }} />
      </div>
      <div className="smlml-lifeline-stem" />
    </div>
  );
}
