/** Font/display lifecycle shared by every React Flow diagram kind. */

import { useEffect, useState } from "react";
import { resetLayoutMeasurements } from "./layout";

function displaySignature(): string {
  const body = getComputedStyle(document.body);
  return [
    window.devicePixelRatio,
    window.visualViewport?.scale ?? 1,
    body.fontFamily,
    body.fontSize,
  ].join("|");
}

/**
 * Return an epoch that changes whenever cached text geometry must be rebuilt.
 * Font loading, theme/font variable changes, and DPI/page-scale changes all
 * invalidate the sizes ELK assigned to nodes.
 */
export function useFontMetricEpoch(): number {
  const [epoch, setEpoch] = useState(0);

  useEffect(() => {
    let disposed = false;
    let frame = 0;
    let signature = displaySignature();

    const invalidate = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => {
        if (disposed) return;
        resetLayoutMeasurements();
        signature = displaySignature();
        setEpoch(value => value + 1);
      });
    };
    const invalidateIfDisplayChanged = () => {
      const next = displaySignature();
      if (next !== signature) invalidate();
    };

    // A locally installed font may become usable after the first layout even
    // though this app downloads no webfonts. Re-run once the browser declares
    // its font set stable and whenever that set subsequently changes.
    const fonts = document.fonts;
    void fonts?.ready.then(invalidate);
    fonts?.addEventListener("loadingdone", invalidate);
    fonts?.addEventListener("loadingerror", invalidate);

    window.addEventListener("resize", invalidateIfDisplayChanged);
    window.visualViewport?.addEventListener("resize", invalidateIfDisplayChanged);

    // VS Code changes theme/font tokens by updating body attributes.
    const themeObserver = new MutationObserver(invalidate);
    themeObserver.observe(document.body, { attributes: true, attributeFilter: ["class", "style"] });

    return () => {
      disposed = true;
      cancelAnimationFrame(frame);
      fonts?.removeEventListener("loadingdone", invalidate);
      fonts?.removeEventListener("loadingerror", invalidate);
      window.removeEventListener("resize", invalidateIfDisplayChanged);
      window.visualViewport?.removeEventListener("resize", invalidateIfDisplayChanged);
      themeObserver.disconnect();
    };
  }, []);

  return epoch;
}
