/**
 * Composition root for editors/smlml-web.
 *
 * Boots the WASM LSP worker, opens the seed workspace, mounts the CodeMirror
 * editor and the reused React diagram app, and wires the dock panels — all
 * through one LSP gateway (the same path the VS Code extension ships in browser
 * mode).  Every module is constructed here with explicit dependencies; nothing
 * reaches for globals.
 */

import { LspClient } from "./lsp/lsp-client.ts";
import { createWorkerTransport } from "./lsp/worker-transport.ts";
import { WorkspaceStore, pathToUri } from "./workspace/workspace-store.ts";
import { SEED_FILES } from "./workspace/seed.ts";
import { attachPersistence, idbSnapshotStore, loadSnapshot } from "./workspace/persistence.ts";
import { unzip, zip, download, type ZipEntry } from "./workspace/zip.ts";
import { SmlEditor } from "./editor/editor.ts";
import { firstDefinitionTarget, type DefinitionResponse } from "./editor/definition.ts";
import {
  NavigationHistory,
  type NavigationLocation,
} from "./editor/navigation-history.ts";
import { ViewHost } from "./diagram/view-host.ts";
import { mountDiagramApp } from "./diagram/mount-app.tsx";
import { LogPanel } from "./panels/log.ts";
import { ProblemsPanel } from "./panels/problems.ts";
import { ValuesPanel } from "./panels/values.ts";
import { RunPanel } from "./panels/run-log.ts";
import { Dock } from "./ui/dock.ts";
import { FileTree } from "./ui/file-tree.ts";
import { Toolbar, pillStatus } from "./ui/toolbar.ts";
import { chooseMergeOrReplace, confirmDialog } from "./ui/modal.ts";
import { setupSplitters } from "./ui/splitters.ts";
import {
  coerceAstResponse,
  deliverExport,
  formatAstError,
  transportAstResponse,
  type AstErrorResponse,
  type ExportAstResponse,
  type ImportAstResponse,
} from "./ui/ast-menu.ts";
import { timed, timedSync, formatMs } from "./lsp/timing.ts";
import { AnalysisGate } from "./lsp/analysis-gate.ts";
import type { Diagnostic, Lang, SourceRange } from "./types.ts";
import type { WebviewToExtMsg } from "../../smlml-vscode/src/views/app/types";

const $ = (id: string) => document.getElementById(id)!;

async function boot(): Promise<void> {
  // ── Dock + Log (available before WASM so boot breadcrumbs are visible) ──
  const dock = new Dock($("dock"));
  const log = new LogPanel($("log-list"), $("log-count"));
  log.log("INFO", "starting smlml web viewer…");

  const store = new WorkspaceStore();

  // ── WASM worker + LSP client ──
  // `worker.js` sits next to index.html in dist/; resolve it against the page so
  // the worker's own relative import of wasm-pkg/ stays correct.
  const transport = createWorkerTransport("worker.js", log);
  const lsp = new LspClient(transport);

  let evalEnabled = true;
  let astOperation: "exporting" | "importing" | null = null;
  const navigation = new NavigationHistory();
  let applyNavigation = (_location: NavigationLocation): void => {};
  let navigateRange = (_location: NavigationLocation): void => {};
  let navigateTo = (_uri: string, _line: number, _character: number): void => {};
  let toolbar: Toolbar;
  const updateNavigationState = () =>
    toolbar.setNavigationState(navigation.canGoBack, navigation.canGoForward);
  const goBack = () => {
    const location = navigation.back();
    updateNavigationState();
    if (location) applyNavigation(location);
  };
  const goForward = () => {
    const location = navigation.forward();
    updateNavigationState();
    if (location) applyNavigation(location);
  };

  // Problems auto-opens once per 0→>0 transition, not on every publish that
  // happens to still have errors (or still have a collision) — otherwise
  // every keystroke on an already-broken file would keep yanking the dock
  // back open. Errors and collisions are tracked separately: a file can
  // acquire a collision warning with zero errors, and that transition is
  // the one the user specifically asked to be loud about.
  let prevErrorCount = 0;
  let prevCollisionCount = 0;

  toolbar = new Toolbar({
    onToggleFiles: () => $("workbench").classList.toggle("fb-collapsed"),
    onNavigateBack: goBack,
    onNavigateForward: goForward,
    onFormat: () => void formatActive(),
    onReparse: () => {
      const uri = store.activeUri;
      if (uri) timedSync(log, "EDITOR", "reparse", () => store.touch(uri));
    },
    onImportFiles: (files) => void importFiles(files),
    onExport: () => {
      timedSync(
        log,
        "WORKSPACE",
        "export workspace",
        () => {
          const entries = store.toEntries();
          download(zip(entries), "workspace.zip");
          return entries;
        },
        (e) => `${e.length} file(s)`
      );
    },
    onClearWorkspace: () => {
      void (async () => {
        if (store.files.length === 0) return;
        const ok = await confirmDialog(
          `Delete all ${store.files.length} file(s) from the workspace? "Reload example" restores the demo model.`,
          "Clear"
        );
        if (!ok) return;
        // `replaceAll([])` is the same full wipe zip-import already uses, so
        // every close/active event fires and the panes clear through the normal
        // route. The persistence layer writes the empty snapshot, which is what
        // makes the clear survive a refresh.
        timedSync(log, "WORKSPACE", "clear workspace", () => store.replaceAll([]));
      })();
    },
    onLoadExamples: () => {
      const files = timedSync(
        log,
        "WORKSPACE",
        "load examples",
        () => {
          store.replaceAll(SEED_FILES);
          return store.files;
        },
        (f) => `${f.length} file(s)`
      );
      void analysis.await(files.length);
    },
    onExportAst: () => {
      void (async () => {
        const uri = store.activeUri;
        if (!uri) {
          log.log("AST", "Export AST: no file is active.", "err");
          return;
        }
        // The toolbar button is disabled under the same condition; this is a
        // second gate for callers that reach the handler some other way (the
        // menu item was mid-animation, a future keybinding, …).
        const { errors } = store.totalCounts();
        if (errors > 0) {
          log.log("AST", `Export AST: blocked — ${errors} error${errors === 1 ? "" : "s"} in the workspace.`, "err");
          return;
        }
        astOperation = "exporting";
        toolbar.setStatus("analyzing", "exporting AST…");
        try {
          // Both transport failure shapes reach the log panel: a rejected
          // request (`transportAstResponse`) and a non-response — an older
          // server answers an unknown request with `null`, and `if (!res.ok)` on
          // `null` was an unhandled TypeError inside this floating async IIFE
          // that the user never saw.
          const res = await timed(log, "AST", "export AST",
            async (): Promise<ExportAstResponse | AstErrorResponse> => {
              try {
                return coerceAstResponse<ExportAstResponse>(
                  "smlml/exportAst",
                  await lsp.sendRequest("smlml/exportAst", { uri })
                );
              } catch (err) {
                return transportAstResponse("smlml/exportAst", err);
              }
            },
            (r) => (r.ok ? `${r.contributingFiles.length} file(s)` : "failed")
          );
          if (!res.ok) {
            log.log("AST", formatAstError(res), "err");
            return;
          }
          deliverExport(res);
        } finally {
          astOperation = null;
          updateStatus();
        }
      })();
    },
    onImportAstFile: (file: File) => {
      void (async () => {
        astOperation = "importing";
        toolbar.setStatus("analyzing", "importing AST…");
        try {
          const json = await file.text();
          // See `onExportAst` above for why the raw response is funnelled.
          const res = await timed(log, "AST", "import AST",
            async (): Promise<ImportAstResponse | AstErrorResponse> => {
              try {
                return coerceAstResponse<ImportAstResponse>(
                  "smlml/importAst",
                  await lsp.sendRequest("smlml/importAst", { json })
                );
              } catch (err) {
                return transportAstResponse("smlml/importAst", err);
              }
            },
            (r) => (r.ok ? `${r.files.length} file(s)` : "failed")
          );
          if (!res.ok) {
            log.log("AST", formatAstError(res), "err");
            return;
          }

          if (res.skipped.length > 0) {
            const proceed = await confirmDialog(
              `Only ${res.files.length} root(s) could be converted. The following root(s) will be omitted:\n${res.skipped.join("\n")}\n\nImport the available files anyway?`,
              "Import Partial"
            );
            if (!proceed) {
              log.log("AST", `partial import cancelled — skipped roots: ${res.skipped.join(", ")}`, "warn");
              return;
            }
          }

          // `store.addFile` treats a same-path add as an EDIT, and the server's
          // `-1`, `-2`, … suffixing is intra-import only (it knows nothing about
          // this workspace), so re-importing a revised JSON lands on the same
          // names and would silently destroy the user's edits. Ask first —
          // `chooseMergeOrReplace` on the workspace-zip path is the precedent.
          const clashes = res.files
            .filter((f) => store.file(pathToUri(f.name)) !== undefined)
            .map((f) => f.name);
          if (clashes.length > 0) {
            const ok = await confirmDialog(
              `${clashes.length} file(s) already exist and will be overwritten:\n${clashes.join("\n")}`,
              "Overwrite"
            );
            if (!ok) {
              log.log("AST", `import AST cancelled — would overwrite: ${clashes.join(", ")}`, "warn");
              return;
            }
          }

          let firstUri: string | null = null;
          for (const f of res.files) {
            const written = store.addFile(f.name, f.text);
            if (firstUri === null) firstUri = written.uri;
          }
          if (firstUri) store.setActive(firstUri);
          if (res.skipped.length > 0) {
            log.log("AST", `skipped root(s): ${res.skipped.join(", ")}`, "warn");
          }
          if (res.incomplete.length > 0) {
            log.log("AST", `incomplete file(s): ${res.incomplete.join(", ")}`, "warn");
          }
        } finally {
          astOperation = null;
          updateStatus();
        }
      })();
    },
    onOpenProblems: () => dock.show("problems"),
    onToggleEval: (enabled) => {
      evalEnabled = enabled;
      log.log("WORKSPACE", `eval ${enabled ? "enabled" : "disabled"}`);
      lsp.notify("smlml/setEval", { enabled });
      if (!enabled) {
        const f = store.activeFile;
        if (f && f.uri === store.activeUri) editor.setCalcResults([]);
        values.clear();
        toolbar.setEvalCount(0);
      } else {
        const uri = store.activeUri;
        if (uri) scheduleAnalyze();
      }
    },
  });

  // Held here so `updateStatus` can refuse to overwrite "analyzing".
  const analysis = new AnalysisGate({
    lsp,
    onState: (state, elapsedMs, fileCount, ok) => {
      if (state === "analyzing") {
        if (!astOperation) toolbar.setStatus("analyzing", `analysing ${fileCount} file(s)…`);
      } else {
        if (ok) {
          log.log("LSP", `parsed ${fileCount} file(s) in ${formatMs(elapsedMs)}`, "op");
        } else {
          log.log(
            "LSP",
            `parse barrier timed out after ${formatMs(elapsedMs)} — the server may still be working`,
            "warn"
          );
        }
        updateStatus();
      }
    },
  });

  // ── Editor ──
  const editor = new SmlEditor($("editor"), {
    onChange: (text) => {
      const uri = store.activeUri;
      if (uri) store.setText(uri, text);
    },
    onSelection: (line, character) => {
      if (store.activeUri) {
        navigation.observe({
          uri: store.activeUri,
          range: { startLine: line, startCol: character, endLine: line, endCol: character },
        });
        viewHost.onCursor(store.activeUri, line, character);
      }
    },
    onHover: async (line, character) => {
      const uri = store.activeUri;
      if (!uri) return null;
      try {
        const res = await lsp.sendRequest<{ contents?: { value?: string } | string } | null>(
          "textDocument/hover",
          { textDocument: { uri }, position: { line, character } }
        );
        if (!res?.contents) return null;
        return typeof res.contents === "string" ? res.contents : res.contents.value ?? null;
      } catch {
        return null;
      }
    },
    onDefinition: async (line, character) => {
      const uri = store.activeUri;
      if (!uri) return;
      try {
        const response = await lsp.sendRequest<DefinitionResponse>(
          "textDocument/definition",
          { textDocument: { uri }, position: { line, character } },
        );
        const target = firstDefinitionTarget(response);
        if (!target) return;
        if (!store.file(target.uri)) {
          log.log("LSP", `definition is outside this workspace: ${target.uri}`, "warn");
          return;
        }
        navigateRange({
          uri: target.uri,
          range: {
            startLine: target.range.start.line,
            startCol: target.range.start.character,
            endLine: target.range.end.line,
            endCol: target.range.end.character,
          },
        });
      } catch (error) {
        log.log("LSP", `go to definition failed: ${String(error)}`, "warn");
      }
    },
    onNavigateBack: goBack,
    onNavigateForward: goForward,
  });

  applyNavigation = (location) => {
    if (!store.file(location.uri)) return;
    if (location.uri !== store.activeUri) store.setActive(location.uri);
    editor.revealRange(location.range);
  };
  navigateRange = (location: NavigationLocation) => {
    navigation.navigate(location);
    updateNavigationState();
    applyNavigation(location);
  };
  navigateTo = (uri, line, character) => navigateRange({
    uri,
    range: { startLine: line, startCol: character, endLine: line, endCol: character + 1 },
  });

  // ── Diagram (reused React app) + host orchestration ──
  const runPanel = new RunPanel($("pane-run"));
  const editorBridge = {
    navigate: (uri: string, range: SourceRange) => {
      if (uri && store.file(uri)) navigateRange({ uri, range });
    },
  };
  const viewHost = new ViewHost({
    lsp,
    editor: editorBridge,
    post: (msg) => mounted.post(msg),
    onSimResult: (currentState, traceText) => {
      dock.setTabVisible("run", true);
      runPanel.add(currentState, traceText);
    },
    log: (tag, msg) => log.log(tag, msg, tag === "VIEW" ? "op" : "info"),
    // The worker's snippet-hover lookup, so legend rows can show the same
    // documentation the editor shows for the corresponding keyword.
    docs: transport,
  });
  const mounted = mountDiagramApp($("diagram-root"));
  mounted.subscribe((msg: WebviewToExtMsg) => void viewHost.handleAppMessage(msg));

  // ── Dock panels ──
  const problems = new ProblemsPanel($("pane-problems"), { onNavigate: navigateTo });
  const values = new ValuesPanel($("pane-values"), $("count-values"), lsp, { onNavigate: navigateTo });

  // ── File tree ──
  const fileTree = new FileTree(
    $("fb-list"),
    $("filebrowser"),
    $("fb-new-file"),
    $("fb-new-folder"),
    store,
    {
      onSelect: (uri) => navigateRange(navigation.locationFor(uri)),
      onCreateFile: (path) => store.createFile(path),
      onCreateFolder: (path) => store.createFolder(path),
      onRename: (oldPath, newName) => store.renameItem(oldPath, newName),
      onMove: (srcPath, destFolder) => store.moveItem(srcPath, destFolder),
      onDelete: (path) => void deleteItem(path),
      onDownload: (path) => downloadItem(path),
      onDropFiles: (files) => void importFiles(files),
    }
  );

  setupSplitters();

  // ─────────────────────────── reactive wiring ───────────────────────────

  const pullDiagnostics = async (uri: string): Promise<void> => {
    const report = await lsp.sendRequest<{ kind?: string; items?: Diagnostic[] }>(
      "textDocument/diagnostic",
      { textDocument: { uri } },
    );
    store.setDiagnostics(uri, report?.items ?? []);
  };
  const pullAllDiagnostics = async (): Promise<void> => {
    await Promise.all(store.files.map(file => pullDiagnostics(file.uri)));
  };
  lsp.onNotification("window/logMessage", (params) => {
    const p = params as { message?: string };
    if (p?.message) log.log("LSP", p.message);
  });

  let analyzeTimer: ReturnType<typeof setTimeout> | null = null;
  const scheduleAnalyze = () => {
    if (analyzeTimer) clearTimeout(analyzeTimer);
    analyzeTimer = setTimeout(() => {
      void timed(log, "EDITOR", "analyze active file", () => analyzeActive()).catch(() => {
        /* logged by `timed` */
      });
    }, 300);
  };

  // Pull cross-file diagnostics after typing settles. This keeps diagnostics on
  // one protocol path and avoids recomputing every file inside `didChange`.
  let refreshTimer: ReturnType<typeof setTimeout> | null = null;
  const scheduleRefresh = () => {
    if (refreshTimer) clearTimeout(refreshTimer);
    refreshTimer = setTimeout(() => void pullAllDiagnostics(), 1000);
  };

  store.onEvent((e) => {
    switch (e.type) {
      case "opened":
        lsp.notify("textDocument/didOpen", {
          textDocument: { uri: e.file.uri, languageId: e.file.lang, version: e.file.version, text: e.file.text },
        });
        void pullDiagnostics(e.file.uri);
        scheduleRefresh();
        fileTree.render();
        break;
      case "changed":
        lsp.notify("textDocument/didChange", {
          textDocument: { uri: e.file.uri, version: e.file.version },
          contentChanges: [{ text: e.file.text }],
        });
        if (e.file.uri === store.activeUri) scheduleAnalyze();
        void pullDiagnostics(e.file.uri);
        // An edit can shift other open files' cross-file resolution/rollups.
        scheduleRefresh();
        break;
      case "closed":
        navigation.removeUri(e.uri);
        updateNavigationState();
        lsp.notify("textDocument/didClose", { textDocument: { uri: e.uri } });
        fileTree.render();
        break;
      case "active": {
        const f = store.activeFile;
        $("active-file").textContent = f ? f.path : "—";
        $("active-lang").textContent = f ? `UTF-8 · ${f.lang === "kerml" ? "KerML" : "SysML"}` : "UTF-8";
        if (f) {
          editor.setDoc(f.text, f.lang);
          editor.setDiagnostics(store.diagnostics(f.uri));
          viewHost.setActiveUri(f.uri);
          scheduleAnalyze();
        } else {
          // The store can empty — `removeFile` resolves `setActive` to null, and
          // so does `replaceAll([])`. This branch used not to exist, so the
          // editor and the diagram kept painting the last file's content over an
          // empty workspace. Fixed here rather than in the clear path, so every
          // route that empties the store benefits.
          editor.setDoc("", "sysml");
          editor.setDiagnostics([]);
          editor.setCalcResults([]);
          values.clear();
          toolbar.setEvalCount(0);
          // `RunPanel` has no `clear()`; `reset()` is its equivalent and is
          // already what the constructor calls.
          runPanel.reset();
          dock.setTabVisible("run", false);
          // `viewHost.clear()`, not a hand-rolled empty `loadView` post: only the
          // host can invalidate a `buildView` that is already in flight, and one
          // that lands afterwards would otherwise repaint the deleted file.
          viewHost.clear();
          renderProblems();
          updateStatus();
        }
        fileTree.render();
        break;
      }
      case "diagnostics":
        if (e.uri === store.activeUri) editor.setDiagnostics(store.diagnostics(e.uri));
        renderProblems();
        fileTree.render();
        updateStatus();
        break;
      case "folders":
        fileTree.render();
        break;
    }
  });

  function renderProblems(): void {
    problems.render(store.files.map((f) => ({ uri: f.uri, path: f.path, diagnostics: store.diagnostics(f.uri) })));
    dock.setCount("problems", store.totalCounts().errors + store.totalCounts().warnings);
  }

  function updateStatus(): void {
    // While a batch is in flight the counts are incomplete by definition —
    // reporting them would put the pill on "ok — no problems" before analysis
    // has finished, which is the false green TODO 8 describes.
    if (analysis.analyzing || astOperation) return;
    const { errors, warnings } = store.totalCounts();
    const { kind, text } = pillStatus(errors, warnings);
    toolbar.setStatus(kind, text);

    const gateTooltip = `${errors} error${errors === 1 ? "" : "s"} — fix before rendering (see Problems)`;
    toolbar.setExportGate(errors > 0, `${errors} error${errors === 1 ? "" : "s"} — fix before export (see Problems)`);
    setRenderBlocked(errors > 0, gateTooltip);

    if (prevErrorCount === 0 && errors > 0) dock.show("problems");
    // The reverse transition: errors just cleared without the active file
    // itself changing (e.g. a different file's edit resolved a cross-file
    // error). `analyzeActive`'s own refresh is gated on the *active* file's
    // edits, so nothing else would repaint the diagram the overlay was
    // hiding — it would just vanish, exposing whatever was rendered before
    // the block started.
    if (prevErrorCount > 0 && errors === 0) void viewHost.refresh();
    prevErrorCount = errors;

    const collisions = store.totalCollisions();
    if (prevCollisionCount === 0 && collisions > 0) dock.show("problems");
    prevCollisionCount = collisions;
  }

  /**
   * Block the diagram pane behind an overlay while the active file has
   * errors: `buildView` can still return a graph over a partially-resolved
   * model, and showing it as if it were trustworthy is worse than showing
   * nothing. The overlay's own text carries the tooltip, since it is not a
   * hover target the way a disabled button is.
   */
  function setRenderBlocked(blocked: boolean, tooltip: string): void {
    const el = $("render-block");
    el.hidden = !blocked;
    el.title = blocked ? tooltip : "";
    $("render-block-msg").textContent = blocked ? tooltip : "";
  }

  async function analyzeActive(): Promise<void> {
    const f = store.activeFile;
    if (!f) return;
    // Semantic tokens for the active file.
    try {
      const res = await lsp.sendRequest<{ data: number[] }>("textDocument/semanticTokens/full", {
        textDocument: { uri: f.uri },
      });
      if (res?.data && f.uri === store.activeUri) editor.setSemanticTokens(res.data);
    } catch {
      /* tokens are best-effort */
    }
    // Diagram + values (skipped when eval is disabled).
    // The version goes with the request: an expansion set names element UUIDs
    // from one parse, and every keystroke produces a new one. The refresh
    // itself is skipped while any file has errors — the overlay `updateStatus`
    // raised already tells the reader why, and a stale-but-valid diagram
    // behind it beats replacing it with a build over unresolved state.
    if (store.totalCounts().errors === 0) await viewHost.refresh(f.uri, undefined, f.version);
    if (evalEnabled) {
      const rows = await values.refresh(f.uri);
      // Re-check after the async gap: user may have disabled eval while refresh was in flight.
      if (!evalEnabled) {
        values.clear();
        editor.setCalcResults([]);
        toolbar.setEvalCount(0);
      } else if (f.uri === store.activeUri) {
        editor.setCalcResults(
          rows.map((r) => ({ line: r.line, value: r.value, unit: r.unit, lock: r.lock }))
        );
        toolbar.setEvalCount(rows.length);
      }
    }
  }

  async function formatActive(): Promise<void> {
    const f = store.activeFile;
    if (!f) return;
    let edits: Array<{ range: { start: Pos; end: Pos }; newText: string }> | undefined;
    try {
      edits = await timed(
        log,
        "EDITOR",
        "format document",
        () =>
          lsp.sendRequest<Array<{ range: { start: Pos; end: Pos }; newText: string }>>(
            "textDocument/formatting",
            { textDocument: { uri: f.uri }, options: { tabSize: 4, insertSpaces: true } }
          ),
        (e) => `${e?.length ?? 0} edit(s)`
      );
    } catch {
      return; /* `timed` already logged the failure with its duration. */
    }
    if (!edits?.length) return;
    try {
      const formatted = applyTextEdits(f.text, edits);
      store.setText(f.uri, formatted);
      editor.setDoc(formatted, f.lang);
    } catch (err) {
      log.log("EDITOR", `format document: applying edits failed: ${String(err)}`, "warn");
    }
  }

  async function deleteItem(path: string): Promise<void> {
    const isFolder = !store.file(pathToUri(path));
    const hasChildren =
      isFolder &&
      (store.files.some((f) => f.path.startsWith(path + "/")) ||
        store.folderPaths().some((d) => d.startsWith(path + "/")));
    if (hasChildren && !(await confirmDialog(`Delete folder "${path}" and its contents?`))) return;
    store.deleteItem(path);
    log.log("WORKSPACE", `delete ${path}`);
  }

  function downloadItem(path: string): void {
    const f = store.file(pathToUri(path));
    if (f) {
      download(new Blob([f.text], { type: "text/plain" }), path.split("/").pop() ?? path);
      return;
    }
    const subFiles = store.toEntries().filter((e) => e.path === path || e.path.startsWith(path + "/"));
    const subFolders = store.folderPaths().filter((d) => d === path || d.startsWith(path + "/"));
    download(zip(subFiles, subFolders), `${path.split("/").pop() || "folder"}.zip`);
  }

  async function importFiles(files: File[]): Promise<void> {
    const entries: ZipEntry[] = [];
    const folders: string[] = [];
    let hasZip = false;
    for (const file of files) {
      if (/\.zip$/i.test(file.name)) {
        hasZip = true;
        log.log("WORKSPACE", `import zip ${file.name}`);
        const r = await unzip(await file.arrayBuffer());
        entries.push(...r.files);
        folders.push(...r.folders);
      } else if (/\.(sysml|kerml)$/i.test(file.name)) {
        const path = (file as File & { webkitRelativePath?: string }).webkitRelativePath || file.name;
        entries.push({ path, text: await file.text() });
      }
    }
    if (entries.length === 0 && folders.length === 0) return;
    if (hasZip) {
      const choice = await chooseMergeOrReplace();
      if (choice === null) return;
      if (choice === "replace") {
        store.replaceAll(entries, folders);
        return;
      }
    }
    for (const e of entries) store.addFile(e.path, e.text);
    for (const d of folders) store.createFolder(d);
  }

  // ─────────────────────────── go ───────────────────────────

  try {
    const wasmStart = performance.now();
    await transport.ready;
    log.log("WASM", `WASM ready in ${(performance.now() - wasmStart).toFixed(0)} ms`);
    const initStart = performance.now();
    log.log("LSP", "initialize (loading stdlib…)");
    await lsp.sendRequest("initialize", { capabilities: {}, processId: null, rootUri: "file:///" });
    log.log("LSP", `initialize complete (stdlib parsed) in ${(performance.now() - initStart).toFixed(0)} ms`);
    lsp.notify("initialized", {});

    // Persistence: a clear button without it is a button whose effect vanishes
    // on refresh. IndexedDB needs no permission prompt (`navigator.storage
    // .persist()` does, but it only asks for eviction resistance, which this
    // does not need). If storage is blocked — private-browsing modes, blocked
    // site data — fall back to the old behaviour of seeding every load, and say
    // so once so it is diagnosable rather than mysterious.
    const snapshots = idbSnapshotStore();
    // Blocked storage and a malformed record both come back as `null` here, with
    // one warning and the bad record discarded — never as a throw, because a
    // throw would land in the boot catch below and report "WASM failed" on every
    // subsequent reload, with persistence never attached and so no way to
    // overwrite the offending record short of devtools.
    const restored = await loadSnapshot(snapshots, {
      onError: (err) =>
        log.log("WORKSPACE", `workspace persistence unavailable — seeding examples: ${String(err)}`, "warn"),
    });

    const files = timedSync(
      log,
      "WORKSPACE",
      restored ? "restore workspace" : "load workspace",
      () => {
        if (restored) {
          try {
            store.replaceAll(restored.files, restored.folders);
            const activeUri = restored.activePath ? pathToUri(restored.activePath) : null;
            if (activeUri && store.file(activeUri)) store.setActive(activeUri);
            return store.files;
          } catch (err) {
            // Belt and braces: `loadSnapshot` already rejects records that would
            // do this, so reaching here means a shape nobody anticipated. Seed
            // anyway — a boot that shows the examples beats a boot that fails.
            log.log("WORKSPACE", `stored workspace could not be applied — seeding examples: ${String(err)}`, "warn");
          }
        }
        store.replaceAll(SEED_FILES); // fires didOpen for each; sets first active
        return store.files;
      },
      (f) => `${f.length} file(s)`
    );

    // Attach AFTER the initial load so the restore itself does not immediately
    // rewrite what it just read.
    attachPersistence(store, snapshots, {
      onError: (err) =>
        log.log("WORKSPACE", `workspace could not be saved: ${String(err)}`, "warn"),
    });

    renderProblems();
    // Barrier, not a guess: the worker is FIFO, so this request cannot answer
    // until every didOpen and diagnostic pull above has been processed. `updateStatus`
    // runs from the gate's `settled` callback, not here.
    void analysis.await(files.length);

    // Headless smoke hook (scripts/smoke.mjs): expose the live LSP so the
    // harness can exercise requests directly.  Gated on a query flag so it never
    // leaks into normal use.
    if (location.search.includes("smoke")) {
      (window as unknown as { __smlml?: unknown }).__smlml = { lsp, store };
    }
  } catch (err) {
    toolbar.setStatus("error", "WASM failed");
    log.log("WASM", `boot failed: ${String(err)}`, "err");
  }
}

interface Pos {
  line: number;
  character: number;
}

/** Apply LSP TextEdits to `text` (sorted descending so offsets stay valid). */
function applyTextEdits(text: string, edits: Array<{ range: { start: Pos; end: Pos }; newText: string }>): string {
  const lineStarts = [0];
  for (let i = 0; i < text.length; i++) if (text[i] === "\n") lineStarts.push(i + 1);
  const offset = (p: Pos) => Math.min((lineStarts[p.line] ?? text.length) + p.character, text.length);
  const sorted = [...edits].sort((a, b) => offset(b.range.start) - offset(a.range.start));
  let out = text;
  for (const e of sorted) {
    out = out.slice(0, offset(e.range.start)) + e.newText + out.slice(offset(e.range.end));
  }
  return out;
}

boot().catch((err) => {
  console.error("[smlml-web] fatal boot error:", err);
});
