/**
 * Routed edge — uses the selected live React Flow geometry whenever endpoint
 * nodes are mounted, with ELK's route retained as an initialization fallback.
 *
 * Keeping one renderer active at rest and during movement is important: using
 * ELK's baked sections initially and switching to endpoint-derived geometry
 * after a drag made all three routing modes snap to a different shape.
 */

import React from "react";
import { BaseEdge, getStraightPath, useInternalNode, type EdgeProps } from "@xyflow/react";
import { computeFloatingPath, hasDrifted, insetPolylineEnds, reserveMarkerRuns, type LayoutPoint } from "./edgeGeometry";
import { EdgeLabel } from "./EdgeLabel";
import { MARKER_RUN_REACH, markerShaftInset } from "./EdgeMarkers";

interface Point { x: number; y: number }
interface Section { startPoint: Point; bendPoints?: Point[]; endPoint: Point }

/**
 * Every toolbar mode uses the same live renderer before and after a drag.
 * Mixing ELK sections at rest with live geometry after movement made every
 * mode visibly snap between two different routing implementations.
 */
export function usesLiveRoute(_routing: string | undefined, _dragged: boolean): boolean {
  return true;
}

/** Cumulative arc length at each vertex of a polyline, `dists[0] === 0`. */
function arcLengths(points: Point[]): number[] {
  const dists = [0];
  for (let i = 1; i < points.length; i++) {
    dists.push(dists[i - 1] + Math.hypot(points[i].x - points[i - 1].x, points[i].y - points[i - 1].y));
  }
  return dists;
}

/** Point at half the polyline's total arc length — the true visual midpoint,
 *  not just a vertex (which, for the common one-section/zero-bend route,
 *  would be the target endpoint itself). Exported for direct unit testing. */
export function midpointByArcLength(points: Point[]): Point {
  const dists = arcLengths(points);
  const total = dists[dists.length - 1];
  const half = total / 2;
  for (let i = 1; i < points.length; i++) {
    if (dists[i] >= half) {
      const segLen = dists[i] - dists[i - 1];
      const t = segLen === 0 ? 0 : (half - dists[i - 1]) / segLen;
      const a = points[i - 1], b = points[i];
      return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
    }
  }
  return points[points.length - 1];
}

/**
 * Where to draw an edge's label: the position ELK reserved room for, or the
 * route's own midpoint.
 *
 * ELK was handed each label's measured size and answered with a placement that
 * accounts for every other box on the canvas; `fallback` (the arc-length
 * midpoint) knows only about this one edge, so it is strictly the weaker
 * answer — but it is the only valid one once a drag has invalidated the baked
 * geometry, for the same reason the route itself falls back to floating there.
 * Exported for direct unit testing: the component around it needs React Flow's
 * provider context, and this choice does not.
 */
export function labelAnchor(
  dragged: boolean,
  placed: Point | undefined,
  fallback: Point
): Point {
  return !dragged && placed ? placed : fallback;
}

export function RoutedEdge(props: EdgeProps) {
  const { id, source, target, sourceX, sourceY, targetX, targetY, markerStart, markerEnd, style, label, data } = props;
  const sections = (data?.sections as Section[] | undefined) ?? [];

  // A route baked at layout time has no dependency on live node position —
  // unlike `FloatingEdge` (which recomputes the border intersection from
  // `useInternalNode` on every render), so dragging a node used to leave its
  // routed edges anchored to stale, pre-drag geometry. Detect the drag by
  // comparing each endpoint's live absolute position against the position
  // `layoutViewModel` baked into the edge's `data` at layout time, and fall
  // back to the same live floating path `FloatingEdge` draws whenever either
  // endpoint has moved.
  const sourceNode = useInternalNode(source);
  const targetNode = useInternalNode(target);
  const dragged =
    hasDrifted(sourceNode, data?.sourceLayoutPos as LayoutPoint | undefined) ||
    hasDrifted(targetNode, data?.targetLayoutPos as LayoutPoint | undefined);
  const routing = data?.routing as string | undefined;
  const liveRoute = usesLiveRoute(routing, dragged);

  let path: string;
  let carrierPath: string;
  let labelX: number;
  let labelY: number;
  if (liveRoute && sourceNode && targetNode) {
    [carrierPath] = computeFloatingPath(sourceNode, targetNode, routing);
    [path, labelX, labelY] = computeFloatingPath(
      sourceNode,
      targetNode,
      routing,
      markerShaftInset(markerStart, true),
      markerShaftInset(markerEnd, false),
    );
  } else {
    const routed: Point[] = sections.flatMap(s => [
      s.startPoint, ...(s.bendPoints ?? []), s.endPoint,
    ]);
    // Give each end decoration a straight run to sit on — only the ends that
    // actually carry one, since an undecorated end may meet its border at a
    // corner with nothing lost. See `reserveMarkerRuns`.
    const points = reserveMarkerRuns(
      routed,
      markerStart ? MARKER_RUN_REACH : 0,
      markerEnd ? MARKER_RUN_REACH : 0
    );
    if (points.length >= 2) {
      carrierPath = points.map((p, i) => `${i === 0 ? "M" : "L"}${p.x},${p.y}`).join(" ");
      const shaft = insetPolylineEnds(
        points,
        markerShaftInset(markerStart, true),
        markerShaftInset(markerEnd, false),
      );
      path = shaft.map((p, i) => `${i === 0 ? "M" : "L"}${p.x},${p.y}`).join(" ");
      const mid = midpointByArcLength(shaft);
      labelX = mid.x;
      labelY = mid.y;
    } else {
      [carrierPath] = getStraightPath({ sourceX, sourceY, targetX, targetY });
      path = carrierPath;
      [, labelX, labelY] = getStraightPath({ sourceX, sourceY, targetX, targetY });
    }
  }

  const anchor = labelAnchor(
    liveRoute,
    data?.labelPos as Point | undefined,
    { x: labelX, y: labelY }
  );
  labelX = anchor.x;
  labelY = anchor.y;

  return (
    <>
      <BaseEdge id={id} path={path} style={style} />
      {(markerStart || markerEnd) && (
        <path
          d={carrierPath}
          fill="none"
          stroke="transparent"
          markerStart={markerStart}
          markerEnd={markerEnd}
          pointerEvents="none"
        />
      )}
      <EdgeLabel edgeId={id} label={label} x={labelX} y={labelY} />
    </>
  );
}
