/**
 * Sequence view — OMG VSequence conformant.
 *
 * The one view that does not go through ELK. `smlml_viewgen`'s `VSequence`
 * emits participants and messages and nothing else, and the message order it
 * emits is contractual — see `sequenceLayout` for why no layout engine may be
 * asked to re-derive it, and `render_sequence_dot`
 * (`crates/smlml-cli/src/cmd/render.rs`) for the painter this one is
 * transliterated from.
 *
 * Consequently this component has no async layout, no layout-failure channel
 * (there is no engine to fail) and no routing choice: a message is a straight
 * segment at its row, and the `routing` prop the panel passes every view is
 * accepted and ignored here rather than being silently reinterpreted.
 *
 * Everything else is the shared apparatus every other flow view uses: the same
 * node registry, the same edge components, the same cursor-highlight /
 * search-hit / edge-selection decoration passes.
 */

import React, { useEffect, useState } from "react";
import {
  ReactFlow,
  useNodesState,
  useEdgesState,
  Background,
  BackgroundVariant,
  Controls,
  type Node,
  type Edge,
} from "@xyflow/react";
import type { ViewModel, SourceRange } from "./types";
import type { EdgeRouting } from "./Diagram";
import { layoutSequence } from "./sequenceLayout";
import { EdgeMarkers } from "./EdgeMarkers";
import { NavigateContext } from "./NavigateContext";
import { NODE_TYPES } from "./nodes";
import { NO_MATCHES, type SearchMatches } from "./search";
import { useEdgeSelection } from "./edge-selection";
import { EDGE_TYPES } from "./FloatingEdge";
import { FitAfterLayout, SyncViewportTransition } from "./ViewportTransitions";
import { useFontMetricEpoch } from "./font-metrics-lifecycle";

interface Props {
  model: ViewModel;
  /** Accepted for prop parity with the ELK views; a message has one route. */
  routing: EdgeRouting;
  uri: string;
  onNavigate: (uri: string, range: SourceRange) => void;
  /** Node id to scroll into view and pulse-highlight. */
  highlightNodeId?: string;
  /** Free-text search hits to mark and to frame. */
  matches?: SearchMatches;
}

export function SequenceFlowView({
  model,
  uri,
  onNavigate,
  highlightNodeId,
  matches,
}: Props) {
  const fontMetricEpoch = useFontMetricEpoch();
  const [nodes, setNodes, onNodesChange] = useNodesState<Node>([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState<Edge>([]);
  const [layoutTick, setLayoutTick] = useState(0);
  const edgeSelection = useEdgeSelection();

  useEffect(() => {
    const { nodes: n, edges: e } = layoutSequence(model);
    setNodes(n);
    setEdges(e);
    setLayoutTick(t => t + 1);
  }, [model, fontMetricEpoch, setNodes, setEdges]);

  // Cursor highlight and search hits both decorate nodes, applied in one pass.
  const hits = matches ?? NO_MATCHES;
  const matchedNodes = nodes.map(n => {
    const isCursor = n.id === highlightNodeId;
    const isHit = hits.nodes.has(n.id);
    if (!isCursor && !isHit) return n;
    return {
      ...n,
      className: [n.className, isCursor && "smlml-node-highlight", isHit && "smlml-node-match"]
        .filter(Boolean)
        .join(" "),
      // Re-wrapping `data` is what makes the decoration reach the component:
      // React Flow only re-renders a node whose `data` identity changed.
      data: { ...n.data },
    };
  });

  const matchedEdges = edges.map(e =>
    hits.edges.has(e.id)
      ? { ...e, className: [e.className, "smlml-edge-match"].filter(Boolean).join(" ") }
      : e
  );

  const { decorate, onEdgeClick, onPaneClick } = edgeSelection;
  const { nodes: paintedNodes, edges: paintedEdges } = decorate(matchedNodes, matchedEdges);

  const handleNodeClick = (_: React.MouseEvent, node: Node) => {
    const range = node.data?.range as SourceRange | undefined;
    if (range) onNavigate((node.data?.uri as string | undefined) ?? uri, range);
  };

  return (
    <NavigateContext.Provider value={{ navigate: onNavigate, uri }}>
      <ReactFlow
        nodes={paintedNodes}
        edges={paintedEdges}
        nodeTypes={NODE_TYPES}
        edgeTypes={EDGE_TYPES}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onNodeClick={handleNodeClick}
        onEdgeClick={onEdgeClick}
        onPaneClick={onPaneClick}
        fitView
        minZoom={0.1}
        maxZoom={4}
        nodesDraggable={false}
        nodesConnectable={false}
      >
        <EdgeMarkers />
        <FitAfterLayout trigger={layoutTick} />
        <SyncViewportTransition nodeId={highlightNodeId} />
        <Background variant={BackgroundVariant.Dots} gap={20} size={1} />
        {/* No `LockControl` here, unlike the ELK views. `layoutSequence` pins
            `draggable: false` on every lifeline and frame node it emits, and a
            per-node `draggable` outranks the graph-level `nodesDraggable`, so a
            lock control on this canvas would toggle a flag no node reads. The
            per-node pin is the contract: a message segment is drawn at a fixed
            row against its participant's column, and a moved lifeline leaves
            its own messages behind. `showInteractive={false}` retires React
            Flow's own padlock for the reason `LockControl` documents. */}
        <Controls position="bottom-left" showInteractive={false} />
      </ReactFlow>
    </NavigateContext.Provider>
  );
}
