/**
 * Guards panel — lists every transition guard in the current machine with its
 * evaluated value (true / false / undetermined) and undetermined-reason. Sits
 * in the simulation view's right column above the Trace. Each guard row
 * offers override controls when an `onOverrideChange` handler is provided.
 */
import React, { useState } from "react";
import type { GuardEval, GuardValue } from "./types";

const CHIP: Record<GuardValue, { bg: string; fg: string; label: string }> = {
  true:          { bg: "var(--vscode-charts-green, #89d185)", fg: "#1e1e1e", label: "true" },
  false:         { bg: "var(--vscode-charts-red, #f14c4c)",   fg: "#1e1e1e", label: "false" },
  undetermined:  { bg: "var(--vscode-charts-yellow, #cca700)",fg: "#1e1e1e", label: "undetermined" },
};

export function GuardsPanel({
  guards,
  overrides = {},
  onOverrideChange,
}: {
  guards: GuardEval[];
  overrides?: Record<string, boolean>;
  onOverrideChange?: (expression: string, value: boolean | undefined) => void;
}) {
  const [collapsed, setCollapsed] = useState(false);

  return (
    <div style={{ borderBottom: "1px solid var(--vscode-panel-border, #3e3e3e)" }}>
      <div
        onClick={() => setCollapsed(c => !c)}
        style={{
          cursor: "pointer", padding: "6px 10px", fontWeight: 600, fontSize: 10,
          textTransform: "uppercase", letterSpacing: "0.5px",
          color: "var(--vscode-sideBarSectionHeader-foreground, #ccc)",
        }}
      >
        {collapsed ? "▸" : "▾"} Guards
      </div>
      {!collapsed && (
        <div style={{ padding: "0 10px 6px" }}>
          {guards.length === 0 ? (
            <div style={{ fontStyle: "italic", fontSize: 11, color: "var(--vscode-editorLineNumber-foreground, #555)" }}>
              No guards in this machine.
            </div>
          ) : (
            guards.map(g => (
              <div key={g.edgeId} style={{ padding: "3px 0", fontSize: 11 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                  <span style={{
                    background: CHIP[g.value].bg, color: CHIP[g.value].fg,
                    borderRadius: 3, padding: "0 5px", fontSize: 10, whiteSpace: "nowrap",
                  }}>
                    {CHIP[g.value].label}
                  </span>
                  <code style={{ wordBreak: "break-word" }}>{g.expression}</code>
                </div>
                {onOverrideChange && (
                  <div style={{ display: "flex", gap: 4, paddingLeft: 4, marginTop: 2 }}>
                    {([
                      ["Auto", undefined],
                      ["force true", true],
                      ["force false", false],
                    ] as const).map(([label, val]) => {
                      const active = overrides[g.expression] === val
                        || (val === undefined && overrides[g.expression] === undefined);
                      return (
                        <button
                          key={label}
                          aria-label={label}
                          onClick={() => onOverrideChange(g.expression, val)}
                          style={{
                            fontSize: 9, padding: "0 4px", borderRadius: 2,
                            border: "1px solid var(--vscode-input-border, #555)",
                            background: active
                              ? "var(--vscode-list-activeSelectionBackground, #094771)"
                              : "transparent",
                            color: "var(--vscode-foreground, #ccc)", cursor: "pointer",
                          }}
                        >
                          {label}
                        </button>
                      );
                    })}
                  </div>
                )}
                {g.value === "undetermined" && g.reason && (
                  <div style={{ fontSize: 10, color: "var(--vscode-charts-yellow, #cca700)", paddingLeft: 4 }}>
                    {g.reason}
                  </div>
                )}
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
}
