/**
 * In-page LSP client over a message transport (the WASM worker).
 *
 * Owns JSON-RPC id correlation through a `pending` request map,
 * exposes `sendRequest` / `notify`, and fans server-initiated notifications out
 * to subscribers (for example `window/logMessage`).
 *
 * Transport-agnostic by design: it takes an `RpcTransport`, so it can be driven
 * by a real `Worker` in the browser or a mock in unit tests.
 */

export interface RpcTransport {
  /** Send one message to the server (worker). */
  post(msg: unknown): void;
  /** Register the inbound-message callback.  Called once by the client. */
  onMessage(cb: (msg: AnyMessage) => void): void;
}

export interface AnyMessage {
  jsonrpc?: string;
  id?: number | string | null;
  method?: string;
  params?: unknown;
  result?: unknown;
  error?: { code: number; message: string; data?: unknown };
}

export type NotificationHandler = (params: unknown) => void;

export type Dispose = () => void;

const REQUEST_TIMEOUT_MS = 15_000;
const INITIALIZE_TIMEOUT_MS = 60_000;

export interface LspClientOptions {
  /** Ordinary request budget. Override only in deterministic tests. */
  requestTimeoutMs?: number;
  /** Startup budget, including the one-time embedded-stdlib warmup. */
  initializeTimeoutMs?: number;
  /** Timer injection for deterministic timeout tests. */
  armTimeout?: (callback: () => void, delayMs: number) => Dispose;
}

export class LspClient {
  private nextId = 1;
  private readonly pending = new Map<
    number,
    { resolve: (v: unknown) => void; reject: (e: Error) => void; cancelTimeout: Dispose }
  >();
  private readonly handlers = new Map<string, Set<NotificationHandler>>();

  constructor(
    private readonly transport: RpcTransport,
    private readonly options: LspClientOptions = {},
  ) {
    transport.onMessage((msg) => this.receive(msg));
  }

  /** Send a request and resolve with its `result` (or reject on `error`). */
  sendRequest<T = unknown>(method: string, params?: unknown): Promise<T> {
    const id = this.nextId++;
    const timeoutMs = method === "initialize"
      ? (this.options.initializeTimeoutMs ?? INITIALIZE_TIMEOUT_MS)
      : (this.options.requestTimeoutMs ?? REQUEST_TIMEOUT_MS);
    return new Promise<T>((resolve, reject) => {
      const armTimeout = this.options.armTimeout
        ?? ((callback: () => void, delayMs: number) => {
          const handle = setTimeout(callback, delayMs);
          return () => clearTimeout(handle);
        });
      const cancelTimeout = armTimeout(() => {
        if (this.pending.has(id)) {
          this.pending.delete(id);
          reject(new Error(`LSP request '${method}' (id=${id}) timed out`));
        }
      }, timeoutMs);
      this.pending.set(id, { resolve: resolve as (v: unknown) => void, reject, cancelTimeout });
      this.transport.post({ jsonrpc: "2.0", id, method, params });
    });
  }

  /** Send a notification (no response expected). */
  notify(method: string, params?: unknown): void {
    this.transport.post({ jsonrpc: "2.0", method, params });
  }

  /** Subscribe to a server→client notification method. Returns a disposer. */
  onNotification(method: string, cb: NotificationHandler): Dispose {
    let set = this.handlers.get(method);
    if (!set) {
      set = new Set();
      this.handlers.set(method, set);
    }
    set.add(cb);
    return () => set!.delete(cb);
  }

  // ─────────────────────────── internals ───────────────────────────

  private receive(msg: AnyMessage): void {
    if (!msg || typeof msg !== "object") return;

    // Response to one of our requests.
    if (msg.id !== undefined && msg.id !== null && msg.method === undefined) {
      const entry = this.pending.get(msg.id as number);
      if (!entry) return;
      this.pending.delete(msg.id as number);
      entry.cancelTimeout();
      if (msg.error) entry.reject(new Error(msg.error.message));
      else entry.resolve(msg.result);
      return;
    }

    // Server→client request: we don't implement any, but must answer so the
    // server's progress/configuration round-trips don't dangle.
    if (msg.method !== undefined && msg.id !== undefined && msg.id !== null) {
      this.transport.post({ jsonrpc: "2.0", id: msg.id, result: null });
      // Still let subscribers observe it (e.g. for logging).
      this.emit(msg.method, msg.params);
      return;
    }

    // Notification.
    if (msg.method !== undefined) {
      this.emit(msg.method, msg.params);
    }
  }

  private emit(method: string, params: unknown): void {
    const set = this.handlers.get(method);
    if (!set) return;
    for (const cb of set) {
      try {
        cb(params);
      } catch (err) {
        // A faulty handler must not break dispatch.
        console.error(`[lsp-client] handler for '${method}' threw:`, err);
      }
    }
  }
}
