/**
 * Port node — a small square mounted on the *boundary* of its parent, matching
 * the SysML graphical notation (and the pilot's `portin`/`portout` rendering):
 * a port is a tiny square that straddles the parent's edge, not a free-floating
 * box. The layout pass parents the port to its owner and places it centred on
 * the correct side; this component only draws the square plus its name label.
 *
 * `data.side` is one of "WEST" | "EAST" | "NORTH" | "SOUTH" (the parent edge the
 * square sits on); the name label is pushed outward from that edge.
 */

import React from "react";
import { Handle, Position, type NodeProps } from "@xyflow/react";
import { formOf } from "./form";

type Side = "WEST" | "EAST" | "NORTH" | "SOUTH";

export function PortNode({ data, selected }: NodeProps) {
  const label = (data.label as string | undefined) ?? "";
  const side = (data.side as Side | undefined) ?? "WEST";
  // ARCH-4 semantic display fields: the wire label is creole-free; render
  // intent here (strikethrough noname, italic abstract, ^ inherited,
  // ~<short> ), matching DefaultNode's idiom.
  const nameSynthesized = data.nameSynthesized as boolean | undefined;
  const isAbstract = data.isAbstract as boolean | undefined;
  const isInherited = data.isInherited as boolean | undefined;
  const shortName = data.shortName as string | undefined;
  // Server-classified family, authoritative and shared with the CLI painters;
  // "default" is the wire's own fallback for a node with no family tint.
  const family = (data.family as string | undefined) ?? "default";
  const familyClass = ` fam-${family}`;

  // Direction cue (filled = in-flowing, hollow = out-flowing) — resolved
  // server-side into `data.filled` by `ViewNode::classify_filled`, so this
  // component reads the wire rather than re-deriving it from `kind`. Absent
  // ⇒ filled (the wire's own default for a node with no direction to draw).
  const filled = (data.filled as boolean | undefined) ?? true;

  // Name label sits just outside the parent edge the port is mounted on.
  const labelPos: React.CSSProperties =
    side === "NORTH" ? { bottom: "100%", left: "50%", transform: "translateX(-50%)", marginBottom: 2 }
    : side === "SOUTH" ? { top: "100%", left: "50%", transform: "translateX(-50%)", marginTop: 2 }
    : side === "EAST" ? { left: "100%", top: "50%", transform: "translateY(-50%)", marginLeft: 3 }
    : { right: "100%", top: "50%", transform: "translateY(-50%)", marginRight: 3 };

  return (
    <div
      className={`smlml-port-node${familyClass}${filled ? "" : " smlml-port-hollow"}`}
      data-form={formOf(data)}
      style={{ position: "relative", width: 14, height: 14 }}
    >
      <div
        className="smlml-port-square"
        title={label}
        style={{
          width: 14,
          height: 14,
          boxShadow: selected
            ? "0 0 0 2px var(--vscode-focusBorder, #0e639c)"
            : undefined,
        }}
      />
      {label && (
        <span
          className="smlml-port-label"
          style={{
            position: "absolute",
            ...labelPos,
            fontSize: 10,
            lineHeight: 1,
            whiteSpace: "nowrap",
            color: "var(--vscode-editor-foreground, #cccccc)",
            pointerEvents: "none",
            ...(nameSynthesized ? { textDecoration: "line-through" } : undefined),
            ...(isAbstract ? { fontStyle: "italic" } : undefined),
          }}
        >
          {isInherited ? "^" : ""}
          {shortName ? `~<${shortName}> ` : ""}
          {label}
        </span>
      )}
      {/* Hidden connection points on every side so connector edges can attach
          regardless of which border the port is mounted on. */}
      <Handle type="target" position={Position.Left}   style={{ opacity: 0 }} />
      <Handle type="source" position={Position.Right}  style={{ opacity: 0 }} />
      <Handle type="target" position={Position.Top}    id="t" style={{ opacity: 0 }} />
      <Handle type="source" position={Position.Bottom} id="b" style={{ opacity: 0 }} />
    </div>
  );
}
