/**
 * Minimal, dependency-free ZIP read/write for `.sysml` / `.kerml` workspaces.
 *
 * Ported from the editors/smlml-web prototype.  Reading handles both stored and
 * deflated entries (inflate via the platform `DecompressionStream`); writing
 * emits stored (uncompressed) entries, which are universally readable.  Uses
 * only web-platform globals (Blob, DataView, TextEncoder/Decoder, Response,
 * DecompressionStream) available in browsers and Node ≥ 18.
 */

export interface ZipEntry {
  path: string;
  text: string;
}

export interface UnzipResult {
  files: ZipEntry[];
  folders: string[];
}

async function inflateRaw(bytes: Uint8Array): Promise<string> {
  const stream = new Blob([bytes] as unknown as BlobPart[])
    .stream()
    .pipeThrough(new DecompressionStream("deflate-raw"));
  return await new Response(stream).text();
}

/** Parse a ZIP archive, returning `.sysml`/`.kerml` files and directory paths. */
export async function unzip(buf: ArrayBuffer): Promise<UnzipResult> {
  const u8 = new Uint8Array(buf);
  const dv = new DataView(buf);
  const td = new TextDecoder();
  let eocd = -1;
  for (let i = u8.length - 22; i >= 0; i--) {
    if (dv.getUint32(i, true) === 0x06054b50) {
      eocd = i;
      break;
    }
  }
  if (eocd < 0) throw new Error("not a zip");
  const count = dv.getUint16(eocd + 10, true);
  let p = dv.getUint32(eocd + 16, true);
  const files: ZipEntry[] = [];
  const folders = new Set<string>();
  for (let n = 0; n < count && dv.getUint32(p, true) === 0x02014b50; n++) {
    const method = dv.getUint16(p + 10, true);
    const compSize = dv.getUint32(p + 20, true);
    const nameLen = dv.getUint16(p + 28, true);
    const extraLen = dv.getUint16(p + 30, true);
    const commentLen = dv.getUint16(p + 32, true);
    const lho = dv.getUint32(p + 42, true);
    const name = td.decode(u8.subarray(p + 46, p + 46 + nameLen));
    const dataStart = lho + 30 + dv.getUint16(lho + 26, true) + dv.getUint16(lho + 28, true);
    const raw = u8.subarray(dataStart, dataStart + compSize);
    if (name.endsWith("/")) {
      const dir = name.replace(/\/+$/, "");
      if (dir) folders.add(dir);
    } else {
      const slash = name.lastIndexOf("/");
      if (slash > 0) folders.add(name.slice(0, slash));
      if (/\.(sysml|kerml)$/i.test(name)) {
        const text = method === 0 ? td.decode(raw) : method === 8 ? await inflateRaw(raw) : null;
        if (text != null) files.push({ path: name, text });
      }
    }
    p += 46 + nameLen + extraLen + commentLen;
  }
  return { files, folders: [...folders] };
}

const crcTable = (() => {
  const t: number[] = [];
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();

function crc32(buf: Uint8Array): number {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = (c >>> 8) ^ crcTable[(c ^ buf[i]) & 0xff];
  return (c ^ 0xffffffff) >>> 0;
}

/** Build a stored (uncompressed) ZIP Blob from files and (optionally) empty folders. */
export function zip(files: ZipEntry[], folders: string[] = []): Blob {
  const enc = new TextEncoder();
  const parts: Uint8Array[] = [];
  const central: Uint8Array[] = [];
  let offset = 0;
  const all: ZipEntry[] = [
    ...folders.map((d) => ({ path: d.replace(/\/?$/, "/"), text: "" })),
    ...files,
  ];
  for (const f of all) {
    const nb = enc.encode(f.path);
    const data = enc.encode(f.text);
    const crc = crc32(data);
    const lh = new DataView(new ArrayBuffer(30));
    lh.setUint32(0, 0x04034b50, true);
    lh.setUint16(4, 20, true);
    lh.setUint32(14, crc, true);
    lh.setUint32(18, data.length, true);
    lh.setUint32(22, data.length, true);
    lh.setUint16(26, nb.length, true);
    parts.push(new Uint8Array(lh.buffer), nb, data);
    const ch = new DataView(new ArrayBuffer(46));
    ch.setUint32(0, 0x02014b50, true);
    ch.setUint16(4, 20, true);
    ch.setUint16(6, 20, true);
    ch.setUint32(16, crc, true);
    ch.setUint32(20, data.length, true);
    ch.setUint32(24, data.length, true);
    ch.setUint16(28, nb.length, true);
    ch.setUint32(42, offset, true);
    central.push(new Uint8Array(ch.buffer), nb);
    offset += 30 + nb.length + data.length;
  }
  const cSize = central.reduce((s, a) => s + a.length, 0);
  const eo = new DataView(new ArrayBuffer(22));
  eo.setUint32(0, 0x06054b50, true);
  eo.setUint16(8, all.length, true);
  eo.setUint16(10, all.length, true);
  eo.setUint32(12, cSize, true);
  eo.setUint32(16, offset, true);
  return new Blob([...parts, ...central, new Uint8Array(eo.buffer)] as unknown as BlobPart[], {
    type: "application/zip",
  });
}

/** Trigger a browser download of `blob` as `name` (browser-only). */
export function download(blob: Blob, name: string): void {
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = name;
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 2000);
}
