/**
 * Canonical view palette — the web/TS half of the single source of truth.
 *
 * Imports the same `palette.json` the Rust side reads (`smlml_view::palette`),
 * so node-type hues are never forked into CSS/TS literals.
 *
 *   - `installFamilyPalette()` injects the `.smlml-cm-type .fam-* { --fam }`
 *     custom-property rules at runtime (instead of a hand-maintained block in
 *     theme.css).
 */
import palette from "../../../../../crates/smlml-view/palette.json";

type Palette = {
  family: Record<string, string>;
};

const PALETTE = palette as unknown as Palette;

/**
 * Inject the family-hue custom properties as a stylesheet, once per document.
 * Each family maps to `.smlml-cm-type .fam-<name> { --fam: <hue> }` — not
 * scoped to `.smlml-node`, because every node family stamps its own `fam-*`
 * class directly on whichever element it paints (`DefaultNode` on
 * `.smlml-node`, `StateNode` on `.smlml-state-node`, `PortNode` on
 * `.smlml-port-node`, and so on); the JS side owns the *value* of `--fam`,
 * theme.css owns which surfaces mix it in and by how much.
 */
export function installFamilyPalette(doc: Document = document): void {
  const ID = "smlml-family-palette";
  if (doc.getElementById(ID)) return;
  const rules = Object.entries(PALETTE.family)
    .map(
      ([fam, hue]) =>
        `.smlml-cm-type .fam-${fam}{--fam:${hue};}`,
    )
    .join("\n");
  const style = doc.createElement("style");
  style.id = ID;
  style.textContent = rules;
  doc.head.appendChild(style);
}

/**
 * The canonical family hues, for surfaces that must *explain* the colouring
 * rather than apply it (the legend). `installFamilyPalette` remains the way to
 * apply it; this export exists so the legend cannot hand-copy a hex value and
 * drift from `palette.json`.
 */
export const FAMILY_HUES: Readonly<Record<string, string>> = PALETTE.family;
