/** Shared React Flow camera effects used by every diagram kind. */

import { useEffect, useRef } from "react";
import { useReactFlow, type FitViewOptions } from "@xyflow/react";

const OVERVIEW_MS = 320;
const FOCUS_MS = 420;
const MAX_AUTO_ZOOM = 1.5;

/** A gentle acceleration/deceleration avoids a visible join between stages. */
export function syncEase(t: number): number {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}

function motionOptions(duration: number): Pick<FitViewOptions, "duration" | "ease" | "interpolate"> {
  return { duration, ease: syncEase, interpolate: "smooth" };
}

/** Fit the newly calculated graph after React Flow has committed its nodes. */
export function FitAfterLayout({ trigger }: { trigger: number }) {
  const { fitView } = useReactFlow();
  const previousTrigger = useRef(-1);

  useEffect(() => {
    if (trigger === previousTrigger.current) return;
    previousTrigger.current = trigger;
    const timer = setTimeout(() => fitView({ padding: 0.12, duration: 200 }), 60);
    return () => clearTimeout(timer);
  }, [trigger, fitView]);

  return null;
}

/**
 * Frame every search hit at once.
 *
 * Keyed on the sorted id list rather than the array identity, which is fresh
 * on every render. An empty result set is left alone: clearing the search box
 * should restore normal navigation, not move the viewport.
 */
export function FitToMatches({ nodeIds }: { nodeIds: string[] }) {
  const { fitView } = useReactFlow();
  const key = nodeIds.join("\u0000");
  const previousKey = useRef<string | undefined>(undefined);

  useEffect(() => {
    if (key === previousKey.current) return;
    previousKey.current = key;
    if (!nodeIds.length) return;
    void fitView({ nodes: nodeIds.map(id => ({ id })), padding: 0.25, duration: 300 });
    // `nodeIds` is represented by `key`; including its fresh array identity
    // would re-frame an unchanged result set on every render.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, fitView]);

  return null;
}

/**
 * Camera movement used by editor → diagram synchronization.
 *
 * A direct fit of a distant node makes the diagram appear to teleport. Keep
 * the old and new elements visible for the first half of the movement, then
 * settle on the new element. The shared React app is used by both the VS Code
 * webview and smlml-web, so this is the single implementation for both hosts.
 */
export function SyncViewportTransition({ nodeId }: { nodeId: string | undefined }) {
  const { fitView } = useReactFlow();
  const previousNode = useRef<string | undefined>(undefined);
  const sequence = useRef(0);

  useEffect(() => {
    const ticket = ++sequence.current;
    if (!nodeId || nodeId === previousNode.current) return;

    const fromNodeId = previousNode.current;
    previousNode.current = nodeId;

    const reducedMotion = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
    if (!fromNodeId || reducedMotion) {
      void fitView({
        nodes: [{ id: nodeId }],
        padding: 0.25,
        maxZoom: MAX_AUTO_ZOOM,
        ...motionOptions(reducedMotion ? 0 : FOCUS_MS),
      });
      return;
    }

    void (async () => {
      // Establish where the destination is relative to the element the user
      // was just reading before committing to the new close-up.
      await fitView({
        nodes: [{ id: fromNodeId }, { id: nodeId }],
        padding: 0.35,
        ...motionOptions(OVERVIEW_MS),
      });

      // A newer cursor event owns the camera now. Do not let the tail of an
      // older transition pull the reader back to a stale node.
      if (sequence.current !== ticket) return;
      await fitView({
        nodes: [{ id: nodeId }],
        padding: 0.25,
        maxZoom: MAX_AUTO_ZOOM,
        ...motionOptions(FOCUS_MS),
      });
    })();
  }, [nodeId, fitView]);

  return null;
}
