/**
 * Thin, total React-Flow painter — resolved EdgeStyle/NodeShape → marker ids,
 * dash pattern, stroke width, and node-component key.
 *
 * This is the only place that turns the wire's resolved appearance into React
 * Flow attributes; `layout.ts` calls it for every edge and node and adds only
 * the simulation overlays (fired highlight, guard stroke) on top. The `never`
 * defaults make a new Arrow/NodeShape variant a compile error here until it is
 * handled.
 *
 * Marker values are BARE ids: React Flow v12 wraps a string marker in
 * `url('#…')` itself, so returning `url(#id)` would double-wrap to
 * `url('#url(#id)')` and silently render no marker at all.
 *
 * Each `never` default THROWS rather than returning the value it was handed:
 * the `never` binding catches a new variant at compile time, and the throw
 * catches one that arrives at runtime from a newer server, instead of leaking
 * the raw wire token into a CSS dash pattern or a component key nobody has
 * registered.
 *
 * Which wire fields feed this painter (and the analogous DOT/SVG painters in
 * `smlml-cli`), and which each surface deliberately ignores, is ledgered in
 * `layout.vtest.ts`'s `CONSUMED`/`UNCONSUMED` tables on this side and in
 * `smlml-cli`'s `tests/wire_consumption.rs` on the Rust side.
 */
import type { Arrow, EdgeStyle, NodeShape } from "./types";
import { MARKER } from "./EdgeMarkers";

function arrowMarker(a: Arrow): string | undefined {
  switch (a) {
    case "none":            return undefined;
    case "triangle-hollow": return MARKER.triangleHollow;
    case "triangle-hollow-colon": return MARKER.triangleHollowColon;
    case "triangle-hollow-bar":   return MARKER.triangleHollowBar;
    case "arrow-filled":    return MARKER.arrowFilled;
    case "chevron-open":    return MARKER.chevronOpen;
    case "diamond-filled":  return MARKER.diamondFilled;
    case "diamond-hollow":  return MARKER.diamondHollow;
    case "circle-plus":     return MARKER.circlePlus;
    default: {
      const _exhaustive: never = a;
      throw new Error(`unhandled Arrow variant: ${String(_exhaustive)}`);
    }
  }
}

function dashArray(line: EdgeStyle["line"]): string | undefined {
  switch (line) {
    case "solid":  return undefined;
    case "dashed": return "6 4";
    case "dotted": return "2 3";
    default: {
      const _exhaustive: never = line;
      throw new Error(`unhandled Line variant: ${String(_exhaustive)}`);
    }
  }
}

/** Resolved React-Flow edge attributes for an [`EdgeStyle`]. */
export function edgeStyleMarkers(style: EdgeStyle): {
  markerStart?: string;
  markerEnd?: string;
  strokeDasharray?: string;
  strokeWidth: number;
} {
  return {
    markerStart: arrowMarker(style.tail),
    markerEnd: arrowMarker(style.head),
    strokeDasharray: dashArray(style.line),
    strokeWidth: style.thickness,
  };
}

/**
 * The key `layout.ts` maps to a registered node component. One per
 * [`NodeShape`]; `SHAPE_NODE_TYPE` in `layout.ts` is total over this union, so
 * a new key is a compile error there until it is given a component.
 */
export type NodeShapeKey =
  | "box"
  | "diamond"
  | "bar"
  | "circle"
  | "circleFinal"
  | "port"
  | "note";

/** Node-component key for a [`NodeShape`]; `layout.ts` maps it to a registry type. */
export function nodeShapeKey(shape: NodeShape): NodeShapeKey {
  switch (shape) {
    case "box":          return "box";
    case "diamond":      return "diamond";
    case "bar":          return "bar";
    case "circle":       return "circle";
    case "circle-final": return "circleFinal";
    case "port":         return "port";
    case "note":         return "note";
    default: {
      const _exhaustive: never = shape;
      throw new Error(`unhandled NodeShape variant: ${String(_exhaustive)}`);
    }
  }
}
