/**
 * Metamodel view — the resolved element graph as the engine stores it.
 *
 * Not an OMG diagram: it answers *which metaclass instances did this text
 * produce*, *how are they really owned*, and *what does each one hold*. The
 * spine is ownership, so the graph is a tree, and it is laid out with ELK's
 * `mrtree` — measured roughly 2× faster than the `layered` every other kind
 * uses, which is what makes the server's 4000-node budget affordable.
 *
 * Three things this painter composes that the wire deliberately does not:
 *
 *   - Guillemets. `stereotype` and an edge's `label` arrive as bare metaclass
 *     names; the display syntax is added here.
 *   - Cross-reference presentation. The server marks a reference edge
 *     `Dependency` and names the field storing it; dashing it and writing
 *     `«FeatureTyping» type` is this painter's language for that.
 *   - Every truncation placeholder's text, from the numbers it carries.
 *
 * ELK runs synchronously on the main thread, so a large layout is a freeze
 * rather than background work. Above `SLOW_LAYOUT_NODES` this view paints a
 * progress notice and yields to the browser before starting, so the pause is
 * announced rather than looking like a hang.
 */

import React, { useCallback, useEffect, useRef, useState } from "react";
import {
  ReactFlow,
  useNodesState,
  useEdgesState,
  useReactFlow,
  useStore,
  Background,
  BackgroundVariant,
  Controls,
  type Node,
  type Edge,
} from "@xyflow/react";
import type {
  ExpansionSnapshot,
  SourceRange,
  Truncation,
  ViewEdge,
  ViewModel,
  ViewNode,
} from "./types";
import { SLOW_LAYOUT_NODES, boundedBudget } from "./types";
import type { ExpandAmendment } from "./types";

export type { ExpandAmendment };
import type { EdgeRouting } from "./Diagram";
import { layoutViewModel, routingAlgorithm, type LayoutOptions } from "./layout";
import { EdgeMarkers } from "./EdgeMarkers";
import { EDGE_TYPES } from "./FloatingEdge";
import { NavigateContext } from "./NavigateContext";
import { LayoutFailureBanner } from "./LayoutFailureBanner";
import { NODE_TYPES } from "./nodes";
import { truncationLabel } from "./nodes/MetamodelNode";
import { FitAfterLayout, SyncViewportTransition } from "./ViewportTransitions";
import { useFontMetricEpoch } from "./font-metrics-lifecycle";


interface Props {
  model: ViewModel;
  routing: EdgeRouting;
  uri: string;
  onNavigate: (uri: string, range: SourceRange) => void;
  /** Amend the accumulated expansion set and re-request this view. */
  onExpand?: (request: ExpandAmendment) => void;
  /**
   * What the host's expansion set holds. Absent falls back to the response's
   * own `expanded` flag, which over-offers the collapse control.
   */
  expansion?: ExpansionSnapshot;
  /** Node id to scroll into view and pulse-highlight. */
  highlightNodeId?: string;
}

/** The truncation a node carries, or `undefined` for a real element. */
export function truncationOf(n: ViewNode): Truncation | undefined {
  return n.kind.type === "truncation" ? n.kind.truncation : undefined;
}

/**
 * A cross-reference edge: dashed, and named by both the relationship metaclass
 * and the field storing it.
 *
 * `Dependency` is the kind the builder uses for every non-structural reference;
 * `field` is what tells one apart from an ownership edge that also carries a
 * field (the `ownedRelationship` / `ownedRelatedElement` halves of a split
 * spine edge, which stay solid because they are still the spine).
 */
export function isCrossReference(e: ViewEdge): boolean {
  return e.kind.type === "dependency" && e.field !== undefined;
}

/** The edge text: `«Relationship» field` for a reference, `«Relationship»` otherwise. */
export function edgeText(e: ViewEdge): string | undefined {
  const rel = e.label ? `«${e.label}»` : undefined;
  if (isCrossReference(e)) return rel ? `${rel} ${e.field}` : e.field;
  return rel ?? e.field;
}

/**
 * The nearest node with a source range, walking up the ownership spine.
 *
 * A node the engine built with no distinct grammar rule behind it is not a
 * navigation target — there is nowhere to go — so the click lands on the
 * closest ancestor that does have a span rather than doing nothing.
 */
export function navigationTarget(
  model: ViewModel,
  id: string
): SourceRange | undefined {
  const byId = new Map(model.nodes.map(n => [n.id, n] as const));
  const ownerOf = new Map<string, string>();
  for (const e of model.edges) {
    if (e.kind.type === "containment") ownerOf.set(e.target, e.source);
  }
  const seen = new Set<string>();
  let cur: string | undefined = id;
  while (cur !== undefined && !seen.has(cur)) {
    seen.add(cur);
    const range = byId.get(cur)?.range;
    if (range) return range;
    cur = ownerOf.get(cur);
  }
  return undefined;
}

/**
 * Which affordance a click landed on, or `undefined` for the node's own box.
 *
 * A metamodel node is both a navigation target and the host of its expand and
 * collapse controls, and the builder marks most non-leaf elements
 * `expandable`. Dispatching on the node rather than on the control would make
 * graph→source navigation unreachable across the majority of the graph, so the
 * discriminator is the element actually clicked.
 */
export type ExpandControl = "expand" | "collapse";

export function controlAt(target: EventTarget | null): ExpandControl | undefined {
  const el = target instanceof Element ? target : null;
  if (el?.closest(".smlml-metamodel-expand")) return "expand";
  if (el?.closest(".smlml-metamodel-collapse")) return "collapse";
  return undefined;
}

/**
 * How a click amends the expansion set, or `undefined` when it does not — in
 * which case the click is a navigation.
 *
 *   - A `+N` placeholder adds the branch it stands for. `depth` stays absent,
 *     which the wire reads as unbounded.
 *   - The global placeholder switches to whole-graph mode at a bounded budget.
 *     Whole-graph is not an addition: the wire spells it as an *empty* node
 *     list, so adding to the set could never produce it.
 *   - The expand control adds this node's UUID; the collapse control removes
 *     it. A removal must never be sent as an empty `nodes` list — the server
 *     reads that as the whole graph, which is the maximum-cost opposite.
 *
 * A close is gated on `collapsible`, not on `expanded`: only an id the client's
 * set actually holds can be removed from it, and a request that removes nothing
 * re-renders the identical graph.
 */
export function expandRequestFor(
  data: {
    truncation?: Truncation;
    expandable?: boolean;
    expanded?: boolean;
    collapsible?: boolean;
    elementId?: string;
  },
  fallbackId: string,
  control?: ExpandControl
): ExpandAmendment | undefined {
  const t = data.truncation;
  if (t) {
    // A placeholder is nothing but its control — the whole box is the target.
    return t.affordance === "branch"
      ? { add: [t.parent] }
      : { all: true, budget: boundedBudget(t.total) };
  }
  if (!control) return undefined;
  const id = data.elementId ?? fallbackId;
  if (control === "expand") return data.expandable ? { add: [id] } : undefined;
  return (data.collapsible ?? data.expanded) ? { remove: [id] } : undefined;
}

/**
 * A copy of the model with each placeholder's composed text as its `label`.
 *
 * The wire sends placeholders with an empty label and the numbers separately.
 * Sizing measures `label`, so the text has to exist before layout or ELK
 * reserves a box too small for what gets painted into it.
 */
function withPlaceholderLabels(model: ViewModel): ViewModel {
  if (!model.nodes.some(truncationOf)) return model;
  return {
    ...model,
    nodes: model.nodes.map(n => {
      const t = truncationOf(n);
      return t ? { ...n, label: truncationLabel(t) } : n;
    }),
  };
}

/**
 * Floor on the zoom `revealViewport` may widen to — the same floor the pane
 * enforces, so a reveal can never leave the view at a zoom the user could not
 * have reached by pinching.
 */
const MIN_ZOOM = 0.1;

/** A rectangle in flow coordinates. */
export interface Rect { x: number; y: number; width: number; height: number }

/**
 * The viewport that holds `anchor` still while the graph re-lays out under it.
 *
 * An expansion is an amendment to a graph the user is already reading, but ELK
 * re-runs over the whole tree and answers with new coordinates for everything —
 * so "keep the viewport" and "keep your place" are different things. The node
 * whose control was clicked is the one place the user demonstrably is, so the
 * pan is whatever cancels *its* movement, and the zoom is not touched at all.
 */
export function anchoredViewport(
  vp: { x: number; y: number; zoom: number },
  before: { x: number; y: number },
  after: { x: number; y: number }
): { x: number; y: number; zoom: number } {
  return {
    x: vp.x - (after.x - before.x) * vp.zoom,
    y: vp.y - (after.y - before.y) * vp.zoom,
    zoom: vp.zoom,
  };
}

/** Whether any part of `r` is inside the `w`×`h` screen under viewport `vp`. */
export function isOnScreen(
  r: Rect,
  vp: { x: number; y: number; zoom: number },
  w: number,
  h: number
): boolean {
  const left = r.x * vp.zoom + vp.x;
  const top = r.y * vp.zoom + vp.y;
  return left + r.width * vp.zoom > 0 && left < w && top + r.height * vp.zoom > 0 && top < h;
}

/**
 * The viewport that brings `bounds` into view without ever zooming in.
 *
 * Reached only when an expansion put its new nodes off-screen. It centres on
 * the union of the anchor and the new material and takes `min(current, fitted)`
 * as the zoom, so the view can widen to show what appeared but never jumps
 * closer than where the user had it — a zoom-in would be the same lost place
 * the whole-graph fit was.
 */
export function revealViewport(
  vp: { x: number; y: number; zoom: number },
  bounds: Rect,
  w: number,
  h: number,
  minZoom: number,
  padding = 0.15
): { x: number; y: number; zoom: number } {
  const pad = 1 + padding;
  const fitted = Math.min(
    w / Math.max(bounds.width * pad, 1),
    h / Math.max(bounds.height * pad, 1)
  );
  const zoom = Math.max(minZoom, Math.min(vp.zoom, fitted));
  return {
    x: w / 2 - (bounds.x + bounds.width / 2) * zoom,
    y: h / 2 - (bounds.y + bounds.height / 2) * zoom,
    zoom,
  };
}

/** The union of `rects`, or `undefined` when there are none. */
export function unionOf(rects: Rect[]): Rect | undefined {
  if (rects.length === 0) return undefined;
  const x1 = Math.min(...rects.map(r => r.x));
  const y1 = Math.min(...rects.map(r => r.y));
  const x2 = Math.max(...rects.map(r => r.x + r.width));
  const y2 = Math.max(...rects.map(r => r.y + r.height));
  return { x: x1, y: y1, width: x2 - x1, height: y2 - y1 };
}

/**
 * Shown while a layout above {@link SLOW_LAYOUT_NODES} runs.
 *
 * It says the editor will stop responding because it will: ELK holds the main
 * thread for the whole pass, so this notice is the last frame the browser gets
 * to paint until the layout returns.
 */
function LayoutProgress({ count }: { count: number }) {
  return (
    <div
      role="status"
      className="smlml-metamodel-progress"
      style={{
        position: "absolute",
        inset: 0,
        zIndex: 20,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        gap: 6,
        background: "var(--vscode-editor-background, #1e1e1e)",
        color: "var(--vscode-descriptionForeground, #999)",
      }}
    >
      <div style={{ fontWeight: 600 }}>Laying out {count} nodes…</div>
      <div style={{ fontSize: 12 }}>
        Layout runs on the UI thread — the editor will not respond until it
        finishes.
      </div>
    </div>
  );
}

export function MetamodelFlowView({
  model,
  routing,
  uri,
  onNavigate,
  onExpand,
  expansion,
  highlightNodeId,
}: Props) {
  const fontMetricEpoch = useFontMetricEpoch();
  const [nodes, setNodes, onNodesChange] = useNodesState<Node>([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState<Edge>([]);
  const [layoutTick, setLayoutTick] = useState(0);
  const [layoutFailed, setLayoutFailed] = useState<Error | undefined>(undefined);
  const [pending, setPending] = useState<number | undefined>(undefined);
  /** Ids revealed by the last expansion, pulsed so they can be found. */
  const [revealed, setRevealed] = useState<ReadonlySet<string>>(() => new Set());
  const { fitView, getViewport, setViewport, getNodes } = useReactFlow();
  // The flow's own pixel size, for deciding whether the new material landed
  // outside the view. Read from React Flow's store rather than a wrapper ref:
  // the store already holds the measured size of the pane these nodes are
  // drawn in, and a second measurement could only disagree with it.
  const paneW = useStore(st => st.width);
  const paneH = useStore(st => st.height);
  const paneRef = useRef({ w: paneW, h: paneH });
  paneRef.current = { w: paneW, h: paneH };

  /**
   * The node whose control was clicked, and where it sat when it was — the
   * anchor the next layout is held against. Set by the click, consumed by the
   * layout it caused, and `undefined` for a layout nobody asked for (first
   * load, file change, routing change), which still fits the whole graph.
   */
  const anchorRef = useRef<{ id: string; x: number; y: number } | undefined>(undefined);
  /** Node ids the previous layout drew, to tell an expansion's additions apart. */
  const drawnRef = useRef<ReadonlySet<string>>(new Set());

  useEffect(() => {
    let cancelled = false;
    const slow = model.nodes.length > SLOW_LAYOUT_NODES;
    setPending(slow ? model.nodes.length : undefined);

    const run = async () => {
      const opts: LayoutOptions = {
        direction: "DOWN",
        edgeRouting: routingAlgorithm(routing),
        // Ownership is drawn as edges, never as nesting: the spine already
        // states it once, and box-in-box would state it a second time in a
        // notation that could disagree.
        containment: "edge",
        algorithm: "mrtree",
        // These boxes are `MetamodelNode`s, not OMG element boxes — see
        // `LayoutOptions.variant`.
        variant: "metamodel",
      };
      const laid = await layoutViewModel(withPlaceholderLabels(model), opts);
      if (cancelled) return;
      const anchor = anchorRef.current;
      anchorRef.current = undefined;
      const previously = drawnRef.current;
      drawnRef.current = new Set(laid.nodes.map(n => n.id));

      setNodes(decorateNodes(laid.nodes, model, expansion));
      setEdges(decorateEdges(laid.edges, model));
      setLayoutFailed(laid.layoutFailed);
      setPending(undefined);

      // A layout the user did not ask for (first paint, a new file, a routing
      // change) frames the whole graph; one caused by their own click holds
      // their place instead. `layoutTick` is what `FitAfterLayout` watches, so
      // not bumping it *is* how the fit is suppressed.
      const held = anchor && holdPlace(anchor, laid.nodes, previously);
      if (!held) {
        setRevealed(new Set());
        setLayoutTick(t => t + 1);
      }
    };

    /**
     * Keep the clicked node under the pointer, pulse what appeared, and widen
     * the view only if what appeared landed outside it. Returns false when the
     * anchor did not survive the re-layout, which puts the fit back.
     */
    const holdPlace = (
      anchor: { id: string; x: number; y: number },
      laidNodes: Node[],
      previously: ReadonlySet<string>
    ): boolean => {
      const after = laidNodes.find(n => n.id === anchor.id);
      if (!after) return false;
      const vp = anchoredViewport(getViewport(), anchor, after.position);
      setViewport(vp);

      const fresh = laidNodes.filter(n => !previously.has(n.id));
      setRevealed(new Set(fresh.map(n => n.id)));
      if (fresh.length === 0) return true;

      const rectOf = (n: Node): Rect => ({
        x: n.position.x,
        y: n.position.y,
        width: (n.style?.width as number | undefined) ?? (n.measured?.width ?? 0),
        height: (n.style?.height as number | undefined) ?? (n.measured?.height ?? 0),
      });
      const { w, h } = paneRef.current;
      if (w === 0 || h === 0) return true;
      if (fresh.some(n => isOnScreen(rectOf(n), vp, w, h))) return true;

      const bounds = unionOf([rectOf(after), ...fresh.map(rectOf)]);
      if (bounds) setViewport(revealViewport(vp, bounds, w, h, MIN_ZOOM), { duration: 300 });
      return true;
    };

    if (!slow) {
      void run();
      return () => { cancelled = true; };
    }
    // Hand the browser a frame to paint the notice into before ELK takes the
    // thread. Without the yield the notice and the result land in the same
    // commit and it is never seen.
    const id = setTimeout(() => { void run(); }, 0);
    return () => { cancelled = true; clearTimeout(id); };
  }, [model, routing, expansion, fontMetricEpoch, setNodes, setEdges]);

  // The pulse is a pulse: `.smlml-node-highlight` paints a focus-blue border
  // and fill for as long as it is on the node (only its animation is timed), so
  // leaving the class on everything an expansion revealed would recolour a
  // third of the graph permanently. 1.2s is the animation's own length, the
  // same one the cursor highlight in `Diagram` clears itself after.
  useEffect(() => {
    if (revealed.size === 0) return;
    const id = setTimeout(() => setRevealed(new Set()), 1200);
    return () => clearTimeout(id);
  }, [revealed]);

  const handleNodeClick = useCallback(
    (event: React.MouseEvent, node: Node) => {
      const request = expandRequestFor(node.data ?? {}, node.id, controlAt(event.target));
      if (request) {
        // Where this node sits *now* is what the layout it triggers will be
        // held against. Read from the live store rather than the event's node,
        // which carries the position it was rendered with.
        const live = getNodes().find(n => n.id === node.id) ?? node;
        anchorRef.current = { id: node.id, x: live.position.x, y: live.position.y };
        onExpand?.(request);
        return;
      }
      const range = navigationTarget(model, node.id);
      if (range) onNavigate(uri, range);
    },
    [model, onExpand, onNavigate, uri, getNodes]
  );

  const handleEdgeClick = useCallback(
    (_: React.MouseEvent, edge: Edge) => {
      fitView({ nodes: [{ id: edge.source }, { id: edge.target }], padding: 0.3, duration: 300 });
    },
    [fitView]
  );

  // Two independent reasons to pulse: the editor cursor landed on this node,
  // or an expansion just revealed it. Same class — it is the same "look here".
  const displayNodes = nodes.map(n =>
    n.id === highlightNodeId || revealed.has(n.id)
      ? { ...n, className: (n.className ? n.className + " " : "") + "smlml-node-highlight" }
      : n
  );

  return (
    <NavigateContext.Provider value={{ navigate: onNavigate, uri }}>
      <LayoutFailureBanner error={layoutFailed} />
      {pending !== undefined && <LayoutProgress count={pending} />}
      <ReactFlow
        nodes={displayNodes}
        edges={edges}
        nodeTypes={NODE_TYPES}
        edgeTypes={EDGE_TYPES}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onNodeClick={handleNodeClick}
        onEdgeClick={handleEdgeClick}
        fitView
        minZoom={MIN_ZOOM}
        maxZoom={4}
        nodesDraggable
        nodesConnectable={false}
      >
        <EdgeMarkers />
        <FitAfterLayout trigger={layoutTick} />
        <SyncViewportTransition nodeId={highlightNodeId} />
        <Background variant={BackgroundVariant.Dots} gap={20} size={1} />
        <Controls position="bottom-left" />
      </ReactFlow>
    </NavigateContext.Provider>
  );
}

// ─────────────────────────── Wire → React Flow ───────────────────────────────

/**
 * Route every node to `MetamodelNode` and forward the fields the shared
 * pipeline does not carry.
 *
 * `layout.ts` maps `form`/`shape` onto the OMG node components and forwards the
 * `data` those need; this kind's fields (`element_id`, `has_source`,
 * `expandable`, `expanded`, and the truncation payload) are read by no other
 * view, so they are attached here rather than widening that mapping for one
 * kind's benefit.
 */
export function decorateNodes(
  laid: Node[],
  model: ViewModel,
  expansion?: ExpansionSnapshot
): Node[] {
  const byId = new Map(model.nodes.map(n => [n.id, n] as const));
  const open = expansion ? new Set(expansion.nodes) : undefined;
  const openEverything = expansion?.all ?? false;
  return laid.map(n => {
    const src = byId.get(n.id);
    if (!src) return n;
    const expanded = src.expanded ?? false;
    const elementId = src.element_id;
    // Every drawn descendant of an opened node comes back `expanded`, so that
    // flag says the node *is* open, not that closing it would do anything. A
    // close names one id and removes it from the client's set; on a node the
    // set never held it removes nothing and the identical graph re-renders.
    const collapsible =
      open === undefined
        ? expanded
        : expanded && (openEverything || open.has(elementId ?? n.id));
    return {
      ...n,
      type: "metamodel",
      data: {
        ...n.data,
        elementId,
        hasSource: src.has_source ?? true,
        expandable: src.expandable ?? false,
        expanded,
        collapsible,
        truncation: truncationOf(src),
      },
    };
  });
}

/** Dash the cross-references and write both the relationship and the field on them. */
export function decorateEdges(laid: Edge[], model: ViewModel): Edge[] {
  const byId = new Map(model.edges.map(e => [e.id, e] as const));
  return laid.map(e => {
    const src = byId.get(e.id);
    if (!src) return e;
    return {
      ...e,
      label: edgeText(src),
      style: isCrossReference(src)
        ? { ...e.style, strokeDasharray: "6 4" }
        : e.style,
    };
  });
}
